(window.GIM_TS=window.GIM_TS||{})["Ketubot.8"]={"from":192,"a":[["\u0003\"בבתוליה\"\u0004 כוונתו \u0003שיהו כל בתוליה קיימין\u0004 שלא נבעלה כלל, \u0003בין בכדרכה בין שלא כדרכה.\u0004 ואם כן, אין זה שייך לבעיה לגבי \"מקצת כסף ככל כסף\".","מסופר: \u0003ההיא איתתא דתפסה כסא דכספא\u0004 \u0005[אשה אחת שתפסה כוס כסף]\u0006 מנכסי היתומים לשם גביית חלק מ\u0003כתובתה, קתבעה מזוני\u0004 \u0005[\u0006ו\u0005תבעה מזונות].\u0006 \u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רבא\u0004 לדין. \u0003אמר להו ליתמי\u0004 \u0005[להם ליתומים]:\u0006 \u0003זילו הבו\u0004 \u0005[לכו תנו]\u0006 \u0003לה מזונות,\u0004 כי \u0003לית דחש להא\u0004 \u0005[אין\u0006 מי \u0005שחושש לזו]\u0006 שאמר \u0003ר' שמעון,\u0004 ש\u0003אמר: לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מקצת כסף ככל כסף.\u0004","\u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב יוסף\u0004 שאלה זו: \u0003מוכרת שלא בבית דין,\u0004 האם היא \u0003צריכה שבועה\u0004 שלא נטלה יותר מן הראוי לה, \u0003או אין צריכה שבועה?\u0004 החזיר לו רב יוסף: \u0003ותבעי\u0004 \u0005[ותישאל]\u0006 \u0003לך\u0004 אם צריכה \u0003הכרזה,\u0004 שעוד טרם המכירה יעשו הכרזה פומבית כדי להעריך כראוי את שווי הנכסים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 בענין \u0003הכרזה לא קמיבעיא\u0004 \u0005[מסופק]\u0006 \u0003לי,\u0004 שהרי \u0003אמר ר' זירא אמר רב נחמן: אלמנה ששמה\u0004 (העריכה) את הנכסים ונטלה אותם \u0003לעצמה\u0004 כפרעון כתובתה לפי חשבון זה — \u0003לא עשתה ולא כלום.\u0004","ומעתה יש לברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאכרוז\u0004 \u0005[אם שהכריזו]\u0006 והגיעו לקביעת סכום מסויים לנכסים — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא עשתה ולא כלום?\u0004 שדינה הלא ככל קונה אחר! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר ש\u0003לא אכרוז\u0004 \u0005[הכריזו],\u0006 \u0003ו\u0004מכאן נלמד שאם מכרה \u0003לעצמה הוא שלא עשתה ולא כלום, הא\u0004 \u0005[הרי]\u0006 אם מכרה \u0003לאחר — מה שעשתה עשתה.\u0004 למרות שלא היתה הכרזה.","ודוחים: \u0003לעולם\u0004 מדובר \u0003דאכרוז\u0004 \u0005[שהכריזו],\u0006 ודאמרי \u0005[ושאומרים]\u0006 \u0003לה: מאן שם ליך\u0004 \u0005[מי העריך לך]?\u0006 שאף על פי שהדבר נעשה בפומבי, בכל אופן הערכה לא היתה כאן.","\u0003כי האי\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דההוא גברא דאפקידו גביה כיסתא דיתמי\u0004 \u0005[שאדם אחד שהפקידו אצלו אלמוגים של יתומים].\u0006 \u0003אזל שמה לנפשיה בארבע מאה זוזי\u0004 \u0005[הלך העריך\u0006 את האלמוגים \u0005לעצמו בארבע מאות זוז]\u0006 ולקחם לעצמו. \u0003אייקר קם בשית מאה\u0004 \u0005[התייקר\u0006 מה שהיה בכיס \u0005ועמד בשש מאות].\u0006","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 לשאול, למי מגיע רווח זה, לו או ליתומים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אמי: \u0003מאן שם\u0004 \u0005[מי העריך]\u0006 \u0003לך\u0004 שיתיר לך למכור? ומאחר ואתה הוא שהערכת לעצמך לכן מכירתך לא היתה כדין, ונשארו האלמוגים ברשות היתומים, והרווח שלהם.","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003צריכה שבועה ואינה צריכה הכרזה.\u0004","\u0003אלמנה שהיתה כתובתה מאתים, ומכרה שוה מנה\u0004 מן הנכסים \u0003במאתים, או שוה מאתים\u0004 מן הנכסים וקיבלה רק \u0003במנה\u0004 — הרי זו \u0003נתקבלה כתובתה,\u0004 ואין לה תביעה נוספת.","\u0003היתה כתובתה מנה, ומכרה שוה מנה ודינר במנה — מכרה בטל,\u0004 שהרי נמצא שמכרה נכסים שלא היו שייכים לה. \u0003אפילו היא אומרת אחזיר דינר\u0004 עודף זה \u0003ליורשין\u0004 — בכל זאת \u0003מכרה בטל.\u0004","\u0003רבן שמעון בן גמליאל אומר: לעולם מכרה קיים, עד שתהא שם\u0004 הטעות במכר בגודל כזה \u0003כדי שתשייר בשדה בת תשעה קבין,\u0004 שאם לא היתה טועה היה נשאר בשדה שיעור זה, שהוא השיעור הקטן ביותר של שדה הראוי לעיבוד, שאז יכולים היתומים לטעון שאין רצונם לוותר על שדה השייך להם. אבל אם שיעור הטעות פחות מזה — די אם תחזיר ליתומים. \u0003ובגנה\u0004 שיעור הטעות שאם טעתה בכך אין די במה שתחזיר ליתומים — כל שבשל טעותה לא נותרה גינה \u0003בת חצי קב\u0004 שהוא השיעור הקטן ביותר לגינה הראויה לעיבוד, או \u0003כדברי ר' עקיבא\u0004 בגינה \u0003בית רובע.\u0004","\u0003היתה כתובתה ארבע מאות זוז ומכרה לזה,\u0004 לאדם אחד קרקע ששווייה מנה \u0003במנה, ולזה,\u0004 לאחר, קרקע ששווייה מנה \u0003במנה,\u0004 וכן לשלישי, \u0003ולאחרון\u0004 מכרה מה שהיה \u0003יפה\u0004 (שווה) \u0003מנה ודינר במנה\u0004 בלבד — המכר \u0003של אחרון בטל, ושל כולן מכרן קיים,\u0004 שהרי מכרה במחיר הנכון.","על ההלכה הראשונה במשנה שאם מכרה שווה מאתים במנה או מנה במאתים אין לה עוד תביעה לכתובה, שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 כשמכרה \u0003שוה מאתים במנה\u0004 שאינה נוטלת כתובתה — \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003לה\u0004 היורשים: \u0003את אפסדת\u0004 \u0005[הפסדת]\u0006 לעצמך, שלא ידעת למכור כראוי, ונטלת מן הנכסים את השיעור הראוי לך, אולם אם מכרה \u0003שוה מנה במאתים, נמי תימא\u0004 \u0005[גם כן תאמר\u0006 היא\u0005]:\u0006 \u0003אנא ארווחנא\u0004 \u0005[אני הרווחתי]\u0006 ומשלכם לא נטלתי אלא שווה מנה, ומגיע לי איפוא עוד שווה מנה!","\u0003אמר רב נחמן אמר רבה בר אבוה:\u0004"],["\u0003כאן שנה רבי,\u0004 כלומר, במשנה זו אנחנו למדים ששיטת רבי היא ש\u0003הכל לבעל המעות,\u0004 כלומר, בעל המעות שהגיע לו רווח על ידי שליח — כל הרווח שלו. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 שבה נחלקו חכמים בבעיה זו: מי ששלח שליח לשוק לקנות סחורה בסכום מסויים ו\u0003הוסיפו לו\u0004 חתיכה \u0003אחת יתירה\u0004 על הכמות הראויה, הרי \u0003הכל\u0004 (כל הרווח) \u0003לשליח,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר; חולקין\u0004 בין השליח ובין בעל הבית.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יוסי אומר: הכל לבעל המעות! אמר רמי בר חמא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 ששנינו בשם ר' יוסי שחולקים בין השליח ובעל הבית, מדובר \u0003בדבר שיש לו קצבה,\u0004 שיש מחיר קצוב לאותם חפצים, ואם הוסיף המוכר, הרי זה בגדר מתנה, שספק אם נתן אותה לשליח או שנתן לבעל הבית, ואילו \u0003כאן\u0004 ששנינו משמו כי הכל לבעל הבית, מדובר \u0003בדבר שאין לו קצבה\u0004 ולכן יש לומר שההוספה לא היתה עבור השליח, אלא הוסיף המוכר עבור העיסקה עצמה, ואם כן הכל לבעל המעות.","\u0003אמר רב פפא: הלכתא\u0004 \u0005[ההלכה\u0006 היא\u0005]:\u0006 \u0003דבר שיש לו קצבה — חולקין, דבר שאין לו קצבה — הכל לבעל המעות.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא הוא מה שאמר רמי בר חמא! ומסבירים: רצה לומר ש\u0003שינויא דשנינן שינויא\u0004 \u0005[התירוץ שתירצנו, תירוץ\u0006 אמיתי\u0005]\u0006 \u0003הוא,\u0004 ועל פיו אפשר לפסוק גם הלכה למעשה.","איבעיא להו \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשליח: \u0003זבין\u0004 \u0005[מכור]\u0006 \u0003לי,\u0004 עבורי, \u0003ליתכא\u0004 \u0005[לתך]\u0006 שהוא חצי כור, \u0003ואזל וזבין ליה כורא\u0004 \u0005[והלך ומכר לו כור\u0006 שלם\u0005],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם נאמר כי \u0003מוסיף על דבריו הוא,\u0004 שחצי המעשה נעשה כדין, אלא שהוסיף דבר שלא היתה רשות בידו לעשותו, \u0003ו\u0004לכן \u0003ליתכא מיהא קני\u0004 \u0005[הלתך בכל אופן קנוי],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מעביר על דבריו הוא,\u0004 שכיון שלא עשה בדיוק כדבריו, הרי זה כאילו עשה הכל מדעת עצמו ובלא רשות כלל, \u0003וליתכא נמי\u0004 \u0005[ולתך גם כן]\u0006 \u0003לא קני\u0004 \u0005[קנה]\u0006 הקונה?","\u0003אמר רב יעקב מנהר פקוד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ששנינו בדיני מעילה בקדשים, \u0003אמר בעל הבית לשלוחו: \"תן להן חתיכה\u0004 אחת של בשר \u0003לאורחין\" והוא\u0004 השליח \u0003אומר\u0004 לאורחים: \u0003\"טלו שתים\", והן נטלו שלש,\u0004 ולבסוף התברר שהחתיכות הללו היו בשר של הקדש — הרי \u0003כולן מעלו\u0004 בהקדש.","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי השליח \u0003מוסיף על דבריו הוי\u0004 \u0005[הוא]\u0006 נחשב — \u0003משום הכי\u0004 \u0005[כך]\u0006 מובן מדוע גם \u0003בעל הבית מעל,\u0004 שהשליח שאמר \"שתיים\", אחת מהן היתה בשליחות בעל הבית. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003מעביר על דבריו הוי\u0004 \u0005[הוא] —\u0006 \u0003בעל הבית אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעל? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003השליח שעשה שליחותו\u0004 של המשלח כלשונה וגרם למעילה בהקדש — \u0003בעל הבית\u0004 ששלחו הוא ש\u0003מעל,\u0004 ואם \u0003לא עשה שליחותו\u0004 אלא שינה מן הדברים — \u0003שליח\u0004 הוא ש\u0003מעל,\u0004 ולא בעל הבית!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 כגון באופן \u0003דאמר להו\u0004 \u0005[שאומר להם\u0006 השליח\u0005]\u0006 במפורש לאורחים: \u0003\"טלו אחת מדעתו של בעל הבית, ואחת מדעתי\", ושקלו אינהו תלת\u0004 \u0005[ולקחו הם שלוש],\u0006 שנמצא שכל אחת מן החתיכות ניטלה לדעת אחרת, ולכן כולם מעלו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003היתה כתובתה מנה ומכרה שוה מנה ודינר במנה — מכרה בטל.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003דזבין\u0004 \u0005[שמכרה]\u0006 \u0003שוה מנה ודינר במנה ודינר,\u0004 שלא היתה טעות בעצם המכירה \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"במנה\"\u0004 שאמרו — כוונתו \u0003מנה שלה,\u0004 בשביל המנה שהיה ראוי לה בכתובתה. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 במשנה \u0003\"אפילו\"? — אפילו היא אומרת \"אחזיר את הדינר ליורשים בדינר מקרקעי\u0004 \u0005[קרקעות]\u0006 \u0003\",\u0004 שתחזיר קרקע שוה דינר ליורשים, שאז לא ייפסדו כלום, \u0003וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003מכרה בטל,\u0004 משמע שאנו אומרים שלא רק מה שהוסיפה בטל אלא כל המכר בטל.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן: לא,\u0004 פירוש הדברים במשנה הוא שלא מכרה את הנכס בשוויו אלא \u0003בדאוזיל\u0004 \u0005[שהוזילה]\u0006 מן המחיר, ומכרה בפחות מן השווי, והיתה טעות במכירה עצמה."],["\u0003הא מדסיפא בדאוזיל\u0004 \u0005[הרי מ\u0006כיון \u0005ש\u0006ב\u0005סוף\u0006 המשנה מדובר \u0005בשהוזילה]\u0006 היא מן המחיר, \u0003הוי רישא\u0004 \u0005[הרי ראשה]\u0006 של המשנה מדברת \u0003ב\u0004כש\u0003לא אוזיל\u0004 \u0005[הוזילה],\u0006 שהרי אין המשנה כופלת סתם את דבריה. \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003היתה כתובתה ארבע מאות זוז, מכרה לזה במנה, ולזה במנה, ולאחרון יפה מנה ודינר במנה — של אחרון מכרה בטל, ושל כולן מכרן קיים,\u0004 והרי שלא כל המכר בטל!","ודוחים: \u0003לא, רישא וסיפא\u0004 \u0005[\u0006גם ב\u0005ראשה ו\u0006גם ב\u0005סופה\u0006 של המשנה\u0005]\u0006 מדובר \u0003בדאוזיל\u0004 \u0005[בשהוזילה]\u0006 מן המחיר הראוי, \u0003וסיפא הא קא משמע לן\u0004 \u0005[והסוף,\u0006 דבר \u0005זה השמיע לנו]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 שהמכר בטל, הוא דווקא \u0003דאוזיל בדיתמי\u0004 \u0005[\u0006כ\u0005שהוזילה בשל היתומים],\u0006 שלאחר שגבתה את כל כתובתה הוזילה בתשלום האחרון על חשבון היתומים, \u0003אבל\u0004 כשהוזילה \u0003בדידה\u0004 \u0005[בשלה]\u0006 בפעמים הראשונות — \u0003מכרה קיים.\u0004","ומקשים: \u0003הא מדרישא שמעת מינה\u0004 \u0005[\u0006דבר \u0005זה מראשה\u0006 של המשנה אתה שומע אותו\u0005],\u0006 ששנינו: \u0003היתה כתובתה מאתים ומכרה שוה מנה במאתים, או שוה מאתים במנה — נתקבלה כתובתה.\u0004 הרי אף כשהוזילה בשלה עד כדי מחצית השווי, מכרה קיים!","ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הדין כן \u0003הוא,\u0004 משום \u0003דאיסתלקא\u0004 \u0005[שהסתלקה]\u0006 \u0003לה מהאי ביתא\u0004 \u0005[מאותו בית]\u0006 \u0003לגמרי,\u0004 כלומר, שעל ידי מכירה זו נגמרה כל תביעתה, ושוב אין לה עוד קשר עם ירושת בעלה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003ניגזור\u0004 כבר ביחס ל\u0003מנה\u0004 ה\u0003ראשון\u0004 שתתבטל המכירה \u0003אטו\u0004 \u0005[משום]\u0006 \u0003מנה אחרון,\u0004 שמאחר שבאחרון מכרה בטל — בטל גם בראשון, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך היכא\u0004 \u0005[היכן]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבית לשליח: \u0003\"זיל זבין\u0004 \u0005[לך מכור]\u0006 \u0003לי ליתכא\u0004 \u0005[לתך]\u0006 \u0003\" וזבין ליה כורא\u0004 \u0005[ומכר לו כור],\u0006 ש\u0003ודאי מוסיף על דבריו הוי\u0004 \u0005[הוא]\u0006 ולגבי הלתך מכירתו קיימת.","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 הרי זה במקרה אחר: ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבית לשליח: \u0003\"זיל זבין\u0004 \u0005[לך מכור]\u0006 \u0003לי כורא\u0004 \u0005[כור]\u0006 \u0003\"\u0004\u0003ואזיל וזבין ליה ליתכא\u0004 \u0005[והלך ומכר לו לתך]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אנחנו אומרים]\u0006 ש\u0003אמר ליה\u0004 \u0005[\u0006יכול \u0005לומר לו]\u0006 השליח לבעל הבית: מה \u0003דטבא\u0004 \u0005[שטוב]\u0006 \u0003לך עבדי\u0004 \u0005[עשיתי]\u0006 \u0003לך,\u0004 שלא מכרתי הכל, אלא הנחתי לך מקום לבדוק אם אתה זקוק לכל הכסף, ואם לא תצטרך לכסף לא תמכור עוד, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא מצטרכי\u0004 \u0005[יצטרכו]\u0006 \u0003לך זוזי\u0004 \u0005[הכספים],\u0006 \u0003לא מצית הדרת ביה\u0004 \u0005[תוכל לחזור בו]\u0006 במכר, וטוב עשיתי שמיעטתי ככל האפשר את המכירה.","\u0003או דלמא אמר ליה\u0004 \u0005[שמא\u0006 יכול \u0005לומר לו]\u0006 בעל הבית: איני מסכים לכך, כי \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דליפשו שטרי עילואי\u0004 \u0005[שירבו שטרות\u0006 מכר \u0005עלי],\u0006 שאם אמכור פעמיים יהיו לי שני שטרות של שעבוד, ושמא אזדקק לעמוד עימם בדין, ויצא עלי שם שאני עמוס בשעבודים.","\u0003אמר ר' חנינא מסורא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בהלכות מעילה: \u0003נתן לו\u0004 לשליח \u0003דינר של זהב\u0004 (השווה עשרים וחמישה דינרים, שהם שישה סלעים) ואמר לו: \"הבא (קנה) \u0003לי חלוק\", והלך והביא לו בשלש\u0004 סלעים שהם מחצית הדינר \u0003חלוק, ובשלש טלית\u0004 ולבסוף נמצא שדינר הזהב היה שייך להקדש — \u0003שניהם מעלו.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003שליח כי האי גוונא\u0004 \u0005[בכגון זה]\u0006 נחשב כ\u0003עושה שליחותו ו\u0004רק \u0003מוסיף על דבריו הוי\u0004 \u0005[הוא] —\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 גם \u0003בעל הבית מעל, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003מעביר על דבריו הוי\u0004 \u0005[הוא],\u0006 שהתכוון לומר לו שיקנה בכל הסלעים רק חלוק. \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעל\u0004 בעל הבית? הלא השליח לא עשה את שליחותו כלל!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003דאייתי ליה\u0004 \u0005[שהביא לו]\u0006 חלוק \u0003שוה שש\u0004 סלעים \u0003בשלש,\u0004 שקיבל בעל הבית בדיוק את מה שרצה, ואם כן לא שינה מדבריו, אלא רק הוסיף עליהם, שקנה לו גם טלית.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ה\u0003שליח אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעל?\u0004 הרי עשה מה שאמר לו בעל הבית! ומשיבים: מעל \u0003אטלית\u0004 \u0005[על הטלית]\u0006 שקנה, שהרי הוציא שלושה סלעים משל הקדש לצורך הטלית.","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך\u0006 אתה מפרש, \u0005אמור\u0006 את \u0005סופה]\u0006 של משנה זו, \u0003ר' יהודה אומר: אף בזה בעל הבית לא מעל, מפני שיכול לומר: חלוק גדול הייתי מבקש, ואתה הבאת לי חלוק קטן ורע.\u0004 ואם הביא לו חלוק שוה שש, אין זה חלוק רע!","ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"רע\"? רע בדמים,\u0004 כלומר, בפחות מן הסכום שאמר לו, והוא נחשב כעובר על דבריו משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הבית לשליח, כיון שהזדמן לך מוכר שהוזיל כל כך את המחיר, \u0003אי אייתית לי בשית\u0004 \u0005[אם היית מביא לי\u0006 חלוק \u0005בשישה\u0006 סלעים\u0005]\u0006 \u0003כל שכן דהוה\u0004 \u0005[שהיה]\u0006 אותו חלוק \u0003שוה תרתי סרי\u0004 \u0005[שנים עשר],\u0006 ואז היה בידי חלוק מובחר יותר.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לומר בפירוש \"רע\" ששנינו שהוא רע בדמים, משום \u0003דקתני\u0004 \u0005[ששנה\u0006 שם\u0005]\u0006 \u0003מודה ר' יהודה בקטנית\u0004 שמוכרים אותה במחיר קצוב וקבוע לכל מצב \u0003ששניהם מעלו\u0004 אם קנה רק מקצת מה שאמר לו בעל הבית,"],["\u0003שהקטנית בסלע, וקטנית בפרוטה,\u0004 כלומר, מחיר אחד להם לפי חשבון. מאחר וקיטנית יש לה מחיר קבוע, לא שייכת בה טענה זו של כל שכן שאם היית מביא לי בדינר זהב היה שווה יותר מכפליים כיון שהיו מוזילים לך את המחיר, ולכן מודה בזה ר' יהודה שאף בעל הבית מעל, מה שאין כן בחלוק שאין מחירו קבוע. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא הפירוש.","ושואלים לעצם הענין במכירת הקטנית: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא באתרא דמזבני בשומא\u0004 \u0005[אם תאמר במקום שמוכרים\u0006 קטנית \u0005בשומה,\u0006 בהערכה\u0005]\u0006 \u0003היכא דיהיב ליה\u0004 \u0005[היכן\u0006 בזמן \u0005ש\u0006הוא \u0005נותן לו]\u0006 \u0003סלע מוזלי גביה טפי\u0004 \u0005[מוזילים אצלו יותר]\u0006 ואם כן מרויח, וגם לקטנית אין איפוא מחיר קבוע!","\u0003אמר רב פפא: באתרא דכיילי בכני\u0004 \u0005[במקום שמודדים בכלים],\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003\"כנא כנא\u0004 \u0005[\u0006מלא \u0005כלי כלי]\u0006 \u0003בפרוטה\",\u0004 ולכן כמה שהוא נותן — לפי שיעור הפרוטות הוא מקבל, ואין הבדל במחיר הקיטנית אם הוא קונה מעט או הרבה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו: \u0003היתה כתובתה ארבע מאות זוז,\u0004 ו\u0003מכרה לזה במנה ולזה במנה ולאחרון יפה\u0004 (שווה) \u0003מנה ודינר במנה\u0004 — מכר \u0003של אחרון בטל, ושל כולן מכרן קיים.\u0004 והרי מתחילה נעשתה האשה שליחה למכור שווה ארבע מאות, והיא מכרה מתחילה בפחות, ובכל זאת, מה שמכרה כראוי — קיים! ולא אומרים שעברה על דעת היתומים ויתבטל המיקח?","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 בענין אחר, שמדובר בו \u0003בקטיני\u0004 \u0005[ב\u0006קרקעות \u0005קטנות]\u0006 בודדות שמתחילה אינן חטיבה אחת, הנמכרת בבת אחת, \u0003הכא נמי בקטיני\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ב\u0006קרקעות \u0005קטנות]\u0006 ואין זה חלק מדבר גדול ומלכתחילה לכך נשלחה, כדי למכור כל קרקע בפני עצמה, ומשום כך אין ראיה לענייננו.","בהמשך לדיון הקודם, מעלים בעיה נוספת, ומקדימים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 לנו שאם \u0003אמר\u0004 לשליח: \u0003\"\u0004מכור נכס שלי \u0003ל\u0004אדם \u0003אחד, ולא לשנים\"\u0004 ומכר לשנים — \u0003האמר ליה\u0004 \u0005[הרי אמר לו]\u0006 במפורש \u0003\"לאחד ולא לשנים\",\u0004 ובודאי בטלה שליחותו. אבל אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשליח: \u0003\"\u0004מכור \u0003לאחד\" סתמא\u0004 \u0005[סתם]\u0006 ולא הדגיש שאינו רוצה למכרו לשנים, \u0003מאי\u0004 \u0005[מה]\u0006 הדין, אם מכרו לשנים?","\u0003רב הונא אמר: \"לאחד\"\u0004 אמר, \u0003ולא לשנים. רב חסדא ורבה בר רב הונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003\"לאחד\", ואפילו לשנים, \"לאחד\", ואפילו למאה\u0004 ואינו מקפיד על דבריו.","\u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רב נחמן ל\u0004עיר \u0003סורא, עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב חסדא ורבה בר רב הונא, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה,\u0006 הבעיה שנחלקו בה, \u0005מה\u0006 הדין\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"לאחד\" ואפילו לשנים, ל\"אחד\" ואפילו למאה.\u0004","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 האם ייחשב כעושה רצון בעל הבית \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003טעה\u0004 ה\u0003שליח\u0004 כגון שמכר בפחות? \u0003אמר להו\u0004 \u0005[להם]:\u0006 ש\u0003טעה\u0004 ה\u0003שליח לא קאמינא\u0004 \u0005[אין אני אומר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר אדוני]\u0006 כי \u0003אין אונאה לקרקעות!\u0004 שלא חל בהם איסור אונאה, לפי שאין להם ערך קצוב באמת.","ענה להם: \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן]\u0006 ש\u0003טעה בעל הבית\u0004 עצמו, כגון שמכר קרקעות בפחות מערכן, שאז אינו יכול לטעון משום אונאה, \u0003אבל\u0004 אם \u0003טעה\u0004 ה\u0003שליח, אמר ליה\u0004 \u0005[\u0006יכול \u0005לומר לו]\u0006 בעל הבית: \u0003\"לתקוני שדרתיך\u0004 \u0005[לתקן שלחתיך]\u0006 \u0003ולא לעוותי\u0004 \u0005[לקלקל]\u0006\u0003\"\u0004ובטלה השליחות.","ומסבירים: \u0003ומנא תימרא דשאני\u0004 \u0005[ומנין אומר אתה ששונה]\u0006 הדין לגבי טעות \u0003בין שליח לבעל הבית?\u0004","— \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לשלוחו \"צא ותרום\" — תורם כדעת בעל הבית,\u0004 לפי השיעור שרוצה בעל הבית לתת. שיש הנותן בעין יפה — אחד מארבעים, ויש הנותן בעין בינונית — אחד מחמישים, ויש הנותן בעין רעה — אחד משישים, והשליח צריך לתת לפי רצונו של בעל הבית. \u0003ואם אינו יודע\u0004 מהי \u0003דעתו של בעל הבית — תורם בבינונית,\u0004 שהיא \u0003אחד מחמשים. פיחת עשרה או הוסיף עשרה,\u0004 שנתן אחד מארבעים או אחד משישים — \u0003תרומתו תרומה,\u0004 שיכול הוא לומר לבעל הבית, בכך הערכתי את דעתך.","\u0003ואילו גבי בעל הבית תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תרם ועלה בידו אפילו אחד מעשרים — תרומתו תרומה.\u0004 הרי שלשליח גבול קצוב, שאם טעה בדעת בעל הבית ונתן יותר מן השיעור המקובל — אין תרומתו תרומה. ואילו בעל הבית שטעה — אפילו טעה בהרבה, אין מעשהו בטל.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003היתה כתובתה ארבע מאות זוז, מכרה לזה במנה, ולזה במנה, ולאחרון שוה מנה ודינר במנה — המכר של\u0004 ה\u0003אחרון בטל, ושל כולן מכרן קיים.\u0004 הרי שלמרות שמן הראוי היה שתמכור לאדם אחד, ולא תרבה בשטרות אחריות על היתומים, אם מכרה לאנשים שונים — מכרה קיים!","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 מדובר שם \u0003בקטיני\u0004 \u0005[ב\u0006קרקעות \u0005קטנות]\u0006 בודדות, שמתחילה לא עמדו להימכר יחד.","\u0003שום הדיינין,\u0004 כלומר, אם העריכו הדיינים נכס מסויים לשם מכירתו, \u0003שפיחתו\u0004 בהערכתם \u0003שתות\u0004 (שישית) מן המחיר הראוי, \u0003או הוסיפו שתות\u0004 על המחיר הראוי — \u0003מכרן בטל.\u0004","\u0003רבן שמעון בן גמליאל אומר: מכרן קיים.\u0004 ש\u0003אם כן\u0004 אתה אומר שמבטלים את המכר — \u0003מה כח בית דין יפה\u0004 משל שאר בני אדם? \u0003אבל אם עשו אגרת בקורת ביניהן,\u0004 שעשו הכרזה פומבית, \u0003אפילו מכרו שוה מנה במאתים או שוה מאתים במנה — מכרן קיים,\u0004 שהרי הדבר היה פומבי ועל דעת כן עשו זאת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שליח\u0004 שטעה ומכר בפחות, \u0003כמאן\u0004 \u0005[כמי]\u0006 הוא? האם דינו כדיינים שאם טעו בפחות משתות מכרם קיים או כאלמנה שגם אם פחתה משהו מכרה בטל?"],["\u0003רבא אמר\u0004 בשם \u0003רב נחמן: שליח\u0004 דינו \u0003כדיינין. רב שמואל בר ביסנא אמר\u0004 בשם \u0003רב נחמן:\u0004 דינו \u0003כאלמנה.\u0004","ומסבירים את נימוקיהם: \u0003רבא אמר\u0004 בשם \u0003רב נחמן: שליח כדיינין,\u0004 ומדוע — \u0003מה דיינין לאו לדידהו\u0004 \u0005[לא לעצמם]\u0006 הם מעריכים, ולכן ייפו חכמים את כוחם — \u0003אף שליח נמי לאו לדידיה\u0004 \u0005[גם כן לא לעצמו\u0006 עושה\u0005],\u0006 \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003אלמנה דלדידה\u0004 \u0005[ש\u0006מוכרת \u0005לעצמה].\u0006","\u0003רב שמואל בר ביסנא אמר\u0004 בשם \u0003רב נחמן:\u0004 שליח דינו \u0003כאלמנה, מה אלמנה יחידה — אף שליח יחיד, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בית דין\u0004 ש\u0003רבים נינהו\u0004 \u0005[הם],\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005],\u0006 \u0003שליח\u0004 דינו \u0003כאלמנה.\u0004","ושואלים: \u0003ומאי שנא מהא דתנן\u0004 \u0005[ו\u0006ב\u0005מה שונה\u0006 דבר זה \u0005מזו ששנינו]:\u0006 \u0003האומר לשלוחו \"צא ותרום\" — תורם כדעת בעל הבית, ואם אינו יודע\u0004 מהי \u0003דעתו של בעל הבית — תורם בבינונית\u0004 שהיא \u0003אחד מחמשים.\u0004 ואם \u0003פיחת עשרה או הוסיף עשרה,\u0004 שתרם אחד מארבעים או אחד משישים \u0003— תרומתו תרומה.\u0004 ומדוע לא נאמר שבטלה תרומתו אם לא תרם כדעת בעל הבית?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 מי ש\u0003תורם בעין רעה\u0004 אחד משישים, \u0003ואיכא\u0004 \u0005[ויש]\u0006 ש\u0003תורם בעין יפה\u0004 אחד מארבעים, \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 השליח: \u0003להכי\u0004 \u0005[לכך]\u0006 \u0003אמדתיך,\u0004 שיכולתי להעלות על דעתי שעינך יפה, או רעה. \u0003אבל הכא טעותא הוא\u0004 \u0005[כאן טעות היא],\u0006 שבודאי לא היה הדבר כן, ורק השליח הוא שטעה \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 בעל הבית לשליח: \u0003לא איבעי\u0004 \u0005[היה]\u0006 \u0003לך למיטעי\u0004 \u0005[לטעות].\u0006","\u0003אמר רב הונא בר חנינא אמר רב נחמן: הלכה כדברי חכמים\u0004 במשנתנו שאם טעו הדיינים בהערכתם המיקח בטל. ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006האם \u0005אין לו]\u0006 \u0003לרב נחמן\u0004 שיטה זו של \u0003מה כח בית דין יפה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר שמואל: יתומים שבאו לחלוק בנכסי אביהן — בית דין מעמידין להן אפוטרופוס, ובוררין להם\u0004 (בשבילם) \u0003חלק יפה\u0004 ומחלקים. \u0003הגדילו\u0004 (גדלו) היתומים אחר כך — \u0003יכולין למחות\u0004 על חלוקה זו. \u0003ורב נחמן דידיה\u0004 \u0005[\u0006ב\u0005עצמו]\u0006 \u0003אמר\u0004 ולא בשם שמואל: \u0003הגדילו — אין יכולין למחות,\u0004 ש\u0003אם כן מה כח בית דין יפה.\u0004 הרי שרב נחמן עצמו סבור כדעת רבן שמעון בן גמליאל!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שלדבריו המיקח בטל, הרי זה באופן ש\u0003טעו\u0004 הדיינים והערכתם היתה בלתי נכונה, ולכן לדעתו מבטלים את הפסק כדברי חכמים. ואולם \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שלדבריו אין החלוקה שחילק אפוטרופוס ליתומים בטלה, הרי זה באופן ש\u0003לא טעו\u0004 בחלוקת הנכסים בין היתומים, ולכן פסק כרבן שמעון בן גמליאל שמייפים את כוח בית דין, כדי שלא יוכלו היתומים למחות.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא טעו\u0004 הדיינים, אם כן, \u0003במאי\u0004 \u0005[במה]\u0006 \u0003יכולין\u0004 היתומים \u0003למחות?\u0004 הרי הדיינים עשו כדין! ומשיבים: \u0003ברוחות\u0004 (בצדדים), שאין הם טוענים שהיתה החלוקה בלתי צודקת, אלא מסיבות שונות מעוניינים הם להחליף בצדדים, כגון שיש לאחד מהם שדה משלו הסמוך לאותו צד שאותו הוא לא קיבל בחלוקה זו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: מעשה ועשה רבי כדברי חכמים\u0004 שבמשנה, \u0003אמר לפניו פרטא בנו של ר' אלעזר בן פרטא בן בנו של ר' פרטא הגדול: אם כן מה כח בית דין יפה?! ו\u0004מששמע זאת, \u0003החזיר רבי את המעשה.\u0004","\u0003רב דימי מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את המעשה כפי שנאמר כאן, ואילו \u0003רב ספרא מתני הכי\u0004 \u0005[היה שונה אותו כך]\u0006 בגרסה קצת שונה: \u0003מעשה וביקש רבי לעשות כדברי חכמים, אמר לפניו פרטא בנו של ר' אלעזר בן פרטא בן בנו של ר' פרטא הגדול: אם כן מה כח בית דין יפה?\u0004 ומששמע זאת, \u0003לא עשה רבי את המעשה.\u0004","ומנסים להציע: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005ב\u0006ענין \u0005זה\u0006 רב דימי ורב ספרא \u0005חלוקים],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 רב דימי\u0005]\u0006 \u0003סבר\u0004 שאם \u0003טעה\u0004 החכם \u0003בדבר משנה — חוזר\u0004 בו ממה שפסק. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 רב ספרא\u0005]\u0006 \u0003סבר: אינו חוזר,\u0004 ולכן לגרסתו מדובר ששינה רבי את דעתו לפני שעשה מעשה.","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טעה בדבר משנה — חוזר,\u0004 ואין ביניהם מחלוקת עקרונית כלל, אלא בפרטי המקרה \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר\u0004 כי \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 ה\u0003מעשה, ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר\u0004 כי \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 ה\u0003מעשה.\u0004","\u0003אמר רב יוסף: ארמלתא דזבינה\u0004 \u0005[אלמנה שמכרה]\u0006 לצורך מזונות או כתובה — ה\u0003אחריות\u0004 היא \u0003איתמי\u0004 \u0005[על היתומים],\u0006 שאם התברר שהיה שעבוד קודם על נכס זה שמכרה, נוטל הלוקח מנכסיהם האחרים של היורשים. \u0003ו\u0004כן \u0003בית דין דזבין\u0004 \u0005[שמכרו]\u0006 לצורך זה — ה\u0003אחריות\u0004 היא \u0003איתמי\u0004 \u0005[על היתומים].\u0006","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי אין האלמנה מוכרת מרכוש עצמה, אלא לפרעון חובותיו של הבעל, והאחריות היא איפוא על נכסיו שהם עתה של יתומים!","ומשיבים: \u0003אלמנה\u0004 באמת \u0003לא איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, שברור שהאחריות על מכירה זו היא על היתומים, \u0003כי איצטריך ליה\u0004 \u0005[כאשר הוצרך לו]\u0006 לומר, הרי זה לגבי \u0003בי דינא\u0004 \u0005[בית דין],\u0006 ומדוע הוצרך להדגיש זאת — כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006"],["\u0003כל דזבין מבי דינא\u0004 \u0005[שקונה מבית דין] —\u0006 \u0003אדעתא למיפק ליה קלא\u0004 \u0005[על דעת שייצא לו קול]\u0006 \u0003הוא דזבין\u0004 \u0005[שקונה],\u0006 שמכירה על ידי בית דין נעשית בהכרזה ובפומבי, וסבור הלוקח שאם עד זמן הקניה לא באו מערערים — ודאי שאין עוד כל פקפוק בקנייתו ומוותר על האחריות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת, האחריות על נכסי היתומים ולא על בית הדין.","שנינו במשנה: \u0003רבן שמעון בן גמליאל אומר\u0004 שאפילו אם טעו אין מחזירים, משום שאם לא כן מה כח בית דין יפה. ושואלים: \u0003ועד כמה\u0004 אם טעו בית הדין אין מחזירים? \u0003אמר רב הונא בר יהודה אמר רב ששת: עד פלגא\u0004 \u0005[חצי].\u0006","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמר רבן שמעון בן גמליאל: בית דין שמכרו שוה מאתים במנה או שוה מנה במאתים — מכרן קיים,\u0004 וכיון שלא הביא כדוגמה הפרש גדול יותר, משמע שזהו שיעור הטעות שאינה חוזרת.","\u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יוסף: בית דין שמכרו בלא הכרזה\u0004 (שמפרסמים שקרקע זו עומדת להימכר ובתוך כך יוודע מחירה) — \u0003נעשו כמי שטעו בדבר משנה וחוזרין.\u0004","ותוהים על הלשון: \u0003נעשו?\u0004 מדוע אתה אומר שנעשו כאילו טעו? הלא \u0003ודאי טעו! דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שום\u0004 \u0005[הערכה]\u0006 שעושים בית הדין לפני שמוכרים מנכסי \u0003היתומין\u0004 כדי לפרוע חוב אביהם, הריהי \u0003שלשים יום, ושום\u0004 \u0005[והערכה]\u0006 אותה עושה הגיזבר בבואו למכור מנכסי \u0003ההקדש\u0004 הריהי \u0003ששים יום, ומכריזין\u0004 בשלושים ובשישים הימים האלה \u0003בבקר ובערב.\u0004 ואם כן כתוב במשנה שצריכים להכריז, ואם לא עשו כן, ודאי טעו בדבר משנה!","ומשיבים: \u0003אי מההיא הוה אמינא\u0004 \u0005[אם משם הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003שליח\u0004 שמכר, \u0003אבל בית דין\u0004 שמכרו — \u0003לא,\u0004 אין זה נחשב כטעות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב יוסף שגם בית דין שלא הכריזו — טעו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אשי לאמימר\u0004 על דבריו הקודמים ממה ששנינו: \u0003שום הדיינין,\u0004 כלומר, אם העריכו הדיינים נכס מסויים לשם מכירתו, \u0003שפיחתו\u0004 בהערכתם \u0003שתות\u0004 (שישית) מן המחיר הראוי, \u0003או הותירו שתות\u0004 על המחיר הראוי — \u0003מכרן בטל.\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם מכרו \u0003שוה בשוה,\u0004 במחיר הנכון — \u0003מכרן קיים. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שם גם כש\u0003לא אכרוז\u0004 \u0005[הכריזו]?\u0006 והשיב אמימר: \u0003לא,\u0004 מדובר שם \u0003בדאכרוז\u0004 \u0005[בשהכריזו].\u0006","ומקשים: \u0003הא מדסיפא בדאכרוז הוי רישא בדלא אכרוז\u0004 \u0005[הרי מ\u0006כיון \u0005שסופה\u0006 של המשנה היא \u0005בשהכריזו,\u0006 אם כן \u0005ראשה הוא בשלא הכריזו],\u0006 \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אם עשו אגרת בקורת\u0004 (הכרזה) — \u0003אפילו מכרו שוה מנה במאתים או שוה מאתים במנה — מכרן קיים.\u0004","\u0003אלא\u0004 יש לפרש בדרך אחרת, \u0003לעולם\u0004 מדובר \u0003בדלא אכרוז\u0004 \u0005[בשלא הכריזו],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003כאן,\u0004 בסיפא שמשמע שצריך הכרזה, הרי זה \u0003בדברים שמכריזין עליהן\u0004 ואם מכרום בלא הכרזה — טעות גמורה היא, ואילו \u0003כאן,\u0004 ברישא שמשמע שאין צריך הכרזה, הרי זה \u0003בדברים שאין מכריזין עליהן.\u0004","\u0003ואלו הן דברים שאין מכריזין עליהן: העבדים והמטלטלין והשטרות.\u0004 ומסבירים: \u0003עבדים טעמא מאי\u0004 \u0005[מה טעם]\u0006 אין מכריזים עליהם? — שיש לחשוש \u0003שמא ישמעו\u0004 שעומדים למכרם \u0003ויברחו.\u0004 ו\u0003מטלטלין ושטרות\u0004 אין מכריזים שמוכרים אותם — \u0003שמא\u0004 מתוך הפרסום \u0003יגנבו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כאן — בשעה שמכריזין, כאן — בשעה שאין מכריזין.\u0004 ומתי אין מכריזים?","— באותם זמנים \u0003דאמרי נהרדעי\u0004 \u0005[שאמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לכרגא\u0004 \u0005[ל\u0006תשלום \u0005מסים],\u0006 \u0003למזוני\u0004 \u0005[ל\u0006תשלום \u0005מזונות]\u0006 \u0003ולקבורה — מזבנינן\u0004 \u0005[מוכרים אנו]\u0006 \u0003בלא אכרזתא\u0004 \u0005[הכרזה],\u0006 אלא מיד, מפני שהצרכים הללו הם דחופים ואין הזמן מאפשר להמתין.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כאן — במקום שמכריזין, כאן — במקום שאין מכריזין.\u0004 וכפי ש\u0003אמר רב נחמן: מעולם לא עשו אגרת בקורת בנהרדעא.\u0004","\u0003סבור מינה\u0004 \u0005[\u0006היו \u0005סבורים ממנה,\u0006 מאמירה זו\u0005]\u0006 שלא הכריזו שם \u0003משום דבקיאי בשומא\u0004 \u0005[שבקיאים\u0006 החכמים שם \u0005בהערכה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בר מניומי: לדידי מיפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003רב נחמן\u0004 עצמו, ולדבריו הטעם הוא \u0003משום דקרו להו\u0004 \u0005[שקוראים להם],\u0006 לקונים \u0003\"בני אכלי\u0004 \u0005[אוכלי]\u0006 \u0003נכסי דאכרזתא\u0004 \u0005[הכרזה]\u0006 \u0003\",\u0004 שנחשב הדבר לגנאי שהשתמש הקונה במצוקתו של אחר וקנה ממנו את נכסיו, ולכן לא רצו אנשים הגונים לקנות בהכרזה, ומשום כך ביטלו את התקנה.","\u0003אמר רב יהודה אמר שמואל: מטלטלין של יתומים — שמין אותן ומוכרין אותן לאלתר\u0004 (מיד), כדי שלא ייפסדו עם הזמן. \u0003רב חסדא אמר\u0004 בשם \u0003אבימי: מוכרין אותן לשווקים\u0004 בימי השוק, ואף אם הדבר גורם לעיכוב, לפי שמרובים אז הקונים וישיגו עבורם מחיר הגון.","מעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 בדבר, אלא \u0003הא\u0004 \u0005[זה]\u0006 שאמר אבימי שמוכרים אותם ביום השוק — הרי זה באופן \u0003דמיקרב שוקא\u0004 \u0005[שקרוב\u0006 יום \u0005השוק],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל שמוכרים מיד, הרי זה באופן \u0003דמרחק שוקא\u0004 \u0005[שרחוק\u0006 יום \u0005השוק].\u0006","מסופר: \u0003רב כהנא הוה בידיה שכרא\u0004 \u0005[היה בידו שיכר]\u0006 שהיה שייך ל\u0003רב משרשיא בר חילקאי יתמא\u0004 \u0005[\u0006שהיה \u0005יתום].\u0006 \u0003שהייה\u0004 \u0005[השהה אותו]\u0006 \u0003עד ריגלא\u0004 \u0005[הרגל]\u0006 כדי למוכרו אז, והסביר את טעם מעשיו \u0003ואמר\u0004 כדי להסביר את טעם מעשיו: \u0003אף על גב דנפל ביה איצצתא\u0004 \u0005[אף על פי\u0006 שיכול להיות \u0005שיפול בו פגם\u0006 בשיכר\u0005],\u0006 שיחמיץ מעט, מכל מקום \u0003מייתי זוזא חריפא\u0004 \u0005[מביא\u0006 השיכר \u0005כסף\u0006 מיידי\u0005],\u0006 שאז יוכל לקבל תשלום גבוה יותר ובכסף מזומן ולכן, טובת היתום היא למכור סמוך לרגל.","וכן מסופר: \u0003רבינא הוה בידיה חמרא\u0004 \u0005[היה בידו יין]\u0006 של \u0003רבינא זוטי יתמא בר אחתיה\u0004 \u0005[הקטן היתום בן אחותו].\u0006 \u0003הוה לדידיה נמי חמרא\u0004 \u0005[היה לו עצמו גם כן יין],\u0006 \u0003הוה קמסיק ליה\u0004 \u0005[\u0006ו\u0005היה מוליך אותו]\u0006 \u0003ל\u0004מקום בשם \u0003סיכרא\u0004 כדי למכרו.","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 לשאול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו לאמטויי בהדן\u0004 \u0005[להביא\u0006 את היין שלי \u0005עם\u0006 היין \u0005שלו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל, לא עדיף מדידך\u0004 \u0005[לך,\u0006 וקח גם את שלו, ש\u0005אינו עדיף משלך],\u0006 שאם אתה עושה כן ברכושך, משמע שאתה סבור שזו הדרך הטובה ביותר, ולכן גם בשלו מותר לך לעשות כן.","קטנה שהיתה \u0003ממאנת\u0004 בבעלה, וכן \u0003השניה\u0004 לערוה (שהיא קרובה שאינה אסורה מן התורה ורק חכמים גזרו שאסור לשאתה), \u0003והאילונית\u0004 (שהתברר שיש בה פגם גופני כזה שאינה מסוגלת מעיקרה ללדת) — כל אלה \u0003אין להן\u0004 לא \u0003כתובה, ולא פירות\u0004 של הנכסים שלהן שאכל הבעל בינתיים \u0003ולא מזונות, ולא בלאות,\u0004 כלומר, חפצים שהכניסה לו בנדונייתה והשתמש בהם ונתבלו במשך זמן הנשואין, שאינה מקבלת בחזרה.","\u0003אם מתחלה נשאה לשם אילונית,\u0004 שידע שהיא אילונית ומתוך ידיעה זו נשאה — \u0003יש לה כתובה.\u0004","\u0003אלמנה\u0004 שנישאה \u0003לכהן גדול,\u0004 וכן \u0003גרושה\u0004 או \u0003חלוצה לכהן הדיוט,\u0004 או \u0003ממזרת\u0004 או \u0003נתינה\u0004 (מבני הגבעונים) שנישאה \u0003לישראל,\u0004 או \u0003בת ישראל לנתין\u0004 או \u0003לממזר,\u0004 אף שכל אלה אסורות מדין תורה — \u0003יש להם כתובה.\u0004","\u0003רב תני\u0004 \u0005[שנה]:\u0006 \u0003קטנה\u0004 שהשיאוה אמה או אחיה — כאשר היא \u0003יוצאה בגט אין לה כתובה,\u0004 שמדין תורה אין תוקף לנישואין אלה ולא תיקנו בהם כתובה. \u0003וכל שכן\u0004 שאם יוצאת ממנו באופן שהיא \u0003ממאנת\u0004 בו לפי שאינה רוצה בנישואין הללו.","\u0003שמואל תני\u0004 \u0005[שנה]:\u0006 \u0003ממאנת אין לה כתובה, אבל\u0004 זו ש\u0003יוצאה בגט — יש לה כתובה.\u0004","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: ממאנת אין לה כתובה,\u0004 וזו ש\u0003יוצאה בגט יש לה כתובה.\u0004","ועוד אמר: \u0003ממאנת — לא פסלה מן האחין,\u0004 שאחי הבעל (ושאר קרוביו) רשאים לשאת אותה לאחר שיצאה מרשות בעלה, שכן המיאון עוקר את הנישואין מעיקרם, וכאילו לא היתה נשואה מעולם, \u0003ו\u0004מאותו טעם אף \u0003לא פסלה מן הכהונה\u0004 כגרושה. אבל זו ה\u0003יוצאה בגט — פסלה מן האחין, ופסלה מן הכהונה.\u0004","ועוד הבדל בהלכה: \u0003ממאנת אינה צריכה להמתין שלשה חדשים\u0004 כדי להינשא לאחר, כדרך שתיקנו לגבי כל אשה שנפרדה בדרך כלשהי מבעלה,"],["\u0003יוצאה בגט צריכה להמתין שלשה חדשים\u0004 עד שתינשא בשנית.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 שמואל בדברים אלה? הלא כבר \u0003תנינא כולהו\u0004 \u0005[שנינו\u0006 את \u0005כולם],\u0006 ששנינו: \u0003הממאנת באיש — הוא מותר בקרובותיה, והיא מותרת בקרוביו, ולא פסלה מן הכהונה. נתן לה גט — הוא אסור בקרובותיה, והיא אסורה בקרוביו, ופסלה מן הכהונה.\u0004","ומשיבים: דין זה ש\u0003צריכה להמתין שלשה חדשים\u0004 לפני שנישאת לאחר \u0003איצטריכא ליה\u0004 \u0005[צריך אותו]\u0006 שאותו \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ואגב כן גם מנה גם את שאר ההבדלים שיש בין זו לזו.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005לומר כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו באותה מחלוקת של רב ושמואל, ששנינו, \u0003ר' אליעזר אומר: אין מעשה קטנה כלום\u0004 כאשר נישאת שלא על ידי אביה, \u0003ו\u0004לכן \u0003אין בעלה זכאי במציאתה, ולא במעשה ידיה, ולא בהפרת נדריה, ואינו יורשה, ואינו מיטמא לה. כללו של דבר: אינה כאשתו לכל דבר, אלא\u0004 רק בענין זה \u0003ש\u0004אינה יוצאת ממנו ללא כלום, אלא \u0003צריכה מיאון.\u0004","\u0003ר' יהושע אומר: מעשה קטנה כלום\u0004 (דבר) הוא, ויש בו ממש, \u0003ובעלה זכאי במציאתה ובמעשה ידיה ובהפרת נדריה, ויורשה, ומיטמא לה. כללו של דבר: הרי היא כאשתו לכל דבר, אלא ש\u0004אף על פי כן אינה צריכה גט כדי לצאת ממנו אלא \u0003יוצאה במיאון.\u0004","\u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003רב\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' אליעזר\u0004 ולכן לדבריו גם כאשר יוצאה בגט אין לה כתובה, \u0003ושמואל\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' יהושע?\u0004","ודוחים: \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' אליעזר כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שודאי אין מעשיה כלום, וכדברי רב.","\u0003כי פליגי אליבא\u0004 \u0005[כאשר נחלקו\u0006 הרי זה \u0005לשיטתו]\u0006 של \u0003ר' יהושע: שמואל\u0004 סובר \u0003כ\u0004דעת \u0003ר' יהושע\u0004 בפשטות, \u0003ורב\u0004 אומר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 שהיא כאשתו לכל דבר \u0003אלא\u0004 ביחס להתחייבויות הבאות \u0003מדידה לדידיה\u0004 \u0005[משלה לשלו],\u0006 שלגבי כל התחייבויות האשה לבעלה הוא הדין גם בקטנה, \u0003אבל\u0004 ביחס להתחייבויות הבאות \u0003מדידיה לדידה\u0004 \u0005[משלו לשלה],\u0006 וכגון הכתובה ותנאי הכתובה — \u0003לא\u0004 אמר, שכיון שקטנה היא, ואין לה קידושין מן התורה כלל, אין בידינו לחייב את הבעל לשלם לה דבר משלו.","שנינו במשנה שאין לממאנת, לשניה ולאיילונית כתובה \u0003ולא\u0004 זכות לקבל את ה\u0003בלאות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חייא לרב כהנא: אמרת לן משמיה\u0004 \u0005[לנו משמו]\u0006 של \u0003שמואל: לא שנו אלא\u0004 בלאות של \u0003נכסי מלוג\u0004 (שהם הנכסים השייכים לה, ובעלה רק אוכל פירותיהם) שאין לה, \u0003אבל\u0004 בלאות של \u0003נכסי צאן ברזל\u0004 (שהם נכסים שהיא מכניסה לו ונישומים בכתובתה ושייכים לבעלה, אלא שהוא מקבל עליו להחזירם לה לכשתצא ממנו) \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה.\u0004","\u0003הוי בה\u0004 \u0005[היה עוסק,\u0006 מתקשה בכך\u0005]\u0006 \u0003רב פפא: אהייא\u0004 \u0005[על איזו]\u0006 הלכה במשנה נאמרו דברים אלו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי נאמרו על \u0003ממאנת, אי דאיתנהו\u0004 \u0005[שישנם]\u0006 הבלאות וקיימים בעינם — \u0003אידי ואידי שקלא\u0004 \u0005[זה וזה\u0006 היא \u0005נוטלת],\u0006 שהרי הנישואין בטלו, והיא נוטלת את שלה. \u0003ואי דליתנהו\u0004 \u0005[ואם שאינם\u0006 מצויים\u0005]\u0006 וכגון שבלו לחלוטין במשך הזמן — \u0003אידי ואידי לא שקלא\u0004 \u0005[זה וזה אינה לוקחת],\u0006 שהרי זכותו של הבעל להשתמש בהם!","\u0003אלא\u0004 תאמר כי מדובר על ה\u0003איילונית,\u0004 אולם גם אז קשה: \u0003אי דאיתנהו\u0004 \u0005[אם שישנם]\u0006 אותם בלאות — \u0003אידי ואידי שקלא\u0004 \u0005[זה וזה\u0006 היא \u0005לוקחת],\u0006 \u0003אי דליתנהו\u0004 \u0005[אם שאינם] —\u0006 \u0003איפכא מיבעי ליה\u0004 \u0005[ההיפך\u0006 היה \u0005צריך לו\u0006 לומר\u0005]:\u0006 \u0003נכסי מלוג\u0004 ש\u0003ברשותה קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 שהרי הנכסים הם שלה — \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה,\u0004 שאם נישואיה בטלים — צריך להחזיר לה את רכושה, ואילו \u0003נכסי צאן ברזל דלאו\u0004 \u0005[שלא]\u0006 \u0003ברשותה קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 אלא הם ברשות הבעל — \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה!\u0004","\u0003אלא\u0004 יש לומר שמדובר על ה\u0003שניה\u0004 לעריות, \u0003ו\u0004טעם הדבר: \u0003קנסו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לדידה בדידיה ולדידיה בדידה\u0004 \u0005[לשלה,\u0006 לדברים שמגיעים לה — \u0005משלו, ולשלו,\u0006 לדברים שמגיעים לו — \u0005משלה],\u0006 שכיון שעברו שניהם על דברי חכמים, קנסו חכמים שיפסידו שניהם, שנכסי מלוג שלה שבלו — לא תקבל, ונכסי צאן ברזל שלו שבלו — לא יטול ממנה.","\u0003אמר רב שימי בר אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003רב כהנא: עיילא ליה גלימא\u0004 \u0005[\u0006אם \u0005הכניסה לו\u0006 אשה \u0005גלימה]\u0006 אחרי הנישואין — \u0003קרנא הוי, ולא מכסי לה ואזיל עד דבלי\u0004 \u0005[קרן הוא, ואינו מתכסה בה והולך עד ש\u0006היא \u0005בלה],\u0006 ואין אומרים שתיחשב הגלימה לקרן והשימוש בה כפירות השייכים לבעל ולא תגבה תמורתם, שהרי דווקא בשניה קנסו שאינם שלה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן\u0004 שהשימוש בגלימה \u0003פירא הוי\u0004 \u0005[פירות הם]!\u0006 ומשיבים: דברי \u0003רב נחמן\u0004 אכן \u0003פליגא\u0004 \u0005[חלוקים]\u0006 על שיטה זו.","שנינו במשנה שלממאנת, לשניה ולאילונית \u0003אין להן כתובה. אמר שמואל: לא שנו אלא\u0004 לעיקר כתובה, שהם \u0003מנה\u0004 לאלמנה ו\u0003מאתים\u0004 לבתולה, שתיקנו חכמים לכל אשה הנישאת, \u0003אבל תוספת\u0004 לכתובה שכתב מדעתו, הרי זו כמתנה סתם, ולכן \u0003יש להן.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נשים שאמרו חכמים\u0004 ש\u0003אין להן כתובה, כגון הממאנת וחברותיה — אין להן מנה מאתים\u0004 שהם עיקר כתובה, \u0003אבל תוספת\u0004 שכתב מעצמו — \u0003יש להן.\u0004","אולם \u0003נשים שאמרו חכמים\u0004 כי \u0003יוצאות שלא בכתובה, כגון\u0004 זו ה\u0003עוברת על דת וחברותיה\u0004 (זו שנמצאו בה מומים וכיוצא בה) — \u0003אין להן תוספת, וכל שכן\u0004 שאין להן \u0003מנה\u0004 ו\u0003מאתים,\u0004 שכיון שהן עוברות עבירה, קנסו אותן חכמים בביטול כל התחייבויות הכתובה שכתב הבעל. \u0003והיוצאת משום שם רע,\u0004 שיצא עליה שם רע של זנות ומשום כך בעלה מגרשה — \u0003נוטלת מה שלפניה,\u0004 את הבלאות הקיימים בנכסי מלוג, \u0003ויוצאה.\u0004","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003ל\u0004מה שאמר \u0003רב הונא,\u0004 ש\u0003אמר רב הונא:\u0004 אשה ש\u0003זינתה — לא הפסידה\u0004 את"],["\u0003בלאותיה\u0004 ה\u0003קיימין,\u0004 כלומר, את בגדיה. וכיוצא בהם גם שאר נכסים שהביאה, והם קיימים עדיין — לא הפסידה אותם.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: זינתה — הפסידה בלאותיה קיימין. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם היא זינתה, כליה מי זנאי\u0004 \u0005[האם זנו]?\u0006 ובודאי אין קונסים גם את נכסיה בזה אלא \u0003תני\u0004 \u0005[שנה\u0006 להיפך\u0005]:\u0006 \u0003לא הפסידה בלאותיה קיימין.\u0004","וכיוצא בזה \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 ברייתא \u0003זו\u0004 ששנה חוזר המשניות לפני רב נחמן היא \u0003דברי ר' מנחם סתימתאה\u0004 \u0005[הסתום]\u0006 (שדבריו נאמרו כסתם משנה בכמה מקומות), \u0003אבל חכמים אומרים: זינתה — לא הפסידה בלאותיה קיימין.\u0004","שנינו במשנה ש\u0003אם מתחלה נשאה\u0004 ביודעו שהיא איילונית — יש לה כתובה. \u0003אמר רב הונא: אילונית — אשה ואינה אשה, אלמנה\u0004 לכהן גדול — \u0003אשה גמורה.\u0004 ומסבירים: \u0003אילונית אשה ואינה אשה,\u0004 שפעמים נחשבת כאשתו ופעמים אינה נחשבת כאשתו, כיצד? אם \u0003הכיר בה\u0004 וידע שהיא איילונית כאשר נשאה — \u0003יש לה כתובה\u0004 כאשה רגילה, ואם \u0003לא הכיר בה — אין לה כתובה. אלמנה\u0004 לכהן גדול הריהי \u0003אשה גמורה, בין הכיר בה\u0004 כאשר נשאה וידע שהיא אלמנה, \u0003בין לא הכיר בה\u0004 שהיא אלמנה — \u0003יש לה כתובה.\u0004","","\u0003ורב יהודה אומר: אחת זו ואחת זו אשה ואינה אשה.\u0004 כלומר, גם אלמנה, אם \u0003הכיר בה\u0004 וידע שזה היה מעמדה — \u0003יש לה כתובה,\u0004 ואם \u0003לא הכיר בה — אין לה כתובה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003כנסה\u0004 את האשה \u0003בחזקת שהיא כן,\u0004 שיש בה פגם מסויים או שהיא אסורה עליו, \u0003ונמצאת שהיא כן,\u0004 כפי שידע מראש — \u0003יש לה כתובה.\u0004 ונדייק מכאן: \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם כנס אותה \u0005סתם]\u0006 ונתברר שיש בה פגם או שאסורה עליו — \u0003אין לה כתובה.\u0004 וקשה מכאן על רב הונא!","ודוחים: \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 אל תדייק\u0005]:\u0006 \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם כנסה \u0005סתם]\u0006 \u0003אין לה כתובה, אלא אימא\u0004 \u0005[אמור\u0006 ותדייק כך\u0005]:\u0006 הרי אם \u0003כנסה בחזקת שאינה כן, ונמצאת שהיא כן — אין לה כתובה.\u0004","ושואלים: \u0003אבל\u0004 אם כנס אותה \u0003סתמא מאי\u0004 \u0005[סתם\u0006 ולא פירש, \u0005מה\u0006 משמע שיהא הדין\u0005] —\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 כתובה, אם כן, \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 \u0003בחזקת שהיא כן ונמצאת שהיא כן יש לה כתובה, לשמעינן סתמא\u0004 \u0005[שישמיע לנו\u0006 בכנסה \u0005סתם],\u0006 \u0003וכל שכן הא\u0004 \u0005[זו]\u0006 שכנסה על מנת כן!","\u0003ועוד\u0004 קשה, שהרי \u0003תני\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא אחרת במפורש: \u0003כנסה בידוע\u0004 שיש בה פגם מסויים \u0003ונמצאת בידוע — יש לה כתובה, כנסה סתם — אין לה כתובה.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב הונא!\u0004 ומסבירים: \u0003רב הונא מתניתין אטעיתיה\u0004 \u0005[משנתנו הטעתה אותו],\u0006 שמתוך דיוק שדייק בלשונה הגיע למסקנה זו, ועל פיה אמר דברים שלא כדין. \u0003הוא סבר: מדקא מפליג\u0004 \u0005[מ\u0006כיון \u0005ש\u0006המשנה \u0005מחלקת]\u0006 \u0003באילונית ולא קמפליג\u0004 \u0005[ואינה מחלקת]\u0006 \u0003באלמנה, מכלל\u0004 הדברים אתה למד כי \u0003אלמנה אפילו בסתמא נמי אית\u0004 \u0005[בסתם גם כן יש]\u0006 \u0003לה\u0004 כתובה, גם אם לא ידע שהיא אלמנה, ולאמיתו של דבר \u0003ולא היא\u0004 \u0005[ואינו כן]\u0006 אלא \u0003כי קתני לה\u0004 \u0005[כאשר שנה את\u0006 דין\u0005]\u0006 ה\u0003אלמנה, אפלוגתא\u0004 \u0005[לגבי החלוקה]\u0006 של \u0003אילונית קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 לומר שאלמנה דינה כאיילונית, שאף בה יש לחלק אם ידע בה או לא ידע בה מתחילה, אלא שהזכיר במשנה רק את האיילונית והוא הדין גם לאלמנה.","","","\u0003הנושא את האשה ופסקה עמו,\u0004 כלומר, קבעה איתו תנאי \u0003כדי שיזון את בתה\u0004 שנולדה לה מאיש אחר, במשך \u0003חמש שנים — חייב לזונה חמש שנים\u0004 בכל מקרה, שהרי התחייב לעשות כן.","ואם נתגרשה האשה בתוך הזמן הזה ו\u0003ניסת\u0004 (נישאה) \u0003לאחר, ופסקה\u0004 גם \u0003עמו כדי שיזון את בתה חמש שנים — חייב\u0004 אף הוא \u0003לזונה חמש שנים.\u0004 ו\u0003לא יאמר הראשון: לכשתבא\u0004 הבת \u0003אצלי אזונה, אלא מוליך לה מזונותיה למקום שאמה\u0004 נמצאת בו.","\u0003וכן לא יאמרו שניהם \"הרי אנו זנין אותה כאחד\",\u0004 כלומר, ששניהם יזונו אותה בשותפות, \u0003אלא אחד זנה\u0004 בפועל, \u0003ואחד נותן לה דמי מזונות.\u0004","\u0003ניסת\u0004 (נישאת) אותה בת בתוך הזמן הזה — \u0003הבעל\u0004 שנשא אותה הוא ש\u0003נותן לה מזונות,\u0004 כדין חובת הבעל לאשתו, \u0003והן\u0004 שניהם \u0003נותנין לה דמי מזונות.\u0004 אם \u0003מתו\u0004 שני הבעלים הללו — \u0003בנותיהן\u0004 שלהם \u0003ניזונות מנכסים בני חורין\u0004 משום תנאי כתובה, \u0003והיא,\u0004 בת אשתו, \u0003ניזונת מנכסים משועבדים, מפני שהיא כבעלת חוב,\u0004 שהרי נתחייב לה בשטר ושטרה קודם.","\u0003הפקחים\u0004 שנשותיהם היו מתנות איתם שיזונו את בנותיהן, \u0003היו כותבים\u0004 ומפרשים: \u0003על מנת שאזון את בתך חמש שנים כל זמן שאת עמי,\u0004 שלא יצטרכו לזון בת שאינה שלהם, בזמן שאמה אינה נשואה עוד להם.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003האומר לחבירו \"חייב אני לך מנה\". ר' יוחנן אמר: חייב\u0004 לתת לו, \u0003וריש לקיש אמר: פטור.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לנוכחים שם \u0003\"אתם עדיי\u0004 שאני מודה לו \u0003\" — מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ריש לקיש דקפטר\u0004 \u0005[שפטר],\u0006 הרי בפירוש הודה בפני עדים! \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אמר להו\u0004 \u0005[להם]\u0006 \u0003\"אתם עדיי\" — מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן דקמחייב\u0004 \u0005[שמחייב]?\u0006 והרי בלא שאומר במפורש \"אתם עדי\" אין בדבריו כלום!","","ומשיבים: \u0003לעולם\u0004 תפרש ש\u0003לא קאמר להו\u0004 \u0005[להם]\u0006 \u0003\"אתם עדיי\", והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"חייב אני לך מנה בשטר\". ר' יוחנן אמר: חייב,\u0004 ומדוע — \u0003אלימא מילתא דשטרא כמאן דאמר להו\u0004 \u0005[חזק הדבר\u0006 שמזכיר ענין \u0005שטר כמו שאומר להם]\u0006 \u0003\"אתם עדים\" דמי\u0004 \u0005[נחשב].\u0006 \u0003ריש לקיש אמר: פטור,\u0004 כי לדעתו \u0003לא אלימא מילתא דשטרא\u0004 \u0005[אין חזק הדבר של\u0006 הזכרת \u0005השטר]\u0006 כדי שייחשב כהודאה של ממש.","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנושא את האשה ופסקה עמו לזון את בתה חמש שנים — חייב לזונה חמש שנים. מאי לאו כי האי גוונא\u0004 \u0005[האם לא\u0006 מדובר שם ב\u0005כגון זה],\u0006 שאמר לה, או שמסר לה שטר שאין בו קנין או חתימה, שאם לא כן — מה החידוש בדבר? וקשה אם כן על ריש לקיש הפוטר בכגון זה!"],["\u0003לא,\u0004 פה מדובר \u0003בשטרי פסיקתא\u0004 \u0005[פסיקה]\u0006 שבהם נקבעים הסכומים שמבטיחים המחותנים מצד החתן ומצד הכלה, ושטרות אלה למרות שאין בהם קנין — הרי הם תקפים כאילו היה בהם קנין. \u0003וכ\u0004דברי \u0003רב גידל,\u0004 ש","\u0003אמר רב גידל אמר רב:\u0004 כאשר דנים המחותנים ביניהם ואומרים: \u0003כמה אתה נותן לבנך?\u0004 ואומר האב: \u0003כך וכך.\u0004 ושואל לאבי הכלה: \u0003וכמה אתה נותן לבתך?\u0004 ומשיב: \u0003כך וכך.\u0004 אם מתוך כך \u0003עמדו וקידשו\u0004 — הרי \u0003קנו\u0004 בשעת קידושין את כל מה שנאמר בתנאים הללו של ההורים. \u0003הן הן הדברים הנקנין באמירה,\u0004 שאינם צריכים קנין או שטר מפורש, אלא הבטחה בלבד יש בה כדי לחייב.","ושואלים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כתב לכהן\u0004 שרוצה לפדות את בנו אצלו: \u0003\"שאני חייב לך חמש סלעים\"\u0004 — הרי \u0003חייב ליתן לו חמש סלעים, ובנו אינו פדוי.\u0004 ולדעת ריש לקיש, אם הבן אינו פדוי בכך, מפני מה חייב לתת לו, והרי לא היה ממש בשטר זה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שהוא \u0003משועבד ליה מדאורייתא\u0004 \u0005[לו מן התורה]\u0006 לפדות גם בלי שיכתוב זאת בשטר. ומקשים: \u0003אי הכי, אמאי\u0004 \u0005[אם כך, מדוע]\u0006 \u0003כתב\u0004 שטר כלל? ומשיבים: \u0003כדי לברר לו כהן,\u0004 להודיע שרוצה לפדות את בנו אצל כהן זה, ולא אצל אחר.","ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בנו אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו פדוי?\u0004 הרי כתב לו שטר ומשועבד לכך מן התורה! ומשיבים: \u0003כ\u0004דברי \u0003עולא.\u0004 ש\u0003אמר עולא: דבר תורה\u0004 (מדין תורה) — בנו \u0003פדוי לכשיתן\u0004 את הכסף, \u0003ומאי טעמא\u0004 \u0005[ומה טעם]\u0006 \u0003אמרו\u0004 ש\u0003בנו אינו פדוי? — גזירה שמא יאמרו פודין בשטרות\u0004 בלבד, שיוכל לתת לפדיון בנו גם שטר חוב על אחר הנמצא בידו, והתורה אמרה שפדיון הבן אינו אלא בכסף.","\u0003אמר רבא:\u0004 מחלוקת ר' יוחנן וריש לקיש היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 אחרת שנחלקו בבעיה דומה: \u0003ערב היוצא אחר חיתום שטרות,\u0004 כלומר, שלאחר שנחתם השטר כתב אדם שהוא ערב לחוב הזה, במקרה זה — \u0003גובה\u0004 המלווה רק \u0003מנכסים בני חורין\u0004 של הערב שמאחר שלא היתה הערבות חלק מן השטר ממש, הרי זה כמלוה על פה שאין גובים אותו מנכסים משועבדים.","ומסופר: \u0003מעשה\u0004 כגון זה \u0003בא לפני ר' ישמעאל, ואמר: גובה מנכסים בני חורין. אמר לו בן ננס: אינו גובה לא מנכסים בני חורין ולא מנכסים משועבדים,\u0004 שמה שכתב הערב אין לו ערך משפטי כלל.","\u0003אמר לו\u0004 ר' ישמעאל: \u0003למה? אמר לו\u0004 בן ננס: \u0003הרי שהיה חונק את חבירו בשוק\u0004 ותובע ממנו שיחזיר לו כסף שחייב לו, \u0003ומצאו חבירו\u0004 של הנחנק \u0003ואמר לו\u0004 לחונק: \u0003הנח לו, ואני אתן לך\u0004 מה שאתה תובע ממנו. הרי למרות שהתחייב — \u0003פטור\u0004 מלשלם, ומדוע — \u0003שלא על אמונתו הלוהו,\u0004 שהרי ההלוואה מתחילה לא היתה על סמך האמונה שהאמין בחבר שיפרע לו, שהרי חבר זה בא והבטיח רק לאחר מכן, ולכן אין כאן התחייבות כלל, וכן הוא גם במקרה של ערב לאחר חיתום שטרות.","ואם כן, \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 במחלוקת ר' יוחנן וריש לקיש הראשונה, ש\u0003ר' יוחנן\u0004 ש\u0003אמר כ\u0004דברי \u0003ר' ישמעאל\u0004 שיש ממשות בהתחייבות זו שקיבל על עצמו, \u0003וריש לקיש\u0004 ש\u0003אמר כ\u0004דברי \u0003בן ננס.\u0004","ודוחים: \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003בן ננס כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאם כתב לו בשטר \"חייב אני לך מנה\" שהתחייבות כזו אינה התחייבות,"],["\u0003כי פליגי אליבא\u0004 \u0005[כאשר נחלקו,\u0006 הרי זה \u0005לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' ישמעאל. ר' יוחנן כ\u0004דברי \u0003ר' ישמעאל\u0004 כפשוטם, \u0003וריש לקיש\u0004 סבור כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[\u0006ש\u0005אמר]\u0006 \u0003ר' ישמעאל התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 ש\u0003שייך ליה\u0004 \u0005[לו\u0006 הענין\u0005]\u0006 \u0003לשיעבודא דאורייתא\u0004 \u0005[לשיעבוד מן התורה],\u0006 שכן ערב משועבד מן התורה \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003לא שייך שיעבודא דאורייתא\u0004 \u0005[שעבוד מן התורה]\u0006 כלל, שהרי לא היתה לאיש כל התחייבות מוקדמת.","\u0003גופא\u0004 (לגופה) של הלכה שהזכרנו קודם, \u0003אמר רב גידל אמר רב,\u0004 אמר אבי הבת: \u0003\"כמה אתה נותן לבנך\"?\u0004 ואמר לו אבי הבן: \u0003\"כך וכך\".\u0004 ושאל אותו אבי הבן: \u0003\"וכמה אתה נותן לבתך\"? —\u0004 והשיב לו: \u0003\"כך וכך\". עמדו וקידשו — קנו\u0004 את כל הדברים שהתנו ההורים ביניהם בלי לעשות קנין, שכן \u0003הן הן הדברים הנקנים באמירה.\u0004","\u0003אמר רבא: מסתברא מילתא\u0004 \u0005[מסתבר דברו]\u0006 של \u0003רב בבתו נערה,\u0004 וטעם הדבר — \u0003דקא מטי\u0004 \u0005[שבאה]\u0006 \u0003הנאה לידיה\u0004 \u0005[לידו]\u0006 של האב, שכן הוא זוכה בכסף קידושיה ובכתובתה, וכיון שיש לו הנאה בכך, הריהו גומר ומקנה מה שהבטיח באמירה בלבד, \u0003אבל בוגרת\u0004 ש\u0003לא מטי\u0004 \u0005[באה]\u0006 \u0003הנאה לידיה\u0004 \u0005[לידו],\u0006 שהרי כסף הקידושין והכתובה שייכים רק לה — \u0003לא.\u0004","והוסיף רבא בלשון שבועה: \u0003והאלהים!\u0004 לאמיתו של דבר \u0003אמר רב: אפילו\u0004 ב\u0003בוגרת\u0004 הדין כן. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 \u0003אבי הבן מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003הנאה אתא לידיה\u0004 \u0005[באה לידו]\u0006 שמקנה באמירה בלבד? \u0003אלא\u0004 צריכים לומר שסבור רב כי \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקמיחתני אהדדי גמרי ומקני להדדי\u0004 \u0005[שמתחתנים זה בזה\u0006 ומרוצים בכך, הרי הם \u0005גומרים ומקנים\u0006 את הדברים \u0005זה לזה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: דברים הללו\u0004 של תנאי נישואין \u0003ניתנו ליכתב\u0004 (להכתב), כלומר, אם באים להחתים עדים וכיוצא בזה ולעשות את התנאים הללו כשטר גמור, האם אפשר לעשות זאת, \u0003או לא ניתנו ליכתב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ניתנו ליכתב.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במשנתנו: \u0003הפקחין היו כותבין \"על מנת שאזון את בתך חמש שנים כל זמן שאת עמי\",\u0004 משמע שניתן הדבר להיכתב! ענה לו רב אשי: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כותבין\" — אומרים.\u0004","ושאל שוב רבינא: \u0003וקרי ליה\u0004 \u0005[ו\u0006כי \u0005קורא לה\u0006 התנא\u0005]\u0006 \u0003לאמירה כתיבה?\u0004 ענה לו: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב לאשתו \"דין ודברים אין לי בנכסייך\", ותני\u0004 \u0005[ושנה]\u0006 \u0003ר' חייא\u0004 כביאור לדבר: \u0003האומר לאשתו,\u0004 משמע שאמירה קרויה כתיבה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003אין כותבין שטרי אירוסין ונשואין אלא מדעת שניהם.\u0004 ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003מדעת שניהם — כותבין. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה ב\u0003שטרי פסיקתא\u0004 \u0005[פסק],\u0006 כלומר, בתנאים של הנישואין, והרי שצריך כתיבה!","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לשטרי אירוסין ממש.\u0004 כלומר, שמקדש את האשה בשטר, ושטר זה צריך להיות כתוב מדעת שניהם. \u0003כ\u0004מו שאמרו \u0003רב פפא ורב שרביא. דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003כתבו\u0004 הבעל לשטר אירוסין \u0003לשמה\u0004 של אשה מסויימת, \u0003ושלא מדעתה,\u0004 שהיא לא ידעה זאת — \u0003רבה ורבינא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מקודשת, רב פפא ורב שרביא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אינה מקודשת.\u0004","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו במשנתנו: \u0003מתו\u0004 שני הבעלים הללו — \u0003בנותיהן ניזונות מנכסים בני חורין, והיא\u0004 הבת שהיה עליה התנאי \u0003ניזונת מנכסים משועבדים, מפני שהיא כבעלת חוב.\u0004 משמע שלא מסתפקים באמירה אלא כתבו זאת בשטר, שכן אחרת לא היתה יכולה לטרוף מנכסים משועבדים!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בשקנו מידו,\u0004 שעשו מעשה קנין ובמקרה זה ודאי אפשר לכתוב שטר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהיה שם קנין, אם כן ה\u0003בנות\u0004 שלו \u0003נמי\u0004 \u0005[גם כן]\u0006 יטרפו מנכסים משועבדים! ומשיבים: מדובר \u0003ב\u0004אופן \u0003שקנו לזו ולא קנו לזו,\u0004 שעשו קנין לצורך בת אשתו, ולא לבנות שנולדו להם לאחר שנישאו.","ושואלים: \u0003ומאי פסקא\u0004 \u0005[ומהי הפסיקה],\u0006 מה גורם להחליט שדווקא במקרה זה עשו קנין ולענין אחר לא עשו קנין? ומשיבים: \u0003איהי\u0004 \u0005[היא]\u0006 הבת שהיתה לאשה מבעלה הקודם \u0003דהואי\u0004 \u0005[שהיתה]\u0006 \u0003בשעת קנין\u0004 כשנישאת — \u0003מהני\u0004 \u0005[מועיל]\u0006 \u0003לה\u0004 ה\u0003קנין,\u0004 ואילו ה\u0003בנות\u0004 שנולדו להם לאחר הנישואין ש\u0003לא הוו\u0004 \u0005[היו]\u0006 \u0003בשעת\u0004 ה\u0003קנין — לא מהני להו\u0004 \u0005[מועיל להן]\u0006 ה\u0003קנין.\u0004","ומקשים: \u0003מי לא עסקינן דהואי\u0004 \u0005[האם אין אנו עוסקים\u0006 גם במקרה \u0005שהיו]\u0006 הבנות \u0003בשעת קנין, והיכי דמי\u0004 \u0005[וכיצד\u0006 יכול להיות \u0005הדבר]\u0006 שיהיו בנות שניהם בשעת הקנין — \u0003כגון\u0004 ש\u0003גרשה ואהדרה\u0004 \u0005[והחזירה]\u0006 והיו להם בנות משותפות מנישואיהם הקודמים!","\u0003אלא\u0004 כך צריך לומר: \u0003איהי דליתא\u0004 \u0005[היא,\u0006 בתו החורגת \u0005שאינה]\u0006 נכללת \u0003בתנאי בית דין,\u0004 שאין לה זכות למזונות בדרך כלל — \u0003מהני\u0004 \u0005[מועיל]\u0006 \u0003לה קנין,\u0004 ואילו ה\u0003בנות\u0004 שלו \u0003דאיתנהו\u0004 \u0005[שיש להן]\u0006 זכות מתוך \u0003תנאי בית דין — לא מהני להו\u0004 \u0005[מועיל להן]\u0006 ה\u0003קנין.\u0004","ותוהים: האם משום שיש להן תנאי בית דין \u0003מגרע גרעי\u0004 \u0005[גרועות\u0006 הן \u0005יותר]?\u0006 להיפך, כיון שיש גם תנאי בית דין שיתפרנסו, לכאורה צריך היה להיות כוחן עדיף! \u0003אלא\u0004 כך צריך לומר: \u0003בנותיו היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 \u0003כיון דאיתנהו\u0004 \u0005[ש\u0006הן \u0005ישנן]\u0006 \u0003בתנאי בית דין\u0004 ודרך בני אדם לדאוג לפרנסתן, \u0003אימר צררי אתפסינהו\u0004 \u0005[אמור\u0006 ש\u0005צרורות,\u0006 כסף, \u0005התפיס,\u0006 נתן, \u0005להן]\u0006 כתשלומים עבור המזונות כבר בחייו ולכן אינן יכולות לגבות מן המשועבדים שמא יש להן כבר כדי צרכן, אבל בת זו שהיא חורגת, ואין עליה תנאי בית דין — אין אנו חוששים שנתן לה משלו כלום.","שנינו במשנה: \u0003לא יאמר הראשון\u0004 הרי אני זנה רק כשתהיה אצלי, אלא מוליך מזונות למקום שבו מצויות היא ואמה. \u0003אמר רב חסדא: זאת אומרת\u0004 שבמקרה של גירושין הולכת ה\u0003בת\u0004 ומתגוררת \u0003אצל אמה,\u0004 ולא אצל אביה.","ושואלים: מנין לרב חסדא זאת, \u0003ממאי\u0004 \u0005[ממה],\u0006 מנין יודע אתה ש\u0003ב\u0004בת \u0003גדולה עסקינן\u0004 \u0005[אנו עוסקים],\u0006 ומטעם זה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004בת \u0003קטנה עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003ומשום מעשה שהיה,\u0004 שחוששים לחייה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שמת והניח בן קטן לאמו, יורשי האב אומרים: יהא\u0004 הבן \u0003גדל אצלנו, ואמו אומרת: יהא בני גדל אצלי — מניחין אותו אצל אמו, ואין מניחין אותו אצל\u0004 מי שהוא \u0003ראוי ליורשו. מעשה היה\u0004 בילד כזה \u0003ושחטוהו\u0004 יורשיו \u0003ערב הפסח!\u0004 ולכן אף בקטנה שיש לגביה התחייבויות, אין משאירים אותה אצל אנשים העלולים להזיק לה כדי להפטר מהתחייבותם. ואם כן מנין לו לומר שתמיד הולכת הבת לדור במחיצת אימה?","ומשיבים: \u0003אם כן ליתני\u0004 \u0005[שישנה]\u0006 \u0003למקום שהיא\u0004 בדרך כלל, בלי לפרט היכן,"],["\u0003מאי\u0004 \u0005[מה]\u0006 החזרה וההדגשה \u0003למקום שאמה? שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 כי במקרה של גירושין הולכת ה\u0003בת אצל האם, לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003גדולה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003קטנה.\u0004","שנינו במשנה שאם היו שנים מחוייבים במזונות הבת \u0003לא יאמרו שניהם\u0004 שהם שותפים בהזנתה, אלא כל אחד ממלא אחר התחייבותו לעצמו.","מסופר מעשה: \u0003ההוא גברא דאוגר ליה ריחיא לחבריה\u0004 \u0005[אדם אחד שהשכיר לו ריחיים לחבירו]\u0006 בשכר \u0003טחינה,\u0004 ששוכר הריחיים קיבל עליו כתשלום דמי השכירות לטחון מה שיצטרך המשכיר לעצמו. \u0003לסוף איעתר, זבין ריחיא וחמרא\u0004 \u0005[בסוף התעשר\u0006 המשכיר ו\u0005קנה ריחיים\u0006 נוספות \u0005וחמור]\u0006 ולא הזדקק עוד לטחינתו של השוכר,","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003הוה טחיננא גבך\u0004 \u0005[הייתי טוחן אצלך]\u0006 וזה היה שכרי, \u0003השתא הב\u0004 \u0005[עכשיו תן]\u0006 \u0003לי אגרא\u0004 \u0005[שכר]\u0006 עבור הריחיים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 השוכר: \u0003מיטחן טחיננא לך\u0004 \u0005[אני טוחן בשבילך]\u0006 ולכך הסכמתי, אבל לא למתן שכר.","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רבינא למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו מתניתין\u0004 \u0005[זוהי\u0006 ההלכה האמורה ב\u0005משנתנו]\u0006 \u0003לא יאמרו שניהם \"הרי אנו זנין אותה כאחד\", אלא אחד זנה ואחד נותן לה דמי מזונות.\u0004 שמכאן רצה ללמוד, שאף שהתנאי היה לתת מזונות לבת, הרי כאשר השתנו הנסיבות נותן הוא דמי מזונות. ואף כאן יתן לו השוכר דמי הטחינה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עוירא\u0004 לרבינא: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם, חד כריסא אית\u0004 \u0005[שם, כרס אחת יש]\u0006 \u0003לה, תרתי כריסתא לית\u0004 \u0005[שתי כריסות אין]\u0006 \u0003לה,\u0004 ולכן אין אפשרות בפועל ששניהם יזונו אותה, ואולם \u0003הכא, מצי אמר ליה\u0004 \u0005[כאן, יכול לומר לו]\u0006 השוכר: \u0003טחון\u0004 בריחיים האחרות אותן קנית \u0003וזבין\u0004 \u0005[ומכור]\u0006 לאחרים, ואילו בריחיים בהן אני טוחן \u0003טחון ואותיב\u0004 \u0005[ושמור]\u0006 לאכילתך, וכיון שאפשר שימשיך לטחון אצלו בפועל — אין השוכר חייב לשנות מתנאי ההסכם.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דלית ליה טחינא לריחיא\u0004 \u0005[שאין לו\u0006 לשוכר \u0005טחינה\u0006 אחרת \u0005לריחיים\u0006 שלו\u0005],\u0006 וטחינה זו בשביל המשכיר מספקת לשוכר, ולולא זה יהיו הריחיים בטלות ממלאכה, \u0003אבל\u0004 אם \u0003אית ליה טחינא לריחיא\u0004 \u0005[יש לו טחינה לריחיים]\u0006 בשביל אחרים די צורכו, ויכול לבקש תשלום עבור הטחינה הזו ולשלם דמי שכירות, אלא שמתעקש על קיום תנאי ההסכם — \u0003כגון זו כופין אותו על מדת סדום,\u0004 שבכל דבר שאדם אינו מפסיד ואחר גם נהנה משלו — כופים אותו שלא ינהג ברשעות סתם כמנהג סדום.","\u0003אלמנה שאמרה: אי אפשי\u0004 (אין רצוני) \u0003לזוז מבית בעלי\u0004 אלא להשאר שם — \u0003אין היורשין יכולין לומר לה: \"לכי לבית אביך ואנו זנין אותך\", אלא זנין אותה\u0004 בבית בעלה, \u0003ונותנין לה מדור\u0004 (מקום לדור) \u0003לפי כבודה.\u0004","אבל אם \u0003אמרה: \"אי אפשי לזוז מבית אבא\"\u0004 ואתם תביאו לי מזונותי לשם — \u0003יכולין היורשין לומר לה: אם את\u0004 דרה \u0003אצלנו\u0004 בבית אבינו — \u0003יש ליך\u0004 (לך) \u0003מזונות\u0004 מן הנכסים שירשנו מאבינו, \u0003ואם אין את אצלנו — אין ליך\u0004 (לך) \u0003מזונות.\u0004","\u0003אם היתה טוענת\u0004 שאינה רוצה לדור בבית בעלה המנוח \u0003מפני שהיא ילדה\u0004 (צעירה) \u0003והן\u0004 היתומים \u0003ילדים,\u0004 ואין הדבר נאה שיהיו בבית אחד — \u0003זנין אותה והיא בבית אביה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אלמנה שנשארה בבית בעלה \u0003משתמשת במדור\u0004 (בדירה) \u0003כדרך\u0004 שהיתה \u0003משתמשת בחיי בעלה.\u0004 ומשתמשת \u0003בעבדים ושפחות כדרך שמשתמשת\u0004 בהם \u0003בחיי בעלה. בכרים וכסתות כדרך שמשתמשת בחיי בעלה. בכלי כסף ובכלי זהב כדרך שמשתמשת בחיי בעלה.\u0004 ואין נוטלים ממנה דבר ממה שהיתה נוהגת בחיי הבעל. \u0003שכך כתב לה\u0004 בנוסח הכתובה: \u0003\"ואת תהא יתבת\u0004 \u0005[תהיי יושבת]\u0006 \u0003בביתי ומיתזנא\u0004 \u0005[וניזונת]\u0006 \u0003מנכסי כל ימי מגר ארמלותיך\u0004 \u0005[מגורי אלמנותך]\u0006 \u0003בביתי\".\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 הלשון \u0003\"בביתי\"\u0004 בא למעט ולומר — \u0003ולא בבקתי\u0004 (בבקתה שלי), שאם היה הבית קטן ביותר, אינה יכולה לחייב את היורשים שתמשיך לדור שם איתם.","\u0003אמר רב נחמן: יתומים שמכרו מדור אלמנה — לא עשו ולא כלום.\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003ר' אסי\u0004 בשם \u0003ר' יוחנן?\u0004 ש\u0003אמר ר' אסי אמר ר' יוחנן: יתומים שקדמו ומכרו בנכסים מועטין\u0004 (נכסים שאינם יותר מכדי מזון הבנות), אף על פי שהדין הוא שנכסים מועטים משאירים לצורך מזון היתומות, מכל מקום \u0003מה שמכרו — מכרו.\u0004 הרי שאף שנהגו שלא כראוי — המכר קיים. ומדוע אין מכירת מדור האלמנה מתקיימת?","ומשיבים: \u0003התם לא משתעבדי\u0004 \u0005[שם אין\u0006 הנכסים \u0005משתעבדים]\u0006 \u0003לה מחיים,\u0004 שהשעבוד לצורך מזון הבנות חל רק משעת מותו של אביהן ולא קודם לכן, ואילו \u0003הכא משתעבדי\u0004 \u0005[כאן משתעבדים]\u0006 \u0003לה\u0004 הנכסים גם \u0003מחיים,\u0004 שהרי עוד בחייו היה צריך לתת לה מקום לדור בו, ולכן לא עשו ולא כלום.","\u0003אמר אביי: נקיטינן\u0004 \u0005[מוחזקים אנו]:\u0006 \u0003מדור אלמנה שנפל — אין היורשין חייבין לבנותו\u0004 מחדש,","שאינם חייבים אלא להחזיקה במקום שהיה משועבד לה, אבל כשלעצמם אינם צריכים לדאוג לה לדירה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מדור אלמנה שנפל — אין היורשין חייבין לבנותו. ולא עוד, אלא אפילו היא אומרת \"הניחוני ואבננו משלי\" — אין שומעין לה,\u0004 ואין הם חייבים לקבל את דבריה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי:\u0004 אם \u0003שיפצה\u0004 (תיקנה) את הדירה, ולא בנתה אותה מחדש, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם יכולים היורשים לומר לה שכיון שהבית דורש שיפוץ הרי זה כמו שנפל ותצא ממנו, או כיון שעדיין הוא יכול לעמוד אינם יכולים למונעה מלדור בו ואף לשפצו\u0005?\u0006 לשאלה זו לא היתה תשובה, והריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: \u0003אמרה\u0004 האלמנה ליורשים \u0003אי אפשי\u0004 (אין רצוני) לזוז מבית אבא, ורצוני להיות שם ולקבל שם גם את מזונותי — אין היורשים חייבים במזונותיה.","ושואלים: מדוע הדבר כך, \u0003וליתבו\u0004 \u0005[ושיתנו]\u0006 \u0003לה כי יתבה התם\u0004 \u0005[כאילו היתה יושבת שם]\u0006 בבית בעלה? ומשיבים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב הונא.\u0004 ש\u0003אמר רב הונא: ברכת הבית ברובה,\u0004 שהברכה בבית היא לפי רוב האנשים המצויים שם, שכאשר מצויים בבית אנשים רבים יותר ההוצאות לכל נפש קטנות יותר. ולכן אומרים היורשים לאשה, שאם תשאר גם היא בבית — אין הוצאה מרובה עבורה אבל בהמצאת מזונות לעצמה, מתרבה ההוצאה.","ושואלים: אם כן, \u0003וליתבו\u0004 \u0005[ושיתנו]\u0006 \u0003לה\u0004 מזונות בבית אביה ויפחיתו לה מהם \u0003לפי\u0004 מה שיכולים להרוויח ב\u0003ברכת הבית?\u0004 ומשיבים: \u0003הכי נמי\u0004 \u0005[\u0006ל\u0005כך גם כן]\u0006 כוונת המשנה, שרשאים להפחית לה לפי החשבון, ולא שימנעו ממנה לגמרי את מזונותיה.","\u0003אמר רב הונא: לשון חכמים ברכה, לשון חכמים עושר, לשון חכמים מרפא.\u0004 כלומר, המדקדק בלשון חכמים יכול ללמוד מדבריהם נוסף לעצם ההלכה גם את כל הדברים הללו. כיצד? \u0003ברכה — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שמתוך לשון חכמים למדים על דרך ברכת הבית.","לשון חכמים \u0003עושר — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוכר פירות לחבירו,\u0004 אם \u0003משך\u0004 הקונה את הפירות \u0003ולא מדד — קנה,\u0004 אם \u0003מדד ולא משך — לא קנה. ואם היה\u0004 הקונה \u0003פקח\u0004 ורוצה להבטיח לעצמו שלא יחזור בו המוכר — \u0003שוכר את מקומו\u0004 ואז קונה מיד משעת המדידה. הרי למדים מכאן ענין של עצה בענייני ממונות.","לשון חכמים \u0003מרפא — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא ילעוס אדם חטין ויניח על גבי מכתו בפסח, מפני ש\u0004החטים \u0003מחמיצות\u0004 על ידי כך, ובדרך אגב למדים מלשון חכמים זו שחיטים לעוסות מועילות למכה, והרי כאן ענין של מרפא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בשעת פטירתו של רבי אמר: לבני אני צריך. נכנסו בניו אצלו. אמר להם\u0004 בצוואתו: \u0003הזהרו בכבוד אמכם.\u0004 ועוד אמר: \u0003נר\u0004 שלי \u0003יהא דלוק במקומו, שולחן יהא ערוך במקומו, מטה תהא מוצעת במקומה. יוסף חפני שמעון אפרתי — הם שמשוני בחיי, והם ישמשוני במותי.\u0004","ומבארים את הדברים ביחס למה שאמר להם \u0003הזהרו בכבוד אמכם,\u0004 ושואלים: כיבוד אם הלא מצוה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כבד את אביך ואת אמך\"\u0004 (שמות כ, יב)! ומשיבים: \u0003אשת אב הואי\u0004 \u0005[היתה],\u0006 כלומר לא אמם היתה אלא אם חורגת, ולכן הוצרך להזהירם על כבודה.","ושואלים: הלא החובה לכבד את \u0003אשת\u0004 ה\u0003אב נמי דאורייתא\u0004 \u0005[גם כן מן התורה]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"כבד את אביך ואת אמך\"\u0004 ויש בכתוב זה ביטויים הבאים לרבות, \u0003\"את אביך\"\u0004 — \"את\" בא לרבות \u0003זו אשת אביך, \"ואת אמך\"\u0004 — \"את\" בא לרבות, \u0003זו בעל אמך,\u0004 כלומר, אב חורג, \u0003וי\"ו יתירה\u0004 (של \"ואת\") — \u0003לרבות את אחיך הגדול!\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 שחייב לכבד את אשת אביו הוא דווקא \u0003מחיים,\u0004 בחיי האב ומשום כבודו. \u0003אבל לאחר מיתה — לא,\u0004 ולכן הצטרך רבי להזהיר את בניו על כך.","ומה שציוה אותם \u0003\"נר יהא דלוק במקומו, שולחן יהא ערוך במקומו מטה תהא מוצעת במקומה\", מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כל בי שמשי\u0004 \u0005[בין השמשות\u0006 של ערב שבת\u0005]\u0006 \u0003הוה אתי לביתיה\u0004 \u0005[היה\u0006 רבי \u0005בא לביתו]\u0006 כבחייו, ולכן הוצרך לכל אלו.","ואגב זה מסופר: \u0003ההוא בי שמשא אתאי שבבתא, קא קריה אבבא\u0004 \u0005[פעם\u0006 אחת \u0005בין השמשות\u0006 בערב שבת \u0005באה שכנה\u0006 ו\u0005דפקה על הדלת],\u0006 \u0003אמרה אמתיה\u0004 \u0005[שפחתו]:\u0006 \u0003שתיקו\u0004 \u0005[שתקי],\u0006 ש\u0003רבי יתיב\u0004 \u0005[יושב].\u0006 \u0003כיון\u0004 ש\u0003שמע\u0004 רבי את דבריה, \u0003שוב לא אתא\u0004 \u0005[בא],\u0006 כדי \u0003שלא להוציא לעז על צדיקים הראשונים\u0004 שלא התגלו בפני משפחתם לאחר מותם.","ועל מה שאמר \u0003\"יוסף חפני שמעון אפרתי הם שמשוני בחיי והם ישמשוני במותי\". סבור מינה בהדין עלמא\u0004 \u0005[חשבו מכאן\u0006 ש\u0005בעולם הזה],\u0006 \u0003הוא דקאמר\u0004 \u0005[שאמר]\u0006 שחשבו שהתכוון לומר שהם יהיו המטפלים בקבורתו, \u0003כיון דחזו דקדים ערסייהו לערסיה\u0004 \u0005[שראו שקדמה מיטתם למיטתו,\u0006 שהם מתו לפניו\u0005],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003שמע מינה לההוא עלמא\u0004 \u0005[למד מכאן לאותו עולם,\u0006 לעולם הבא\u0005]\u0006 \u0003הוא דקאמר\u0004 \u0005[שאמר],\u0006 שהם ישמשו אותו גם כן לאחר מותו.","\u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003אמר הכי\u0004 \u0005[כך] —\u0006 כדי ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 הבריות: \u0003מילתא הואי להו\u0004 \u0005[דבר\u0006 מגונה \u0005היה בהם]\u0006 \u0003ועד האידנא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003זכותו\u0004 של \u0003רבי הוא דאהניא להו\u0004 \u0005[היא שהועילה להם]\u0006 שלא מתו בחטאם, וכיון שמת רבי שוב לא הגנה עליהם זכותו ומתו, ולכן הודיע שמתו כדי שיתלוו עימו במותו.","ועוד \u0003אמר להן\u0004 רבי למשמשיו: \u0003לחכמי ישראל אני צריך. נכנסו אצלו חכמי ישראל, אמר להן: \"אל תספדוני בעיירות,\u0004"],["\u0003והושיבו ישיבה\u0004 שתחזור ללימודים הסדירים \u0003לאחר שלשים יום\",\u0004 ולא תבטלו עוד מלימוד בגלל האבל. \u0003\"שמעון בני חכם, גמליאל בני\u0004 יהא \u0003נשיא, חנינא בר חמא ישב בראש\u0004 הישיבה\u0003\".\u0004","ומסבירים: מה שאמר \u0003\"אל תספדוני בעיירות\", סבור מינה\u0004 \u0005[חשבו\u0006 לדון \u0005מכאן]\u0006 ש\u0003משום טרחא הוא דקאמר\u0004 \u0005[שאמר],\u0006 שלא רצה שירבו בטירחה עבורו, שאם יספידוהו בכל עיירה, יתעכבו הרבה בדרך. \u0003כיון דחזי דקספדי\u0004 \u0005[שראו שהיו סופדים]\u0006 \u0003בכרכים וקאתו כולי עלמא\u0004 \u0005[והיו באים הכל\u0006 לכרך\u0005],\u0006 שהיו הכל טורחים כדי לבוא להשתתף בהספדים, \u0003אמרו: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003משום יקרא\u0004 \u0005[כבוד]\u0006 \u0003הוא דקאמר\u0004 \u0005[שאמר],\u0006 שאם היו סופדים אותו בעיירות היו אלה הספדים קטנים ולא ראויים, ובאופן זה התאסף קהל גדול והיה לו כבוד.","ומה שציוה \u0003\"הושיבו ישיבה לאחר שלשים יום\",\u0004 טעמו — \u0003דלא עדיפנא\u0004 \u0005[שאין אני עדיף]\u0006 \u0003ממשה רבינו, דכתיב\u0004 \u0005[שנאמר]\u0006 בו בפטירתו: \u0003\"ויבכו בני ישראל את משה בערבת מואב שלשים יום\"\u0004 (דברים לד, ח), ועניינו: \u0003תלתין יומין ספדין ביממא וליליא\u0004 \u0005[שלושים יום\u0006 שלאחר הפטירה היו \u0005סופדים ביום ובלילה],\u0006 \u0003מכאן ואילך ספדו ביממא וגרסי בליליא\u0004 \u0005[\u0006היו \u0005סופדים ביום ולומדים בלילה],\u0006 \u0003או ספדו בליליא וגרסי ביממא\u0004 \u0005[סופדים בלילה ולומדים ביום],\u0006 \u0003עד דספדי תריסר ירחי שתא\u0004 \u0005[שספדו שנים עשר חודשי שנה].\u0006","מסופר: \u0003ההוא יומא דאשכבתיה\u0004 \u0005[אותו יום של הלווייתו]\u0006 של \u0003רבי נפקא בת קלא\u0004 \u0005[יצאה בת קול]\u0006 \u0003ואמרה: כל\u0004 מי \u0003דהוה באשכבתיה\u0004 \u0005[שהיה בהלווייתו]\u0006 של \u0003רבי, מזומן הוא לחיי העולם הבא. ההוא כובס\u0004 (כובס אחד) \u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003הוה אתי קמיה\u0004 \u0005[היה בא לפני\u0006 רבי\u0005],\u0006 \u0003ההוא יומא\u0004 \u0005[אותו יום]\u0006 \u0003לא אתא\u0004 \u0005[בא]\u0006 ונמצא שלא היה בהלוויה. \u0003כיון\u0004 ש\u0003שמע הכי\u0004 \u0005[כך],\u0006 שמת רבי, מחמת צער \u0003סליק לאיגרא\u0004 \u0005[עלה לגג]\u0006 \u0003ונפל לארעא ומית\u0004 \u0005[לארץ ומת].\u0006 \u0003יצתה\u0004 (יצאה) \u0003בת קול ואמרה: אף ההוא כובס מזומן הוא לחיי העולם הבא.\u0004","על מה שציווה רבי \u0003\"שמעון בני חכם,\u0004 גמליאל בני נשיא \u0003\",\u0004 שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירוש דבריו אלה? ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי ששמעון בני חכם\u0004 יותר, מכל מקום יהיה \u0003גמליאל בני נשיא.\u0004","\u0003אמר לוי: צריכא למימר\u0004 \u0005[\u0006וכי \u0005צריך היה\u0006 דבר זה \u0005לאמרו],\u0006 הלא גמליאל היה הבכור? \u0003אמר ר' שמעון בר רבי: צריכא\u0004 \u0005[צריך\u0006 הדבר\u0005]\u0006 \u0003לך ולמטלעתך\u0004 \u0005[ולצליעתך],\u0006 ולפי שלוי היה צולע, לכן אמר לו בלשון זו. ומסבירים: \u0003מאי קשיא ליה\u0004 \u0005[מה\u0006 היה \u0005קשה לו]\u0006 לר' שמעון שלגלג על שאלתו של לוי — \u0003הא קרא קאמר\u0004 \u0005[הרי הכתוב אומר]:\u0006 \u0003\"ואת הממלכה נתן ליהורם כי הוא הבכור\"\u0004 (דברי הימים ב כא, ג), משמע שהבכור הוא היורש את מינויו של אביו, ולשם מה היה צריך רבי לצוות על כך במפורש!","ומסבירים: \u0003ההוא,\u0004 יהורם, \u0003ממלא מקום אבותיו הוה\u0004 \u0005[היה],\u0006 שהיה גדול ומוצלח כאביו, ולא היה אף אחד מאחיו חכם כמותו, \u0003ו\u0004אולם \u0003רבן גמליאל אינו ממלא מקום אבותיו הוה\u0004 \u0005[היה],\u0006 שהרי היה ר' שמעון אחיו חכם ממנו, כמבואר, ולכן היה רבי צריך להורות שבכל זאת ימנוהו במקומו.","ושואלים: אם כן היה הדבר, \u0003ורבי מאי טעמא עבד הכי\u0004 \u0005[מה טעם עשה כך]\u0006 שמינהו להיות נשיא, אם אינו ממלא מקום כראוי? ומשיבים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003אינו ממלא מקום אבותיו בחכמה,\u0004 שלא היה גדול בתורה כאביו — \u0003ביראת חטא ממלא מקום אבותיו הוה\u0004 \u0005[היה],\u0006 ולכן ראוי היה לו להתמנות נשיא.","על מה שציווה רבי: \u0003\"חנינא בר חמא ישב בראש\",\u0004 מסופר, ש\u0003לא קיבל ר' חנינא\u0004 מינוי זה, משום \u0003שהיה ר' אפס גדול ממנו שתי שנים ומחצה\u0004 ולא רצה להקדימו במינוי. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אפס ברישא\u0004 \u0005[בראש\u0006 הישיבה\u0005]\u0006 \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' חנינא אבראי\u0004 \u0005[בחוץ]\u0006 שלא היה נאה שישב כתלמיד לפני ר' אפס, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003לוי ויתיב גביה\u0004 \u0005[וישב איתו]\u0006 בחוץ ללמוד יחד איתו.","\u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' אפס ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' חנינא ברישא\u0004 \u0005[בראש\u0006 הישיבה\u0005]\u0006 \u0003ולא הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003ללוי איניש למיתב גביה\u0004 \u0005[איש לשבת איתו]\u0006 \u0003וקאתא\u0004 \u0005[ובא]\u0006 \u0003לבבל. והיינו דאמרי ליה\u0004 \u0005[והוא שאמרו לו]\u0006 \u0003לרב: גברא רבה אקלע\u0004 \u0005[אדם גדול בא]\u0006 \u0003לנהרדעא ומטלע\u0004 \u0005[ו\u0006הוא \u0005צולע]\u0006 \u0003ודריש כלילא שרי\u0004 \u0005[ודרש\u0006 ש\u0005כתר\u0006 שנותנים בראש הכלות \u0005מותר]\u0006 לצאת בו ברשות הרבים בשבת. \u0003אמר\u0004 רב: \u0003שמע מינה נח נפשיה\u0004 \u0005[למד מכאן\u0006 ש\u0005נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' אפס, ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' חנינא ברישא\u0004 \u0005[בראש\u0006 הישיבה\u0005],\u0006 \u0003ולא הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003ללוי איניש למיתב גביה\u0004 \u0005[איש לשבת איתו],\u0006 \u0003וקאתא\u0004 \u0005[ובא]\u0006 לוי לבבל.","ושואלים: ומניין לו לרב שר' אפס נפטר? \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהיה אחרת, ש\u0003ר' חנינא\u0004 הוא ש\u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ור' אפס כדיתיב יתיב\u0004 \u0005[כמו שישב ישב]\u0006 \u0003ולא הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003ללוי איניש למיתב גביה וקאתא\u0004 \u0005[איש לשבת איתו ו\u0006לכן הוא \u0005בא]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור] —\u0006 \u0003לוי לר' אפס מיכף הוה כייף ליה\u0004 \u0005[היה כפוף לו],\u0006 והוא כשלעצמו היה יושב לפניו כתלמיד, ולא היה לו לבא לבבל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003כיון\u0004 ש\u0003אמר רבי \"חנינא בר חמא ישב בראש\" — לא סגי\u0004 \u0005[יכול\u0006 להיות\u0005]\u0006 ש\u0003לא מליך\u0004 \u0005[יהיה ראש]\u0006 ור' אפס שהיה עד עכשיו ראש ישיבה ודאי מת, \u0003דכתיב בהו\u0004 \u0005[ש\u0006הרי \u0005נאמר בהם]\u0006 \u0003בצדיקים: \"ותגזר אמר ויקם לך\"\u0004 (איוב כב, כח).","ושואלים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 שם \u0003ר' חייא:\u0004 ומדוע לא מינה אותו רבי להיות ראש ישיבה? ומשיבים: ר' חייא \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 לפני רבי. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא: אני ראיתי קברו של רבי, והורדתי עליו דמעות!\u0004 משיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הדברים, שרבי סיפר שראה את קברו של ר' חייא.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא: אותו היום שמת רבי בטלה קדושה!\u0004 ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 שרבי הוא שאמר על ר' חייא דבר זה.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשחלה רבי נכנס ר' חייא אצלו ומצאו שהוא בוכה, אמר לו: רבי, מפני מה אתה בוכה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מת מתוך השחוק — סימן יפה לו,\u0004 ואם מת \u0003מתוך הבכי — סימן רע לו.\u0004 מת כאשר \u0003פניו למעלה — סימן יפה לו, פניו למטה — סימן רע לו.\u0004 אם היו \u0003פניו כלפי העם\u0004 (האנשים שסביבו) — \u0003סימן יפה לו,\u0004 ואם היו פניו \u0003כלפי הכותל — סימן רע לו.\u0004 היו \u0003פניו ירוקין — סימן רע לו,\u0004 ואם היו \u0003פניו צהובין ואדומים — סימן יפה לו.\u0004 אם \u0003מת בערב שבת — סימן יפה לו,\u0004 שהולך מיד למנוחת שבת. ואם מת \u0003במוצאי שבת — סימן רע לו.\u0004 ואם \u0003מת בערב יום הכפורים — סימן רע לו,\u0004 שעדיין לא נמחלו לו עוונותיו, מת \u0003במוצאי יום הכפורים — סימן יפה לו,\u0004 שאחר מחילת עוונותיו נפטר. \u0003מת מחולי מעיים — סימן יפה לו, מפני שרובם של צדיקים מיתתן בחולי מעיים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אנא\u0004 \u0005[אני]\u0006 על \u0003תורה ומצות קא בכינא\u0004 \u0005[אני בוכה],\u0006 על שאני מפסיד אותם במותי. מכאן שר' חייא היה בשעת מיתתו של רבי!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003איפוך\u0004 \u0005[הפוך]\u0006 שרב הוא שבא לר' חייא לפני מותו, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את כל הדברים הללו, אלא \u0003ר' חייא עסוק במצות הוה\u0004 \u0005[היה]\u0006 \u0003ורבי סבר לא אפגריה\u0004 \u0005[אמנע אותו]\u0006 מלעסוק במצוות על ידי מינויו כראש ישיבה.","\u0003והיינו\u0004 \u0005[והוא\u0006 הדבר\u0005]\u0006 \u0003דכי הוו מינצו\u0004 \u0005[שכאשר היו רבים]\u0006 \u0003ר' חנינא ור' חייא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא לר' חייא: בהדי דידי מינצת\u0004 \u0005[איתי אתה רב]?\u0006 ש\u0003אם חס ושלום נשתכחה תורה מישראל מהדרנא ליה\u0004 \u0005[מחזיר אני אותה]\u0006 \u0003מפלפולי,\u0004 שעל ידי חריפותי אוכל לחזור ולגלות את הדברים שנשתכחו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא: אנא עבדי\u0004 \u0005[אני עושה]\u0006 ש\u0003לא משתכחה\u0004 \u0005[תשכח]\u0006 \u0003תורה מישראל. דאייתינא כיתנא ושדיינא ומגדלנא נישבי וציידנא טביא ומאכילנא בישרא ליתמי\u0004 \u0005[שאני מביא פשתן וזורע ואורג\u0006 מן הפשתן \u0005רשתות, וצד צבאים\u0006 ושוחט אותם \u0005ומאכיל\u0006 את \u0005בשרם ליתומים]\u0006 \u0003ואריכנא מגילתא ממשכי דטביא\u0004 \u0005[ואני עושה מגילות מעורות צבאים]\u0006 \u0003וסליקנא למתא דלית בה מקרי דרדקי\u0004 \u0005[ואני הולך לעיר שאין בה מלמד תינוקות]\u0006 \u0003וכתיבנא חמשא חומשי לחמשא ינוקי\u0004 \u0005[וכותב אני חמישה חומשים לחמישה תינוקות]\u0006 \u0003ומתנינא שיתא סידרי לשיתא ינוקי\u0004 \u0005[ושונה אני שישה סדרים\u0006 של משנה \u0005לשישה תינוקות],\u0006 \u0003לכל חד וחד אמרי ליה\u0004 \u0005[אחד ואחד אני אומר לו]\u0006 \u0003אתני סידרך לחברך\u0004 \u0005[שנה את סידרך,\u0006 את מה שלמדת, \u0005לחברך]\u0006 ועל ידי כך למדים כולם תורה ומשנה כולה.","\u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר רבי: כמה גדולים מעשה חייא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון ברבי\u0004 לאביו: \u0003אפילו ממך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ר' ישמעאל בר' יוסי: אפילו מאבא\u0004 מר' יוסי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003חס ושלום, לא תהא כזאת בישראל.\u0004 ושוב חוזרים לסיפור פטירתו של רבי.","\u0003אמר להן\u0004 רבי לסובבים אותו: \u0003\"לבני קטן אני צריך\". נכנס ר' שמעון אצלו, מסר לו סדרי חכמה\u0004 כיצד הוא צריך לנהוג, ומה הם עיקרי תורה,","\u0003אמר להן: \"לבני גדול אני צריך\", נכנס רבן גמליאל אצלו, ומסר לו סדרי נשיאות. אמר לו: \"בני, נהוג נשיאותך ברמים\u0004 (ביד רמה), \u0003זרוק מרה בתלמידים\",\u0004 שתנהג בהם בתקיפות שתהא אימתך עליהם.","ושואלים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן היא]\u0006 הדרך? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואת יראי ה' יכבד\"\u0004 (תהלים טו, ד), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003זה יהושפט מלך יהודה, כשהיה רואה תלמיד חכם היה עומד מכסאו, ומחבקו ומנשקו, וקורא לו: רבי רבי, מרי מרי\u0004 \u0005[אדוני אדוני],\u0006 הרי שאפילו מלך כשר נוהג קירבה לתלמידים!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003הא בצינעא\u0004 \u0005[זה בצינעה]\u0006 שהיה בין שניהם — היה מכבד ומחבב את התלמידים, \u0003הא בפרהסיא\u0004 \u0005[זה ברבים],\u0006 צריך שתהא אימתו מוטלת עליהם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי\u0004 היה \u0003מוטל\u0004 בשעת חוליו \u0003בציפורי, ומקום מוכן לו\u0004 לקבורה \u0003בבית שערים.\u0004 ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"צדק צדק תרדף\"\u0004 (דברים טז, כ) — \u0003הלך אחר רבי לבית שערים,\u0004 משמע ששם היה מקום מגוריו הקבוע!","ומשיבים: \u0003רבי בבית שערים הוה\u0004 \u0005[היה\u0006 גר\u0005],\u0006 \u0003אלא כיון דחלש\u0004 \u0005[שחלה\u0006 ונחלש\u0005]\u0006 \u0003אמטיוהי\u0004 \u0005[העבירו אותו]\u0006 \u0003לציפורי,\u0004"],["\u0003דמדליא ובסים אוירא\u0004 \u0005[ש\u0006היא \u0005גבוהה ומבושם אוירה].\u0006","מסופר: \u0003ההוא יומא דנח נפשיה\u0004 \u0005[אותו יום שנחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבי, גזרו רבנן תעניתא, ובעו רחמי\u0004 \u0005[תענית וביקשו רחמים],\u0006 \u0003ואמרי\u0004 \u0005[ואמרו]:\u0006 \u0003כל מאן דאמר\u0004 \u0005[מי שיאמר]\u0006 \u0003\"נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבי\"\u0004 — \u0003ידקר בחרב.\u0004","\u0003סליקא אמתיה\u0004 \u0005[עלתה שפחתו]\u0006 של \u0003רבי לאיגרא\u0004 \u0005[לגג]\u0006 \u0003אמרה: עליונים מבקשין את רבי, והתחתונים מבקשין את רבי — יהי רצון שיכופו תחתונים את העליונים. כיון דחזאי\u0004 \u0005[שראתה]\u0006 \u0003כמה זימני דעייל\u0004 \u0005[פעמים שנכנס]\u0006 \u0003לבית הכסא וחלץ תפילין ומנח להו וקמצטער\u0004 \u0005[ומניח אותן ומצטער]\u0006 ביסורי חולי המעיים שלו, \u0003אמרה: יהי רצון שיכופו עליונים את התחתונים.\u0004","\u0003ולא הוו שתקי רבנן מלמיבעי רחמי\u0004 \u0005[ולא היו שותקים חכמים מלבקש רחמים]\u0006 עליו שיחיה ולפיכך לא הועילה תפילתה. \u0003שקלה כוזא, שדייא מאיגרא לארעא, אישתיקו מרחמי, ונח נפשיה\u0004 \u0005[נטלה כד\u0006 ו\u0005השליכה מן הגג לארץ,\u0006 ומפני הרעש הפתאומי \u0005שתקו מ\u0006לבקש \u0005רחמים, ונחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבי.\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לבר קפרא: זיל עיין\u0004 \u0005[לך\u0006 ו\u0005בדוק]\u0006 מה שלומו של רבי, \u0003אזל אשכחיה דנח נפשיה\u0004 \u0005[הלך, מצאו שנחה נפשו,\u0006 נפטר\u0005].\u0006 \u0003קרעיה ללבושיה ואהדריה לקרעיה לאחוריה\u0004 \u0005[קרע את לבושו והחזיר את הקרע לאחוריו]\u0006 שלא ייראה, וכשבא לפני חכמים \u0003פתח ואמר: אראלים\u0004 (מלאכים) \u0003ומצוקים\u0004 (צדיקים שבארץ) \u0003אחזו בארון הקדש, נצחו אראלים את המצוקים, ונשבה ארון הקדש. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 רבי? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתון קאמריתו\u0004 \u0005[אתם אמרתם]\u0006 \u0003ואנא\u0004 \u0005[ואני]\u0006 \u0003לא קאמינא\u0004 \u0005[אמרתי],\u0006 שהרי החליטו שלא יאמר איש שנפטר רבי.","ועוד מסופר: \u0003בשעת פטירתו של רבי זקף עשר אצבעותיו כלפי מעלה, אמר\u0004 בתפילה: \u0003רבונו של עולם! גלוי וידוע לפניך שיגעתי בעשר אצבעותי בתורה, ולא נהניתי\u0004 מן העולם \u0003אפילו באצבע קטנה, יהי רצון מלפניך שיהא שלום במנוחתי. יצתה בת קול ואמרה: \"יבוא שלום ינוחו על משכבותם\"\u0004 (ישעיה נז, ב).","ושואלים: מדוע נאמר \"על משכבותם\" בלשון רבים, \u0003\"על משכבך\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי פתח בלשון יחיד! ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' חייא בר גמדא.\u0004 ש\u0003אמר ר' חייא בר גמדא אמר ר' יוסי בן שאול: בשעה שהצדיק נפטר מן העולם, אומרים מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, צדיק פלוני בא. אומר להם\u0004 הקדוש ברוך הוא: \u0003יבואו צדיקים ויצאו לקראתו, ואומרים לו\u0004 הצדיקים: \u0003\"יבא בשלום\",\u0004 ואחר כך \u0003ינוחו על משכבותם\u0004 שאר הצדיקים.","\u0003אמר ר' אלעזר: בשעה שהצדיק נפטר מן העולם, שלש כיתות של מלאכי השרת יוצאות לקראתו, אחת אומרת לו: \"בא בשלום\", ואחת אומרת: \"הולך נכחו\", ואחת אומרת לו: \"יבא שלום ינוחו על משכבותם\". בשעה שהרשע נאבד מן העולם, שלש כיתות של מלאכי חבלה יוצאות לקראתו, אחת אומרת: \"אין שלום אמר ה' לרשעים\"\u0004 (ישעיה מח, כב), \u0003ואחת אומרת לו: \"למעצבה ישכב\"\u0004 (ראה ישעיה נ, יא), \u0003ואחת אומרת לו: \"רדה והשכבה את ערלים\"\u0004 (יחזקאל לב, יט).","האלמנה \u0003כל זמן שהיא בבית אביה\u0004 ובהיותה שם מפרנסים אותה היורשים, הריהי \u0003גובה כתובתה לעולם,\u0004 אפילו לאחר שנים רבות. \u0003כל זמן שהיא בבית בעלה גובה כתובתה עד עשרים וחמש שנים,\u0004 ומדוע? \u0003שיש בעשרים וחמש שנים שתעשה טובה\u0004 שנותנת לאחרים מעט מעט, ומוציאה מרכוש היתומים עד שהוא מצטבר \u0003כנגד כתובתה,\u0004 אלו \u0003דברי ר' מאיר\u0004 ש\u0003אמר משום\u0004 (בשם) \u0003רבן שמעון בן גמליאל.\u0004","\u0003וחכמים אומרים\u0004 להיפך: \u0003כל זמן שהיא בבית בעלה — גובה כתובתה לעולם,\u0004 שמפני שהיורשים מטפלים בה מתביישת לתבוע מהם, ואילו \u0003כל זמן שהיא בבית אביה — גובה כתובתה\u0004 רק \u0003עד עשרים וחמש שנים\u0004 ואנו מניחים שמחלה על כתובתה אם לא תבעה אותה עד אז.","אם \u0003מתה — יורשיה מזכירין\u0004 ליורשי בעלה את חוב \u0003כתובתה\u0004 ויכולים לחזור ולתבוע אותה \u0003עד עשרים וחמש שנים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 לר' מאיר האומר שאשה במשך עשרים וחמש שנים נהנית כנגד כל כתובתה, האם \u0003ענייה שבישראל\u0004 שכתובתה מועטת הזמן הוא \u0003עד עשרים וחמש שנים, ומרתא בת בייתוס\u0004 שהיתה עשירה מופלגת וכתובתה מרובה גם כן הזמן הוא \u0003עד עשרים וחמש שנים?\u0004 ואיך ייתכן שיש זמן אחד לכולם!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לפום גמלא שיחנא\u0004 \u0005[לפי הגמל המשוי],\u0006 כלומר, העשירה שכתובתה מרובה עושה גם טובה מרובה, וכל אחת לפי עושרה נהנית מן הכתובה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003ל\u0004דעת \u0003ר' מאיר מהו שתשלש\u0004 (שתחלק), שאם הדבר נחשב לדבריו לפי השנים שנהנית, הרי אם עברו פחות שנים תפסיד רק חלק מכתובתה? לשאלה זו לא נמצאה תשובה, והריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה, \u0003וחכמים אומרים: כל זמן\u0004 שהיא בבית בעלה הריהי גובה כתובתה לעולם, וכשהיא בבית אביה גובה את כתובתה עשרים וחמש שנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: אתאי\u0004 \u0005[באה]\u0006 \u0003קודם שקיעת החמה\u0004 של עשרים וחמש שנים — \u0003גובה כתובתה,\u0004 באה \u0003לאחר שקיעת החמה — לא גביא\u0004 \u0005[אינה גובה]?\u0006 וכי \u0003בההיא פורתא אחילתא\u0004 \u0005[באותו\u0006 זמן \u0005מועט מחלה]\u0006 על כתובתה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003כל מדת חכמים\u0004 שיש לה שיעור וגבול, \u0003כן היא,\u0004 וכל היוצא מן התחום שקבעו — כאילו לא עשה כלום. שהרי \u0003בארבעים סאה\u0004 שבמקוה — \u0003טובל\u0004 ונטהר, ואילו \u0003בארבעים סאה חסר קורטוב\u0004 (משהו) — \u0003אינו יכול לטבול בהן.\u0004","\u0003אמר רב יהודה אמר רב: העיד ר' ישמעאל בר' יוסי לפני רבי שאמר\u0004 ר' ישמעאל \u0003משום\u0004 (בשם) \u0003אביו\u0004 ר' יוסי: \u0003לא שנו אלא שאין שטר כתובה יוצא מתחת ידיה,\u0004 כגון במקום שאין כותבים כתובה, \u0003אבל\u0004 אם \u0003שטר כתובה יוצא מתחת ידיה — גובה כתובתה לעולם. ור' אלעזר אמר: אפילו שטר כתובה יוצא מתחת ידיה — אינה גובה אלא עד עשרים וחמש שנים.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת\u0004 על דברי רב יהודה בשם רב: שנינו, \u0003בעל חוב גובה שלא בהזכרה.\u0004 כלומר, איננו צריך במשך הזמן להזכיר שחייבים לו חוב זה וגובה אף לאחר זמן מרובה. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005],\u0006 \u0003אי דלא נקט שטרא\u0004 \u0005[אם שאינו מחזיק שטר\u0006 בידו\u0005] —\u0006 \u0003במאי גבי\u0004 \u0005[במה\u0006 הוא \u0005גובה]?\u0006 \u0003אלא\u0004 ודאי יש לומר שמדובר באופן \u0003דנקיט שטרא\u0004 \u0005[שמחזיק\u0006 ב\u0005שטר]\u0006 ונדייק מכאן: \u0003ו\u0004דווקא \u0003בעל חוב הוא דלאו בר אחולי\u0004 \u0005[שלא בן מחילה]\u0006 \u0003הוא,\u0004 שאין סברה לומר שמחל את החוב, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אלמנה אחילתא\u0004 \u0005[מחלה]\u0006 ושלא כעדותו של ר' ישמעאל בר' יוסי!","\u0003הוא מותיב לה\u0004 \u0005[מקשה אותה,\u0006 את הקושיה הזו\u0005]\u0006 \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה]:\u0006 \u0003לעולם\u0004 תפרש את הברייתא בבעל חוב \u0003דלא נקיט שטרא\u0004 \u0005[שאינו מחזיק\u0006 ב\u0005שטר],\u0006 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים] —\u0006 \u0003כש\u0004ה\u0003חייב מודה\u0004 שלא פרע.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעא: שונין\u0004 חכמים בברייתא: \u0003גרושה הרי היא כבעל חוב\u0004 ואינה צריכה להזכיר כל פעם את חוב כתובתה. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד מדובר]?\u0006 \u0003אי דלא נקיטא\u0004 \u0005[אם שאיננה מחזקת]\u0006 ב\u0003כתובה, במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]?\u0006 \u0003אלא לאו דנקיטא\u0004 \u0005[\u0006האם \u0005לא\u0006 מדובר \u0005שמחזיקה]\u0006 ב\u0003כתובה, וגרושה היא דלאו\u0004 \u0005[שלא]\u0006 \u0003בת אחולי\u0004 \u0005[מחילה]\u0006 \u0003היא,\u0004 שהרי אינה נשארת בבית ואין לה יחסים טובים עם המשפחה שנאמר שמוחלת על כתובתה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אלמנה אחילתא\u0004 \u0005[מחלה אותה,\u0006 את הכתובה\u0005]\u0006 על אף שיש שטר בידה!","ומתרצים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כשחייב מודה,\u0004 שהיורשים מודים שלא נפרעה עדיין כתובתה.","\u0003אמר רב נחמן בר יצחק: תני\u0004 \u0005[שנה]\u0006 \u0003רב יהודה בר קזא במתניתא דבי\u0004 \u0005[בברייתות\u0006 שהיו שנויות \u0005בבית]\u0006 \u0003בר קזא: תבעה כתובתה\u0004 —"],["\u0003הרי היא כבתחלה,\u0004 ויש לה עוד עשרים וחמש שנים מאז, שאם לא תתבע את כתובתה יש לה זכות לקבל. \u0003ואם היה שטר כתובה יוצא מתחת ידיה — גובה כתובתה לעולם.\u0004","באותו ענין \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר רב חסדא לרב נחמן בר יעקב: ילמדנו רבינו,\u0004 האם גם \u0003כששטר כתובה יוצא מתחת ידה מחלוקת\u0004 ר' מאיר וחכמים, \u0003או\u0004 רק \u0003כשאין שטר כתובה יוצא מתחת ידה? והלכה כדברי מי?\u0004 \u0003שלח ליה\u0004 \u0005[לו]:\u0006 דווקא \u0003בשאין שטר כתובה יוצא מתחת ידה מחלוקת, אבל שטר כתובה יוצא מתחת ידה — גובה כתובתה לעולם\u0004 לדברי הכל. \u0003ו\u0004לענין המחלוקת — \u0003הלכה כדברי חכמים.\u0004","","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל. ציטט מחלוקת: \u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: לא שנו\u0004 שהיא נחשבת שמחלה כתובה \u0003אלא\u0004 לגבי \u0003מנה\u0004 של כתובת אלמנה או \u0003מאתים\u0004 של בתולה שהם עיקר כתובה, \u0003אבל תוספת\u0004 שבכתובה — \u0003יש לה\u0004 בכל מקרה, שאינה אלא כשאר מתנה. \u0003ור' אבהו אמר\u0004 בשם \u0003ר' יוחנן: אפילו תוספת אין לה.\u0004 ש\u0003אמר ר' אייבו אמר ר' ינאי: תנאי כתובה ככתובה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואם נמחלה כתובתה — אף התוספת נמחלה.","","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שנחלקו אמוראים אחרים בדבר, \u0003אמר ר' אבא אמר רב הונא אמר רב: לא שנו אלא מנה מאתים, אבל תוספת יש לה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב הונא:\u0004 וכי \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לר' אבא: מה כוונת השאלה שלך, האם \u0003אישתיקן קאמרת\u0004 \u0005[להשתיק אותי אמרת],\u0006 כלומר, שאתה תמה שאמר רב דבר כזה שאינו מתקבל על דעתך, \u0003או אשקיין קאמרת\u0004 \u0005[להשקותני\u0006 (יין) \u0005אמרת],\u0006 שאתה מתפעל מדברי רב אלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אישתיקן קאמינא\u0004 \u0005[להשתיקך אמרתי,\u0006 התכוונתי\u0005],\u0006 כלומר, תמה אני על הדבר. משמע שהוא חולק על רב וסבור כדעת ר' יוחנן באותו ענין.","מסופר: \u0003חמתיה\u0004 \u0005[חמותו]\u0006 של \u0003רב חייא אריכא\u0004 \u0005[הארוך]\u0006 \u0003אינתת אחוה הואי\u0004 \u0005[אשת אחיו היתה],\u0006 \u0003ואלמנה בבית אביה הואי\u0004 \u0005[היתה],\u0006 שמת אחיו של רב חייא, \u0003וזנה\u0004 רב חייא מנכסי אחיו \u0003עשרים וחמש שנין בבי נשא\u0004 \u0005[בבית אביה].\u0006","\u0003לסוף אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מזוני\u0004 \u0005[מזונות].\u0006 \u0003אמר לה: לית\u0004 \u0005[אין]\u0006 \u0003לך מזוני\u0004 \u0005[מזונות]\u0006 עוד. אמרה לו: אם כן \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כתובה. אמר לה: לא מזוני אית\u0004 \u0005[מזונות יש]\u0006 \u0003לך ולא כתובה אית\u0004 \u0005[יש]\u0006 \u0003לך,\u0004 שאחרי עשרים וחמש שנה אין לך זכויות.","\u0003תבעתיה לדינא קמיה\u0004 \u0005[תבעה אותו לדין לפני]\u0006 \u0003רבה בר שילא. אמר ליה\u0004 \u0005[לו]\u0006 לרב חייא אריכא: \u0003אימא לי איזי גופא דעובדא היכי הוה\u0004 \u0005[אמור לי ידידי, גופו של המעשה איך היה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זניתה\u0004 \u0005[זנתי אותה]\u0006 \u0003עשרים וחמש שנים בבי נשא\u0004 \u0005[בבית אביה],\u0006 \u0003בחיי דמר, דבכתפאי אמטאי\u0004 \u0005[בחיי אדוני, שבכתפי הבאתי]\u0006 \u0003לה\u0004 מזונות כל יום ויום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר שילא: \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]:\u0006 \u0003כל זמן שהיא בבית בעלה גובה כתובתה לעולם — דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003משום כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא\u0004 ש\u0003לא תבעה,\u0004 שכיון שהיא בבית בעלה ומטפלים בה יפה, מתביישת לתבוע את הכתובה, ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003משום כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא\u0004 ש\u0003לא תבעה\u0004 את הכתובה, שהרי אף בבית אביה נהגת בה בכבוד מרובה, ולכן \u0003זיל הב\u0004 \u0005[לך תן]\u0006 \u0003לה\u0004 את כתובתה.","","\u0003לא אשגח\u0004 \u0005[השגיח]\u0006 בדבריו ולא נתן לה דמי כתובתה. \u0003כתב לה\u0004 רבה בר שילא שטר \u0003אדרכתא אניכסיה\u0004 \u0005[על נכסיו],\u0006 כלומר, שטר פסיקה המורה על כך שיכולה לגבות מנכסיו כדי חובה. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב חייא זה \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי מר היכי דנן\u0004 \u0005[יראה אדוני איך דן אותי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שפיר\u0004 \u0005[יפה]\u0006 \u0003דנך,\u0004 כלומר, גם אני מסכים להלכה זו.","\u0003אמרה ליה\u0004 \u0005[לו]\u0006 האשה לרבא: \u0003אי הכי ליזיל להדר\u0004 \u0005[אם כך, שילך ויחזיר]\u0006 \u0003לי פירי דמן ההוא יומא\u0004 \u0005[\u0006את \u0005הפירות\u0006 של הנכסים שאכל \u0005מאותו יום]\u0006 שהפסיק לתת לי \u0003עד האידנא\u0004 \u0005[עכשיו].\u0006 \u0003אמר לה: אחוי\u0004 \u0005[הראי]\u0006 \u0003לי אדרכתיך\u0004 \u0005[\u0006את שטר \u0005האדרכתא\u0006 שבידך\u0005].\u0006 \u0003חזייה\u0004 \u0005[ראה]\u0006 ש\u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003כתוב בה \"ואישתמודענא\u0004 \u0005[ונודע לנו]\u0006 ש\u0003נכסים אלו דמיתנא אינון\u0004 \u0005[של המת הם]\u0006 \u0003\",\u0004 שכיון שהיתה אשת אחיו, היתה האדרכתא צריכה להיות רק על נכסי המת. \u0003אמר לה\u0004 רבא: ה\u0003אדרכתא לאו שפיר כתיבא\u0004 \u0005[איננה כתובה יפה],\u0006 שנכתבה האדרכתא על כל נכסי האח היורש, ובאמת לא השתעבדו לה אלא רק נכסי בעלה־אחיו המת\u0005.\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003תיזיל\u0004 \u0005[\u0006ש\u0005תלך]\u0006 ה\u0003אדרכתא,\u0004 כלומר, כיון שאינה כתובה כפי שצריך, אוותר על הזמן של האדרכתא, אבל \u0003אישקול מיומא דשלימי יומא אכרזתא\u0004 \u0005[אקח מן היום שנשלמו ימי ההכרזה]\u0006 לאחר ששמו בית הדין את נכסי המת \u0003עד השתא\u0004 \u0005[עכשיו].\u0006 \u0003אמר לה: הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום]\u0006 ש\u0003לא כתיב טעותא\u0004 \u0005[\u0006היתה \u0005כתובה טעות]\u0006 \u0003באדרכתא, אבל היכא דכתיב טעותא\u0004 \u0005[במקום ש\u0006היתה \u0005כתובה טעות]\u0006 \u0003באדרכתא — לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 ולא מועילה ההכרזה, שכיון שהיתה טעות בשטר אין לך זכות לפירות מאותה שעה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 כי \u0003אחריות טעות סופר הוא,\u0004 שאף שלא נכתב הדבר הרי זה כאילו היה כתוב בשטר, ואף כאן טעות סופר היא.","","","\u0003אמר לה רבא: בהא ליכא למימר\u0004 \u0005[בזה אין לומר]\u0006 ש\u0003טעות סופר הוא,\u0004 ומדוע? \u0003דבהא\u0004 \u0005[שבזה]\u0006 \u0003אפילו רבה בר שילא טעי\u0004 \u0005[טעה]\u0006 ואין זו טעות סופר, אלא טעות בהלכה. כי \u0003מעיקרא הוא סבור\u0004 \u0005[שמתחילה חשב\u0006 רבה בר שילא\u0005]\u0006 כי \u0003הני והני דידיה\u0004 \u0005[אלה\u0006 נכסיו \u0005ואלה\u0006 נכסי המת \u0005שלו\u0006 הם\u0005],\u0006 שהוא יורשם, ואם כן \u0003מה לי\u0004 אם גובה \u0003מהני\u0004 \u0005[מ\u0006נכסים \u0005אלה],\u0006 \u0003מה לי\u0004 אם גובה \u0003מהני\u0004 \u0005[מ\u0006נכסים \u0005אלה],\u0006","\u0003ולא היא\u0004 \u0005[ואין הדבר כן],\u0006 כי \u0003זימנין דאזלה ומשבחה להו\u0004 \u0005[\u0006ש\u0005פעמים שהולכת ומשביחה אותם,\u0006 את הנכסים שלו\u0005],\u0006 שהיא סבורה שהם מגיעים בחלקה, ואלה שהיו שייכים ל\u0003בעלה מכספי\u0004 \u0005[נפסדים],\u0006 שהאח היורש אינו מטפל בהם כראוי שיודע שהם משועבדים לכתובת האשה, \u0003ו\u0004לבסוף \u0003אמר לה שקיל דידך\u0004 \u0005[קחי את שלך]\u0006 שהם נכסי בעלה, האח שמת, \u0003והב\u0004 \u0005[ותני]\u0006 \u0003לי דידי\u0004 \u0005[את שלי]\u0006 \u0003ואתי לאפוקי\u0004 \u0005[ויבואו להוציא]\u0006 \u0003לעז על בי דינא\u0004 \u0005[בית הדין]\u0006 שאינו דואג לתקנת האשה, ולכן צריך לדייק ולכתוב מאיזה קרקעות היא נוטלת את דמי כתובתה. ובמקרה זה, כיון שטעה רבה בר שילא ולא כתב כראוי, אין ממש בשטר האדרכתא.","","\u0003שני דייני גזירות\u0004 שהיו ראשי הדיינים \u0003היו בירושלים, אדמון וחנן בן אבישלום. חנן אומר שני דברים\u0004 שנחלקו חכמים עליו, \u0003אדמון אומר שבעה.\u0004 ומפרטים את הדברים. \u0003מי שהלך למדינת הים ואשתו תובעת מזונות,\u0004 שאומרת שלא השאיר לה בעלה כל כסף, ותובעת שיפסקו לה בית דין מזונות מנכסיו, \u0003חנן אומר:\u0004"],["\u0003תשבע בסוף,\u0004 שאם יתברר שמת בעלה והיא באה ליטול כתובתה, תשבע שלא השאיר לה בעלה כסף בצאתו, \u0003ולא תשבע בתחלה\u0004 בשעה שתובעת את המזונות, כשיצא למדינת הים. \u0003נחלקו עליו בני כהנים גדולים, ואמרו: תשבע\u0004 גם \u0003בתחלה ו\u0004גם \u0003בסוף. אמר ר' דוסא בן הרכינס כדבריהם\u0004 של בני כהנים גדולים. \u0003אמר רבן יוחנן בן זכאי: יפה אמר חנן, לא תשבע אלא בסוף.\u0004","שנינו במשנה ששני דייני גזירות היו בירושלים \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך, ממה ששנינו בברייתא: \u0003שלשה דייני גזילות היו בירושלים: אדמון בן גדאי, וחנן המצרי, וחנן בן אבישלום.\u0004 אם כן \u0003קשיא תלת אתרין\u0004 \u0005[קשה\u0006 מ\u0005שלושה על שנים],\u0006 שבמשנה נמנו רק שנים, וגם \u0003קשיא\u0004 \u0005[קשה]\u0006 שבמשנה נקראים הם \u0003\"\u0004דייני \u0003גזירות\"\u0004 ואילו בברייתא הם נקראים \u0003\"\u0004דייני \u0003גזילות\"!\u0004","וממשיכים: \u0003בשלמא תלת אתרין\u0004 \u0005[נניח\u0006 מ\u0005שלושה על שנים]\u0006 \u0003לא קשיא\u0004 \u0005[קשה]\u0006 כי \u0003דחשיב ליה\u0004 \u0005[\u0006מי \u0005ש\u0006היה \u0005חשוב לו] —\u0006 \u0003קתני\u0004 \u0005[שנה],\u0006 ומי ש\u0003לא\u0004 היה \u0003חשיב ליה\u0004 \u0005[חשוב לו] —\u0006 \u0003לא קתני\u0004 \u0005[שנה],\u0006 והיו דיינים נוספים אלא שמנה רק את הדיינים החשובים לעניינו. \u0003אלא\u0004 לשון \u0003\"גזירות\"\u0004 על לשון \u0003\"גזילות\" קשיא\u0004 \u0005[קשה]!\u0006","\u0003אמר רב נחמן בר יצחק:\u0004 אין זו סתירה, אלא הכוונה היא \u0003שהיו גוזרין גזירות על גזילות.\u0004 כלומר, שהיו קובעים דינים בדיני גזילות. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 שבהמה ש\u0003קיטמה נטיעה\u0004 (קצצה שתיל צעיר) בשדה אחר, \u0003ר' יוסי אומר: גוזרי גזירות שבירושלים אומרים:\u0004 על \u0003נטיעה בת שנתה\u0004 משלם \u0003שתי כסף,\u0004 ועל \u0003בת שתי שנים\u0004 — משלם \u0003ארבע כסף.\u0004","ושואלים עוד לעניין דייני גזירות: \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003שלשה דייני גזירות היו בירושלים: אדמון, וחנן, ונחום\u0004 ולמעלה הוזכר חנן המצרי כדיין שלישי! \u0003אמר רב פפא: מאן תנא\u0004 \u0005[ומי שנה]\u0006 את שמו של \u0003נחום\u0004 בין הדיינים הללו — \u0003ר' נתן היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נתן אומר: אף נחום המדי מגוזרי גזירות\u0004 ש\u0003בירושלים היה, ולא הודו לו חכמים.\u0004","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 מאלה \u0005לא היו\u0006 דיינים\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' פנחס אמר ר' אושעיא: שלש מאות ותשעים וארבעה בתי דינין היו בירושלים, כנגדן\u0004 היו מספר \u0003בתי כנסיות, וכנגדן בתי מדרשות, וכנגדן בתי סופרים\u0004 שמלמדים בהם את התינוקות. ומשיבים: \u0003דיינין טובא הוו\u0004 \u0005[הרבה היו]\u0006 \u0003וכי קאמרינן\u0004 \u0005[וכאשר אמרנו] —\u0006 על \u0003גוזרי גזירות קאמרינן\u0004 \u0005[אמרנו],\u0006 כלומר, מתקיני התקנות.","\u0003אמר רב יהודה אמר רב אסי: גוזרי גזירות שבירושלים היו נוטלין שכרן תשעים ותשע מנה\u0004 לשנה \u0003מתרומת הלשכה,\u0004 אם \u0003לא רצו — מוסיפין להם.\u0004 ושואלים: \u0003לא רצו?\u0004 כלומר, האם הכוונה שאם לא רצו להסתפק בסכום זה מוסיפים להם כרצונם? \u0003אטו ברשיעי עסקינן\u0004 \u0005[וכי ברשעים אנו עוסקים]\u0006 שתובעים שכר מרובה יותר מצרכם? \u0003אלא,\u0004 הכוונה היא להיפך: אם \u0003לא ספקו,\u0004 שלא היה די להם בסכום זה \u0003אף על פי שלא רצו — מוסיפין עליהן\u0004 כדי שיוכלו לפנות את עצמם למלאכת הציבור.","מסופר: החכם \u0003קרנא הוה שקיל איסתירא\u0004 \u0005[היה לוקח מעה]\u0006 \u0003מ\u0004ן ה\u0003זכאי ואיסתירא\u0004 \u0005[ומעה]\u0006 \u0003מ\u0004ן ה\u0003חייב,\u0004 כלומר, משני הצדדים שהיו באים להתדיין לפניו, \u0003ודאין להו דינא\u0004 \u0005[והיה דן להם דין].\u0006 ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[ואיך\u0006 היה \u0005עושה כך]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ושחד לא תקח\"\u0004 (שמות כג, ח), משמע שאסור לדיין ליטול כסף מבעלי הדין!","\u0003וכי תימא הני מילי היכא דלא שקיל מתרוייהו דלמא אתי לאצלויי דינא\u0004 \u0005[ואם תאמר\u0006 כי \u0005דברים אלה\u0006 לאסור שוחד נאמרו רק \u0005במקום שאינו לוקח משניהם, שמא יבוא להטות את הדין]\u0006 לטובת מי שנתן לו כסף, ואילו \u0003קרנא כיון דשקיל מתרוייהו\u0004 \u0005[שהיה לוקח משניהם]\u0006 \u0003לא אתי לאצלויי דינא\u0004 \u0005[יבוא להטות את הדין],\u0006 \u0003ו\u0004אולם \u0003כי לא אתי לאצלויי דינא, מי שרי\u0004 \u0005[כאשר אינו בא להטות\u0006 את \u0005הדין, האם מותר]\u0006 לקבל?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר: \u0003\"ושחד לא תקח\" מה תלמוד לומר? אם ללמד שלא לזכות את החייב ושלא לחייב את הזכאי\u0004 משום השוחד — \u0003הרי כבר נאמר \"לא תטה משפט\"\u0004 (דברים טז, כ), \u0003אלא\u0004 בא הכתוב לומר ש\u0003אפילו\u0004 כדי \u0003לזכות את הזכאי ולחייב את החייב אמרה\u0004 ה\u0003תורה \"ושחד לא תקח\",\u0004 משמע שאסור לדיין לקבל דבר מבעלי הדין אפילו כשאין חשש של הטיית הדין!","ומשיבים: \u0003הני מילי היכא דשקיל\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005כשלוקח\u0006 את הכסף\u0005]\u0006 \u0003בתורת שוחד\u0004 גם אם אינו מטה את הדין, ואילו \u0003קרנא בתורת אגרא\u0004 \u0005[שכר]\u0006 \u0003הוה שקיל\u0004 \u0005[היה לוקח]\u0006 ולא כשוחד. ומקשים: \u0003ובתורת אגרא\u0004 \u0005[שכר]\u0006 \u0003מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנוטל שכר לדון — דיניו בטלין,\u0004 שאין הדיין דן אלא בחינם! ומשיבים: \u0003הני מילי אגר דינא\u0004 \u0005[דברים אלה\u0006 אמורים כשהוא נוטל \u0005שכר הדין],\u0006 ואילו \u0003קרנא אגר בטילא הוה שקיל\u0004 \u0005[שכר בטלה היה לוקח],\u0006 שמשום שהיה בטל ממלאכתו בזמן הדין, היה מקבל שכר בטלה על כך.","ושואלים: \u0003ואגר בטילא מי שרי\u0004 \u0005[ושכר בטלה האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מכוער הדיין שנוטל שכר לדון, אלא שדינו דין.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא אגר דינא\u0004 \u0005[אם תאמר שכר\u0006 שנוטל עבור \u0005הדין],\u0006 אולם במקרה כזה האם \u0003דינו דין? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנוטל שכר לדון — דיניו בטילין! אלא\u0004 ודאי מדובר ב\u0003אגר בטילא\u0004 \u0005[שכר בטלה]\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003מכוער הדיין!\u0004","ומשיבים: \u0003הני מילי בטילא דלא מוכחא\u0004 \u0005[דברים אלה\u0006 שמכוער דיין זה, הוא כשנוטל שכר \u0005בטלה שאינה מוכחת],\u0006 שאינו עסוק ממש במלאכה באותה שעה, אלא מכיון שהוא מבזבז את זמנו, והיתה לו אפשרות שיעשה דברים אחרים הוא נוטל שכר בטלה. אבל \u0003קרנא בטילא דמוכחא הוה שקיל\u0004 \u0005[\u0006שכר \u0005בטלה מוכחת היה לוקח],\u0006 \u0003דהוה תהי באמברא דחמרא\u0004 \u0005[שהיה תוהה,\u0006 בודק, \u0005באוצרות יין]\u0006 כדי לקבוע איזה מהם יעמוד ואיזה יתקלקל \u0003ויהבי ליה זוזא\u0004 \u0005[והיו נותנים לו זוז]\u0006 כשכר, וכאשר עסק בדין היה ניכר שהוא מפסיד את שכר עבודתו.","\u0003כי הא\u0004 \u0005[כמו זה]\u0006 המעשה ש\u0003רב הונא כי הוה אתי דינא לקמיה\u0004 \u0005[כאשר היה בא דין לפניו]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 למתדיינים: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי גברא דדלי\u0004 \u0005[אדם שידלה]\u0006 \u0003לי\u0004 את המים שאני צריך לדלות לשדה \u0003בחריקאי\u0004 \u0005[במקומי]\u0006 \u0003ואידון לכו דינא\u0004 \u0005[ואדון לכם\u0006 את \u0005הדין],\u0006 שאיני יכול להתבטל ממלאכתי.","\u0003אמר ר' אבהו: בא וראה כמה סמויות\u0004 (עוורות) \u0003עיניהן של מקבלי שוחד,\u0004 שמקלקלים לעצמם. כיצד? \u0003אדם חש בעיניו — נותן ממון לרופא\u0004 שיירפאנו, ואפילו אז — \u0003ספק מתרפא ספק אינו מתרפא. והן,\u0004 הדיינים, \u0003נוטלין שוה פרוטה\u0004 כשוחד \u0003ומסמין\u0004 (מעוורים) את \u0003עיניהן, שנאמר: \"כי השחד יעור פקחים\"\u0004 (שמות כג, ח).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"כי השחד יעור עיני חכמים\"\u0004 (דברים טז, כ), הרי זה \u0003קל וחומר לטפשין,\u0004 שבודאי מעוור השוחד את עיניהם. והנאמר \u0003\"ויסלף דברי צדיקים\"\u0004 (שמות כג, ח. דברים טז, כ), הרי זה \u0003קל וחומר לרשעים.\u0004 ושואלים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003טפשים ורשעים בני דינא נינהו\u0004 \u0005[בני דין הם],\u0006 שאותם ממנים לדיינים? \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003\"כי השחד יעור עיני חכמים\",\u0004 לומר ש\u0003אפילו\u0004 אם היה \u0003חכם גדול ו\u0004הוא \u0003לוקח שוחד — אינו נפטר מן העולם בלא סמיות\u0004 (עוורון) \u0003הלב,\u0004 שבסופו של דבר נעשה טיפש. \u0003\"ויסלף דברי צדיקים\",\u0004"],["\u0003אפילו\u0004 אם הוא \u0003צדיק גמור ולוקח שוחד — אינו נפטר מן העולם בלא טירוף דעת.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: דרש רב נחמן בר כהן, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מלך במשפט יעמיד ארץ ואיש תרומות יהרסנה\"\u0004 (משלי כט, ד) — \u0003אם דומה\u0004 ה\u0003דיין למלך,\u0004 כלומר, \u0003שאינו צריך לכלום\u0004 ואינו נזקק לבריות — \u0003יעמיד ארץ,\u0004 הוא יכול להיות דיין. \u0003ואם דומה לכהן שמחזר על הגרנות,\u0004 כלומר, שנזקק לאחרים — \u0003יהרסנה.\u0004","\u0003אמר רבה בר רב שילא: האי דיינא דשאיל שאילתא\u0004 \u0005[דיין זה, ששואל\u0006 דברים מאחרים\u0005]\u0006 — \u0003פסול למידן דינא\u0004 \u0005[לדון דין],\u0006 שהרי זה כאילו קיבל שכר מאותם אנשים ששואל מהם. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 זאת \u0003אלא דלית ליה לאושולי\u0004 \u0005[שאין לו להשאיל\u0006 לאחרים\u0005]\u0006 והוא כל הזמן רק נזקק ושואל, \u0003אבל\u0004 אם \u0003אית ליה לאושולי\u0004 \u0005[יש לו להשאיל] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","ומקשים: \u0003איני\u0004 \u0005[וכך הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 שהיה דיין \u0003שאיל שאילתא מדבי\u0004 \u0005[היה שואל מבית]\u0006 \u0003בר מריון אף על גב דלא שיילי מיניה\u0004 \u0005[אף על פי ש\u0006הם \u0005לא היו שואלים ממנו]?\u0006 ומשיבים: \u0003התם לאחשובינהו\u0004 \u0005[שם להחשיב אותם]\u0006 \u0003הוא דבעי\u0004 \u0005[שרצה],\u0006 שרבא היה עשיר ולא עשה זאת כדי ליהנות מהם, אלא להיפך, על ידי ששאל מהם נתן להם כבוד.","\u0003אמר רבא: מאי טעמא דשוחדא\u0004 \u0005[מה הטעם של\u0006 איסור \u0005שוחד]?\u0006 \u0003כיון דקביל ליה שוחדא מיניה\u0004 \u0005[שמקבל שוחד ממנו],\u0006 \u0003איקרבא ליה דעתיה לגביה והוי כגופיה\u0004 \u0005[התקרבה דעתו אליו ונעשה כגופו]\u0006 \u0003ואין אדם רואה חובה לעצמו.\u0004 ויש לכך רמז לשוני: \u0003מאי\u0004 \u0005[מה\u0006 הוא לשון\u0005]\u0006 \u0003\"שוחד\" — שהוא חד\u0004 \u0005[אחד]\u0006 עם הנידון. \u0003אמר רב פפא: לא לידון איניש דינא\u0004 \u0005[ידון אדם דין]\u0006 לא \u0003למאן דרחים ליה\u0004 \u0005[למי ש\u0006הוא \u0005אוהב אותו]\u0006 \u0003ולא למאן דסני ליה\u0004 \u0005[למי ש\u0006הוא \u0005שונא אותו].\u0006 ומסביר: \u0003דרחים ליה\u0004 \u0005[\u0006לזה \u0005ש\u0006הוא \u0005אוהב אותו] —\u0006 \u0003לא חזי ליה\u0004 \u0005[אינו רואה לו]\u0006 \u0003חובה, דסני ליה\u0004 \u0005[\u0006לזה \u0005ש\u0006הוא \u0005שונא אותו] —\u0006 \u0003לא חזי ליה זכותא\u0004 \u0005[אינו רואה לו זכות].\u0006","\u0003אמר אביי: האי צורבא מרבנן דמרחמין ליה בני מתא\u0004 \u0005[תלמיד חכם זה, שאוהבים אותו בני העיר] —\u0006 \u0003לאו משום דמעלי טפי\u0004 \u0005[לא מפני ש\u0006הוא \u0005מעולה יותר]\u0006 ולכן אוהבים אותו, \u0003אלא משום דלא מוכח להו במילי דשמיא\u0004 \u0005[שאינו מוכיח אותם בדברי שמים]\u0006 ולכן אוהבים אותו, לפי שאינו דורש מהם דבר.","\u0003אמר רבא: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]:\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 \u0003בני\u0004 עירי \u0003מחוזא כולהו רחמו לי\u0004 \u0005[כולם אוהבים אותי],\u0006 \u0003כיון דהואי דיינא\u0004 \u0005[שנעשיתי דיין],\u0006 \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003מינייהו סנו לי ומנייהו רחמו לי\u0004 \u0005[מהם שונאים אותי ומהם אוהבים אותי],\u0006 שמן הסתם זה שנתחייב בדין שונא אותי וזה שנזדכה בדין אוהב אותי. \u0003כיון דחזאי דמאן דמיחייב ליה האידנא קא זכי\u0004 \u0005[שראיתי שמי שאני מחייב אותו עכשיו זוכה]\u0006 בדין \u0003למחר\u0004 והבנתי שאין זה דבר של קבע, \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003אם מרחם\u0004 \u0005[לאהוב] —\u0006 \u0003כולהו רחמו לי\u0004 \u0005[כולם אוהבים אותי],\u0006 \u0003אי מסנו\u0004 \u0005[אם לשנוא] —\u0006 \u0003כולהו סנו לי\u0004 \u0005[כולם שונאים אותי],\u0006 שאין הדבר תלוי בכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"ושחד לא תקח\"\u0004 (שמות כג, ח), \u0003אינו צריך לומר\u0004 שכוונת הכתוב לאסור דווקא \u0003שוחד ממון, אלא אפילו שוחד דברים נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור,\u0004 כגון שעושים לו טובה בדיבורים או באופן אחר — הרי זה שוחד. \u0003מדלא כתיב\u0004 \u0005[מ\u0006כיון \u0005שלא נאמר]\u0006 \u0003\"בצע לא תקח\"\u0004 אלא \"שוחד\". ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003שוחד דברים?\u0004","ומסבירים: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003שמואל הוה עבר במברא\u0004 \u0005[היה עובר במעבורת\u0006 צרה\u0005],\u0006 \u0003אתא ההוא גברא יהיב ליה ידיה\u0004 \u0005[בא אדם אחד ונתן לו\u0006 את \u0005ידו]\u0006 לעזור לו לצאת מן המעבורת, \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003מאי עבידתיך\u0004 \u0005[מה מעשיך\u0006 פה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין],\u0006 כיון שעשית לי טובה. ואף על פי שלא נתן לו כסף נוצרה ביניהם קרבה.","כיוצא בו מסופר: \u0003אמימר הוה יתיב וקא דאין דינא\u0004 \u0005[היה יושב ודן דין].\u0006 \u0003פרח גדפא ארישיה, אתא ההוא גברא שקליה\u0004 \u0005[פרחה\u0006 ועלתה \u0005נוצה על ראשו, בא אדם אחד\u0006 ונטל \u0005אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003מאי עבידתיך\u0004 \u0005[מה מעשיך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין]\u0006 בשל כך. ומסופר עוד: \u0003מר עוקבא הוה שדי רוקא קמיה\u0004 \u0005[היה מושלך רוק לפניו],\u0006 \u0003אתא ההוא גברא כסייה\u0004 \u0005[בא אדם אחד וכיסה אותו,\u0006 את הרוק\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר עוקבא: \u0003מאי עבידתיך\u0004 \u0005[מה מעשיך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין].\u0006","מסופר: \u0003ר' ישמעאל בר' יוסי הוה\u0004 \u0005[היה]\u0006 \u0003רגיל אריסיה\u0004 \u0005[אריסו]\u0006 \u0003דהוה מייתי ליה כל מעלי שבתא כנתא דפירי\u0004 \u0005[שהיה מביא לו כל ערב שבת סל פירות].\u0006 \u0003יומא חד אייתי ליה בחמשה בשבתא\u0004 \u0005[יום אחד הביא לו\u0006 את הסל \u0005ב\u0006יום \u0005חמישי בשבת].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי שנא האידנא\u0004 \u0005[מה שונה עכשיו]\u0006 שהקדמת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך, \u0003ואמינא\u0004 \u0005[ואמרתי]\u0006 \u0003אגב אורחי\u0004 \u0005[דרכי],\u0006 שיום חמישי הוא יום מושב בית דין, \u0003אייתי ליה למר\u0004 \u0005[אביא לו לאדוני]\u0006 את סל הפירות. \u0003לא קביל מיניה\u0004 \u0005[קיבל ממנו]\u0006 ר' ישמעאל את הפירות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין].\u0006","\u0003אותיב זוזא דרבנן וקדיינין ליה\u0004 \u0005[הושיב זוג חכמים והיו דנים\u0006 הם \u0005אותו].\u0006 \u0003בהדי דקאזיל ואתי\u0004 \u0005[בתוך\u0006 הזמן \u0005שהיה הולך ובא]\u0006 \u0003אמר\u0004 ר' ישמעאל בלבו: \u0003אי בעי\u0004 \u0005[אם היה רוצה] —\u0006 \u0003טעין הכי\u0004 \u0005[היה טוען כך],\u0006 \u0003ואי בעי\u0004 \u0005[ואם היה רוצה] —\u0006 \u0003טעין הכי\u0004 \u0005[היה טוען כך]\u0006 הכל לזכותו של אותו אדם שהביא לו את הפירות. \u0003אמר: תיפח נפשם של מקבלי שוחד! ומה אני שלא נטלתי, ו\u0004אפילו \u0003אם\u0004 כן \u0003נטלתי —\u0004 הלא את \u0003שלי נטלתי,\u0004 שהרי אריסו היה זה ופירות אלה מן הדין היו של ר' ישמעאל, ובכל זאת כל \u0003כך\u0004 אני מושפע ממעשה זה, \u0003מקבלי שוחד\u0004 ממש \u0003על אחת כמה וכמה\u0004 שדעתם נוטה אחרי נותן שוחד.","כיוצא בו מסופר: \u0003ר' ישמעאל בר אלישע\u0004 שהיה כהן \u0003אייתי ליה ההוא גברא\u0004 \u0005[הביא לו אדם אחד]\u0006 את \u0003ראשית הגז. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהיכא את\u0004 \u0005[מהיכן אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדוך פלן\u0004 \u0005[ממקום פלוני].\u0006 שאל אותו ר' ישמעאל: \u0003ומהתם להכא\u0004 \u0005[ומשם\u0006 עד \u0005כאן]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003כהן\u0004 אחר \u0003למיתבא ליה\u0004 \u0005[לתת לו\u0006 את ראשית הגז\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך, \u0003ואמינא\u0004 \u0005[ואמרתי]\u0006 \u0003אגב אורחאי\u0004 \u0005[דרכי]\u0006 \u0003אייתי ליה למר\u0004 \u0005[אביא לו לאדוני]\u0006 את ראשית הגז. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין],\u0006 ו\u0003לא קביל מיניה\u0004 \u0005[קיבל ממנו\u0006 את ראשית הגז\u0005].\u0006","\u0003אותיב ליה זוגא דרבנן וקדייני ליה\u0004 \u0005[הושיב לו זוג חכמים והיו דנים אותו].\u0006 \u0003בהדי דקאזיל ואתי\u0004 \u0005[בתוך שהיה הולך ובא],\u0006 \u0003אמר: אי בעי טעין הכי, ואי בעי טעין הכי\u0004 \u0005[אם היה רוצה, היה\u0006 האיש \u0005טוען כך, ואם רוצה טוען כך]\u0006 וזוכה בדין. ומכיון שכך, \u0003אמר\u0004 בלבו: \u0003תיפח נפשם של מקבלי שוחד! ומה אני שלא נטלתי, ואם נטלתי — שלי נטלתי,\u0004 שהרי כהן אני וזכאי ל\u0003כך, מקבלי שוחד\u0004 ממש \u0003על אחת כמה וכמה.\u0004","מסופר: \u0003רב ענן אייתי ליה ההוא גברא כנתא דגילדני דבי גילי\u0004 \u0005[הביא לו אדם אחד סל של דגים קטנים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי עבידתיך\u0004 \u0005[מה מעשיך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 בפניך. \u0003לא קביל מיניה\u0004 \u0005[קיבל ממנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 עוד: \u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 האיש: \u0003דינא דמר לא בעינא, קבולי לקביל מר\u0004 \u0005[\u0006את \u0005דינו של אדוני אינני רוצה,\u0006 אבל \u0005יקבל אדוני]\u0006 על כל פנים את מתנתי \u0003דלא למנען מר מאקרובי\u0004 \u0005[שלא ימנעני אדוני מלהקריב]\u0006 \u0003בכורים.\u0004 ומה ענין ביכורים לכאן — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ואיש בא מבעל שלישה ויבא לאיש האלהים לחם בכורים עשרים לחם שערים וכרמל בצקלנו\"\u0004 (מלכים ב ד, מב). ויש להבין מדוע נאמר \"לחם ביכורים\", \u0003וכי אלישע אוכל בכורים הוה\u0004 \u0005[היה],\u0006 והרי לא היה כהן! \u0003אלא לומר לך: כל המביא דורון\u0004 (מתנה) \u0003לתלמיד חכם — כאילו מקריב בכורים,\u0004 ואם כן רוצה גם אני לקיים מצוה זו.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קבולי לא בעינן דאיקביל\u0004 \u0005[לקבל אינני רוצה],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת לי טעמא\u0004 \u0005[טעם\u0006 בדבר\u0005],\u0006 \u0003מקבילנא\u0004 \u0005[אקבל\u0006 ממך\u0005],\u0006 כיון שאתה רוצה לעשות מצוה. \u0003שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003רב נחמן\u0004 ו\u0003שלח ליה\u0004 \u0005[לו]\u0006 במכתב: \u0003נידייניה מר להאי גברא\u0004 \u0005[ידון אדוני את האיש הזה]\u0006 משום \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ענן פסילנא ליה לדינא\u0004 \u0005[פסול לו לדין].\u0006 \u0003אמר\u0004 רב נחמן בלבו: \u0003מ\u0004כיון ש\u0003שלח לי הכי\u0004 \u0005[כך],\u0006 \u0003שמע מינה קריביה\u0004 \u0005[מכאן שקרובו]\u0006 \u0003הוא,\u0004 ולכן פסול לו לדין. באותו זמן כבר \u0003הוה קאים דינא דיתמי קמיה\u0004 \u0005[היה עומד דין של יתומים לפניו],\u0006 \u0003אמר:\u0004"],["\u0003האי\u0004 \u0005[זו]\u0006 מצות \u0003עשה\u0004 של הדיינים לשפוט בצדק \u0003והאי\u0004 \u0005[וזו]\u0006 מצות \u0003עשה\u0004 לכבד את בעלי התורה וגם את בני משפחתם — \u0003עשה\u0004 של \u0003כבוד\u0004 ה\u0003תורה עדיף.\u0004 לכן \u0003סלקיה לדינא דיתמי ואחתיה לדיניה\u0004 \u0005[סילק,\u0006 הניח \u0005את דין היתומים והורידו,\u0006 ונפנה \u0005לדין]\u0006 של אותו אדם, משום שסבר שהוא קרובו של רב ענן, \u0003כיון דחזא בעל דיניה יקרא דקא עביד ליה\u0004 \u0005[שראה בעל דינו\u0006 את \u0005הכבוד ש\u0006הדיין \u0005עושה לו],\u0006 \u0003איסתתם טענתיה\u0004 \u0005[נסתתמו טענותיו]\u0006 והפסיד במשפט. ונגרם איפוא על ידי רב ענן, אם כי שלא בכוונה ושלא במישרין, עוול במשפט.","מסופר: \u0003רב ענן הוה\u0004 \u0005[היה]\u0006 \u0003רגיל אליהו\u0004 הנביא \u0003דאתי גביה\u0004 \u0005[שבא אצלו]\u0006 \u0003דהוה מתני ליה\u0004 \u0005[שהיה משנה,\u0006 מלמד, \u0005לו]\u0006 מה שנכתב אחר כך בספר \u0003סדר דאליהו. כיון דעבד הכי\u0004 \u0005[שעשה כך],\u0006 שגרם לעיוות הדין, \u0003איסתלק\u0004 \u0005[הסתלק]\u0006 אליהו. \u0003יתיב בתעניתא ובעא רחמי ואתא\u0004 \u0005[ישב\u0006 רב ענן \u0005בתענית וביקש רחמים ובא]\u0006 אליהו, אבל \u0003כי אתא, הוה מבעית ליה בעותי\u0004 \u0005[כאשר היה בא, היה מפחיד אותו],\u0006 שהיתה התגלותו בפעמים אלה באופן מפחיד.","\u0003ועבד תיבותא ויתיב קמיה עד דאפיק ליה סידריה\u0004 \u0005[ועשה\u0006 רב ענן לעצמו \u0005תיבה וישב לפניו עד שהוציא לו\u0006 גמר ללמד אותו \u0005את סדרו].\u0006 \u0003והיינו דאמרי\u0004 \u0005[והוא שאומרים]:\u0006 \u0003סדר דאליהו רבה, סדר אליהו זוטא,\u0004 שאת הראשון לימדו קודם מעשה זה, ואת האחר לימדו לאחר מעשה.","מסופר, \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב יוסף הוה ריתחא\u0004 \u0005[היה\u0006 זמן \u0005זעם\u0006 של המקום\u0005],\u0006 שהיה רעב בעולם. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרב יוסף: ליבעי מר רחמי\u0004 \u0005[יבקש אדוני רחמים]\u0006 על הגזירה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003ומה אלישע דכי הוו רבנן מיפטרי מקמיה, הוו פיישי תרי אלפן ומאתן רבנן\u0004 \u0005[שכאשר היו חכמים נפטרים מלפניו, היו נשארים אלפיים ומאתים חכמים]\u0006 שהוא היה מפרנסם משלו, בכל זאת \u0003בעידן ריתחא\u0004 \u0005[בזמן זעם\u0006 ורעב\u0005]\u0006 \u0003לא הוה בעי רחמי\u0004 \u0005[היה מבקש רחמים],\u0006 \u0003אנא איבעי רחמי\u0004 \u0005[אני אבקש רחמים]?\u0006","\u0003וממאי דפיישי הכי\u0004 \u0005[וממה\u0006 יודעים אנחנו \u0005שכך נשארו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר משרתו מה אתן זה לפני מאה איש\"\u0004 (מלכים ב ד, מג), ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לפני מאה איש\"? אילימא דכולהו\u0004 \u0005[אם תאמר שכולם],\u0006 כל מה שקיבל במתנה, שהיו עשרים לחם ולחם ביכורים וכרמל, \u0003לפני מאה איש בשני בצורת טובא הוו\u0004 \u0005[הרבה הם]\u0006 ויכולים להסתפק בכך! \u0003אלא\u0004 הכוונה היתה ש\u0003כל חד וחד קמי\u0004 \u0005[אחת ואחת\u0006 מן הככרות הללו \u0005לפני]\u0006 \u0003מאה איש,\u0004 ולפי זה היו אלפיים ומאתים חכמים שם.","אגב כך מספרים: \u0003כי הוו מיפטרי רבנן מבי\u0004 \u0005[כאשר היו נפטרים חכמים מבית]\u0006 \u0003רב, הוו פיישי אלפא ומאתן רבנן\u0004 \u0005[היו נשארים\u0006 עוד ללמוד \u0005אלף ומאתיים חכמים].\u0006 וכשיצאו \u0003מבי\u0004 \u0005[מבית]\u0006 \u0003רב הונא, הוו פיישי תמני מאה רבנן\u0004 \u0005[היו נשארים שמונה מאות חכמים].\u0006 \u0003רב הונא הוה דריש בתליסר אמוראי\u0004 \u0005[היה דורש בשלושה עשר אמוראים],\u0006 שהיו דרושים שלושה עשר מתורגמנים כדי להשמיע את דבריו לכל העם הרב שהיה שם. \u0003כי הוו קיימי רבנן ממתיבתא\u0004 \u0005[כאשר היו עומדים חכמים מישיבתו]\u0006 של \u0003רב הונא ונפצי גלימייהו\u0004 \u0005[ומנערים את גלימותיהם]\u0006 \u0003הוה סליק אבקא וכסי ליה ליומא\u0004 \u0005[היה עולה האבק ומכסה את אור השמש]\u0006 והיה נראה מרחוק, \u0003ואמרי במערבא\u0004 \u0005[והיו אומרים בארץ ישראל]:\u0006 \u0003קמו ליה ממתיבתא\u0004 \u0005[עמדו\u0006 כבר \u0005מהישיבה]\u0006 של \u0003רב הונא בבלאה\u0004 \u0005[הבבלי].\u0006","\u0003כי מיפטרי רבנן מבי\u0004 \u0005[כאשר היו נפטרים חכמים מבית]\u0006 מדרשם של \u0003רבה ורב יוסף הוו פיישי ארבע מאה רבנן\u0004 \u0005[היו נשארים ארבע מאות חכמים]\u0006 \u0003וקרו לנפשייהו\u0004 \u0005[והיו קוראים לעצמם]:\u0006 \u0003\"יתמי\"\u0004 \u0005[יתומים],\u0006 שרק הם נשארו מכל הקהל. \u0003כי הוו מיפטרי רבנן מבי\u0004 \u0005[כאשר היו נפטרים חכמים מבית]\u0006 \u0003אביי, ואמרי לה מבי\u0004 \u0005[ויש אומרים מבית]\u0006 \u0003רב פפא, ואמרי לה מבי\u0004 \u0005[ויש אומרים מבית]\u0006 \u0003רב אשי, הוו פיישי מאתן רבנן\u0004 \u0005[היו נשארים מאתים חכמים]\u0006 \u0003וקרו נפשייהו\u0004 \u0005[והיו קוראים לעצמם]\u0006 \u0003יתמי דיתמי\u0004 \u0005[יתומי יתומים].\u0006","ושוב לדברים הנוגעים לענין חכמים המקבלים שכר מן הרבים. \u0003אמר ר' יצחק בר\u0004 \u0005[בן]\u0006 \u0003רדיפא אמר ר' אמי: מבקרי מומין שבירושלים,\u0004 שהיו בודקים את הבהמות שמביאים לקרבן אם אין בהן מום הפוסלן להקרבה, \u0003היו נוטלין שכרן מתרומת הלשכה. אמר רב יהודה אמר שמואל: תלמידי חכמים המלמדין הלכות שחיטה לכהנים\u0004 במקדש, \u0003היו נוטלין שכרן מתרומת הלשכה.\u0004","\u0003אמר רב גידל אמר רב: תלמידי חכמים המלמדים הלכות קמיצה לכהנים, נוטלין שכרן מתרומת הלשכה,\u0004 שכל אלה היו עסוקים כל הזמן בעבודות הצריכות למקדש ולכן היו מקבלים שכרם מן המקדש. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מגיהי ספרים\u0004 (ספרי תורה) \u0003שבירושלים, היו נוטלין שכרן מתרומת הלשכה.\u0004","\u0003אמר רב נחמן אמר רב: נשים האורגות בפרכות\u0004 של המקדש, היו \u0003נוטלות שכרן מתרומת הלשכה. ואני אומר\u0004 שלא מתרומת המקדש, אלא \u0003מקדשי בדק הבית.\u0004 ומדוע? \u0003הואיל ופרכות תחת\u0004 (במקום) \u0003בנין עשויות,\u0004 הרי הן שייכות לבנין המקדש, ולכן שכרן צריך להיות משולם לא מן הכסף המוקדש לקרבנות ולצרכי יום יום של המקדש אלא מן הכסף המוקדש לבנין עצמו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003נשים האורגות בפרכות, ובית גרמו\u0004 שהיו ממונים \u0003על מעשה לחם הפנים, ובית אבטינס\u0004 שהיו ממונים \u0003על מעשה הקטרת — כולן היו נוטלות שכרן מתרומת הלשכה,\u0004 ולא כדברי רב נחמן!","משיבים: \u0003התם בדבבי\u0004 \u0005[שם\u0006 מדובר בפרוכות \u0005של השערים],\u0006 שפרוכות אלה אינן נחשבות לחלק מן הבנין אלא כדרך ליפותו והחזקתו. ש\u0003אמר ר' זירא אמר רב: שלשה עשר פרכות היו במקדש שני, שבעה כנגד שבעה שערים\u0004 שהיו בעזרה, ועוד \u0003אחד לפתחו של היכל, ואחד לפתחו של אולם. שנים\u0004 היו \u0003בדביר, שנים כנגדן בעליה\u0004 מעל הדביר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשים המגדלות בניהן לפרה,\u0004 שהיו מגדלים תינוקות במקומות מיוחדים שיהיו כל ימיהם בטהרה כדי שישאבו מים לצורך פרה אדומה, ואמהותיהם היו משמרות אותם לכך— \u0003היו נוטלות שכרן מתרומת הלשכה. אבא שאול אומר:\u0004 לא מתרומת הלשכה, אלא \u0003נשים יקרות\u0004 (עשירות וחשובות) \u0003שבירושלים היו זנות אותן ומפרנסות אותן.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הונא מרב:\u0004"],["\u0003כלי שרת מהו שיעשו מקדשי בדק הבית?\u0004 וצדדי השאלה: \u0003צורך מזבח נינהו\u0004 \u0005[הם]\u0006 \u0003ו\u0004לכן \u0003מקדשי בדק הבית אתו\u0004 \u0005[באים],\u0006 \u0003או צורך קרבן נינהו\u0004 \u0005[הם],\u0006 \u0003ו\u0004לכן \u0003מתרומת הלשכה היו עושין אותן? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין נעשין אלא מתרומת הלשכה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו],\u0006 הלא נאמר על אלה שחיזקו את בדק הבית: \u0003\"וככלו‍תם הביאו לפני המלך ויהוידע (הכהן) את שאר הכסף ויעשהו כלים לבית ה' כלי שרת\"\u0004 (דברי הימים ב' כד, יד), משמע שכלי השרת נעשים מהכסף שהוקדש לבדק הבית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003דאקרייך כתובי\u0004 \u0005[מי שלימד אותך כתובים]\u0006 \u0003לא אקרייך נביאי\u0004 \u0005[לימד אותך נביאים],\u0006 ושכחת את הכתוב המקביל בנביאים, שנאמר \u0003\"אך לא יעשה בית ה' ספות\u0004 כסף מזמרות מזרקות חצוצרות כל כלי זהב וכלי כסף מן הכסף המובא בית ה'. \u0003כי לעשי המלאכה יתנהו\u0004 וחיזקו בו את בית ה'\u0003\"\u0004(מלכים ב יב, יד-טו), הרי שאת כלי השרת לא עשו מן הנדבה לבדק הבית.","ומקשים: \u0003אי הכי, קשו קראי אהדדי\u0004 \u0005[אם כך, קשים הכתובים זה על זה],\u0006 שבמקום אחד נאמר שעשו מכסף זה גם כלי שרת, ובמקום שני נאמר שהוא רק לעושי המלאכה לבדק הבית ממש! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן — שגבו והותירו,\u0004 ואז משתמשים בכסף הנותר לצורכי כלי שרת, \u0003כאן — שגבו ולא הותירו\u0004 ואז נותנים את הכסף כולו לבדק הבית.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003גבו והותירו מאי הוי\u0004 \u0005[מה יש],\u0006 הרי בסופו של דבר הכסף הוקדש לצורך אחר, ואם כלי שרת אינם נעשים מקדשי בדק הבית, כיצד אפשר להשתמש בו לכך? \u0003אמר ר' אבהו: לב בית דין מתנה עליהן\u0004 מתחילה, \u0003אם הוצרכו\u0004 לבדק הבית — \u0003הוצרכו, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003יהו\u0004 \u0005[יהיו]\u0006 \u0003ל\u0004צורך \u0003כלי שרת.\u0004","\u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כלי שרת באין מתרומת הלשכה, שנאמר: \"את שאר הכסף\"\u0004 (דברי הימים ב' כד, יד), \u0003איזהו כסף שיש לו שיריים — הוי אומר זה תרומת הלשכה.\u0004 שהדרך היתה שלאחר שמכניסים בלשכה את כסף השקלים היו תורמים ממנו תחילה חלק מסויים לצרכי הקרבנות, ועושים שימוש אחר בשיריים.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003שיריים גופייהו\u0004 \u0005[עצמם]\u0006 הם שיינתנו לצורך כלי שרת, ולא תרומת הלשכה? ונפרש \"שאר הכסף\" — הכסף שנשאר בלשכה לאחר תרומה! ומשיבים: \u0003כ\u0004מו ש\u0003אמר רבא\u0004 במקום אחר: \u0003\"העולה\"\u0004 כוונתו \u0003עולה ראשונה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003\"הכסף\"\u0004 — כוונתו \u0003כסף ראשון\u0004 של התרומה עצמה, ולא שייריה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה ששנינו: \u0003הקטורת וכל קרבנות צבור\u0004 — \u0003באין מתרומת הלשכה, מזבח הזהב ולבונה וכלי שרת — באין ממותר נסכים.\u0004","\u0003מזבח העולה, הלשכות והעזרות — באין מקדשי בדק הבית.\u0004 מה שבונים \u0003חוץ לחומת העזרה — באין משירי הלשכות. זו היא ששנינו: חומת העיר ומגדלותיה וכל צרכי העיר\u0004 בירושלים \u0003באין משירי הלשכה.\u0004 והרי זה חולק על מה שאמרנו בענין כלי שרת!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מותר תרומה,\u0004 אם נשאר כסף מהכספים של תרומת הלשכה בראש חודש ניסן שמכאן ואילך היו משתמשים רק בתרומה חדשה, \u0003מה היו עושין בה,\u0004 באותו מותר? היו עושים \u0003ריקועי זהב ציפוי לבית קדשי הקדשים, ר' ישמעאל אומר:\u0004 מותרות שונים הם, ולהם דינים שונים. \u0003מותר פירות — לקיץ המזבח,\u0004 שאם הזדמן שלא היו קרבנות על המזבח, היו מביאים עולות משל ציבור, שלא ישאר המזבח ריק. \u0003מותר תרומה — לכלי שרת.\u0004","\u0003ר' עקיבא אומר: מותר תרומה\u0004 — \u0003לקיץ המזבח, מותר נסכים\u0004 — \u0003לכלי שרת. ר' חנינא סגן הכהנים אומר: מותר נסכים\u0004 היה \u0003לקיץ המזבח, מותר תרומה לכלי שרת. וזה וזה,\u0004 גם ר' חנינא וגם ר' עקיבא \u0003לא היו מודים בפירות,\u0004 שלדעתם לא היה דבר כזה במקדש.","ושואלים: ובעצם \u0003\"פירות\" מאי היא\u0004 \u0005[מה הוא],\u0006 מה עניינם של פירות אלה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מותר תרומה מה היו עושין בה — לוקחין\u0004 (קונים) \u0003פירות בזול ומוכרין אותם ביוקר, והשכר\u0004 (והרווח) שהיה בא מכאן — \u0003מקיצין בו את המזבח. וזו היא ששנינו: מותר פירות\u0004 היה נעשה \u0003לקיץ המזבח.\u0004","ושואלים: אם כך \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 \u0003\"זה וזה לא היו מודין בפירות\"?\u0004 ומשיבים: ר' עקיבא לשיטתו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מותר שירי לשכה מה היו עושין בהן? לוקחין בהן יינות שמנים וסלתות, והשכר להקדש,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אין משתכרין\u0004 (עושים רווחים) \u0003בשל הקדש,\u0004 אפילו לצורכי המקדש ו\u0003אף לא בשל עניים.\u0004","ומסבירים את הטעם: \u0003בשל הקדש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 — לפי ש\u0003אין עניות במקום עשירות,\u0004 והמקדש צריך תמיד להיות ברווחה ובעושר, ואין מקום לעשיית רווחים קטנים כדרך עניים. \u0003בשל עניים מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 משתכרים — \u0003דלמא מתרמי להו עניא וליכא למיתבא ליה\u0004 \u0005[שמא יזדמן להם עני ולא יהיה לתת לו],\u0006 שכיון שהשקיעו את הכסף בעסק — אין מה לתת עכשיו לעני, הנזקק לכסף.","ומעתה חוזרים לפירושה של המשנה. שנינו בה: \u0003מי שהלך למדינת הים\u0004 ובאה אשתו ותבעה מזונות מבית דין, נחלקו תנאים מתי צריכה האשה להשבע שלא נטלה משל בעלה כלום. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה, \u0003רב אמר:\u0004"],["\u0003פוסקין מזונות לאשת איש,\u0004 כלומר, אם הלך הבעל למדינת הים ולא השאיר כסף לפרנסת אשתו, בית דין יורדים לנכסיו ומוציאים מהם דמי מזונות לאשתו. \u0003ושמואל אמר: אין פוסקין מזונות לאשת איש. אמר שמואל: מודה לי אבא\u0004 (רב, שזה היה שמו) \u0003בשלשה חדשים הראשונים\u0004 להליכתו, שאין יורדים לנכסיו לתת לאשתו מהם מזונות. ומדוע — \u0003לפי שאין אדם מניח ביתו ריקן,\u0004 אלא בודאי השאיר דבר מה שתוכל אשתו להתפרנס ממנו זמן קצר.","ומסבירים: \u0003בששמעו בו שמת\u0004 אותו אדם במדינת הים \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שיורדים לנכסיו. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה \u0003בשלא שמעו בו שמת.\u0004 וצדדי הבעיה הם, \u0003רב אמר: פוסקין, דהא\u0004 \u0005[שהרי]\u0006 הוא \u0003משועבד\u0004 לתת \u0003לה\u0004 את מזונותיה. \u0003ושמואל אמר: אין פוסקין.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של שמואל? \u0003רב זביד אמר: אימא צררי אתפסה\u0004 \u0005[אמור\u0006 ש\u0005צרורות,\u0006 כסף, \u0005התפיסה,\u0006 נתן לה בידה משלו\u0005]\u0006 לפני שיצא. \u0003רב פפא אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא אמר לה\u0004 קודם יציאתו \u0003\"צאי מעשה ידיך במזונותיך\",\u0004 שהוא מוותר על זכותו במעשה ידיה, ועליה לזון את עצמה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שני הטעמים הללו הלכה למעשה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 אם היתה האשה \u0003גדולה\u0004 (מבוגרת) שאפשר שנתן לה כסף, \u0003ולא ספקה\u0004 \u0005[ואינה\u0006 יכולה \u0005להסתפק]\u0006 במה שהיא מרויחה. שלדברי רב זביד שיש לשער שנתן לה כסף — אין נותנים לה מזונות, ולדברי רב פפא, כיון שאין מעשי ידיה מספיקים למזונותיה — יש לה מזונות.","ולהיפך: \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003קטנה וספקה\u0004 \u0005[ומסתפקת\u0006 במעשה ידיה\u0005],\u0006 שאין לחשוש שנתן לה כסף, אבל יש לחשוש שמא אמר לה שתיזון ממעשה ידיה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מי שהלך למדינת הים ואשתו תובעת מזונות, חנן אמר: תשבע בסוף,\u0004 שאם יתברר שמת בעלה והיא באה ליטול כתובתה, תשבע שלא השאיר לה בעלה כסף בצאתו, \u0003ולא תשבע בתחלה,\u0004 בשעה שתובעת את המזונות, כשיצא למדינת הים. \u0003נחלקו עליו בני כהנים גדולים ואמרו: תשבע בתחלה ובסוף.\u0004 ולענייננו, \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא לענין שבועה, אבל מזוני יהבינן\u0004 \u0005[מזונות נותנים אנו]\u0006 \u0003לה\u0004 לדעת הכל, וקשה אם כן על שיטת שמואל! \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003שמואל\u0004 לשיטתו: במשנה מדובר \u0003בששמעו בו שמת,\u0004 ולדעת כולם פוסקים לה.","ומקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא: \u0003מי שהלך למדינת הים ואשתו תובעת מזונות, בני כהנים גדולים אומרים: תשבע, חנן אומר: לא תשבע\u0004 ומקבלת בלא שבועה. \u0003ואם בא ואמר: פסקתי לה מזונות\u0004 והשארתי לה כסף די צורכה — \u0003נאמן\u0004 ועליה להחזיר לו את מה שקיבלה מנכסיו על ידי בית דין. ומכל מקום נראה שחלקו רק בענין השבועה, אבל על כך שנותנים לה מזונות אינם חולקים, וקשה אם כן לדברי שמואל!","ומתרץ: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בששמעו בו שמת.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אם בא ואמר\" קאמר\u0004 \u0005[אומר\u0006 התנא\u0005],\u0006 ומשמע שלא מת! ומתרצים: הכוונה היא \u0003אם בא לאחר שמועה,\u0004 שהיתה שמועה שמת, ולכן נתנו לה מזונות, ואחר כך משבא חזרה, התברר שלא היתה זו שמועת אמת.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מי שהלך למדינת הים ואשתו תובעת מזונות, ואם בא ואמר\u0004 שלפני צאתו אמר לה \u0003\"צאי מעשה ידיך במזונותיך\" — רשאי. קדמו בית דין ופסקו\u0004 לה מזונות — \u0003מה שפסקו פסקו,\u0004 ואינה צריכה להחזירם. וקשה אם כן לשמואל! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בששמעו בו שמת\u0004 ולכן פסקו לה מזונות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מי שהלך למדינת הים ואשתו תובעת מזונות — בית דין יורדים לנכסיו, וזנין ומפרנסין לאשתו, אבל לא\u0004 את \u0003בניו ובנותיו, ולא\u0004 נותנים לה \u0003דבר אחר,\u0004 וקשה לשמואל!","\u0003אמר רב ששת:\u0004 מדובר פה \u0003במשרה את אשתו על ידי שליש,\u0004 שגם בהיותו כאן לא היה נותן לה כסף במישרין, אלא היה אדם שלישי (שליש) שהיה ממונה לתת לה כסף לצרכיה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר שהיה לו אדם הממונה לכך, \u0003בניו ובנותיו נמי\u0004 \u0005[גם כן]\u0006 יקבלו מזונות! ומשיבים: \u0003כשהשרה\u0004 (מינה שליש) \u0003לזו,\u0004 לפרנסת אשתו, \u0003ולא השרה לזו,\u0004 למזונות בניו. ושואלים: \u0003מאי פסקא\u0004 \u0005[מה\u0006 הגורם שאתה \u0005פוסק]\u0006 חותך ומבדיל דווקא באופן זה?","\u0003אלא אמר רב פפא\u0004 לדחות בדרך אחרת: מדובר כאן \u0003כששמעה בו שמת\u0004 ושמועה זו היתה \u0003בעד אחד.\u0004 ולכן, \u0003היא,\u0004 האשה, \u0003דאי בעית אינסובי\u0004 \u0005[שאם היתה רוצה להינשא]\u0006 על פי עדות \u0003עד אחד מצי מינסבא\u0004 \u0005[היתה יכולה להינשא],\u0006 שמפני תקנת עגונות מקבלים חכמים עדות עד אחד על מות הבעל, ומתירים לה להינשא — \u0003מזוני נמי יהבינן\u0004 \u0005[מזונות גם כן נותנים אנו]\u0006 \u0003לה,\u0004 שהרי היתה יכולה גם לקבל כתובתה על פי עדות זו.","\u0003בניו ובנותיו דאי בעו למיחת\u0004 \u0005[שאם היו רוצים לרדת]\u0006 \u0003לנכסיו\u0004 ולרשת אותם על פי עדות \u0003עד אחד לא מצו נחתי\u0004 \u0005[היו יכולים לרדת],\u0006 שלענין ירושה צריכים שני עדים — \u0003מזוני נמי לא יהבינן להו\u0004 \u0005[מזונות גם כן אין אנו נותנים להם],\u0006 משום שמבחינתם אין עדיין עדות מספקת שאביהם מת.","אגב כך שואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דבר אחר\"\u0004 שהוזכר בברייתא שכאשר אין הבעל במקום אין נותנים לה אותו? \u0003רב חסדא אמר:\u0004 זהו \u0003תכשיט. רב יוסף אמר:\u0004 זהו כסף לצורך \u0003צדקה.\u0004 ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאין נותנים לה \u0003תכשיט, כל שכן\u0004 שהוא סבור"],["\u0003צדקה,\u0004 שאין בית דין פוסקים צדקה מנכסיו של אדם שלא מדעתו. אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאין נותנים לה לצורך \u0003צדקה — אבל\u0004 לדעתו \u0003תכשיט\u0004 כן \u0003יהבינן\u0004 \u0005[נותנים]\u0006 \u0003לה.\u0004 ומדוע — אנו מעריכים בדעתו ש\u0003לא ניחא ליה דתינוול\u0004 \u0005[נוח לו\u0006 לבעל \u0005שתתנוול\u0006 אשתו\u0005]\u0006 בהיעדר תכשיטים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003היבמה\u0004 שמת בעלה בלא בנים והיא ממתינה ליבם שייבם או יחלוץ לה — \u0003שלשה חדשים הראשונים\u0004 אחרי מות בעלה הריהי \u0003ניזונת משל בעלה,\u0004","\u0003מיכן\u0004 (מכאן) \u0003ואילך,\u0004 כל עוד לא התייבמה, \u0003אינה ניזונת לא משל בעלה ולא משל יבם. עמד\u0004 היבם \u0003בדין,\u0004 ופסקו בית דין שצריך לייבמה \u0003וברח — ניזונת משל יבם.\u0004 ומדין זה, אפשר להביא ראיה כנגד דברי שמואל, שהרי נותנים מזונות לאשה כאשר היבם (הקשור ומחוייב פחות מהבעל) ברח ואיננו כאן!","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך שמואל\u0004 שבמקרה זה גם הוא מודה שנותנים לה מזונות, כי \u0003למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה להאי\u0004 \u0005[לזו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 החשש שמא נתן לה היבם \u0003צררי\u0004 \u0005[כסף]\u0006 — הלא \u0003לא מיקרבא דעתיה לגבה\u0004 \u0005[קרובה דעתו\u0006 של היבם \u0005אליה]\u0006 עד כדי שישאיר לה כסף, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום מעשה ידיה\u0004 שאמר לה היבם \"צאי מעשה ידיך במזונותיך\" — הרי עדיין \u0003לא משתעבדא ליה\u0004 \u0005[אינה משועבדת לו]\u0006 במעשי ידיה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003האשה שהלכה היא ובעלה למדינת הים, ובאת\u0004 (באה) \u0003ואמרה \"מת בעלי\",\u0004 אם \u0003רצתה — ניזונת\u0004 מנכסיו, אם \u0003רצתה — גובה כתובתה.\u0004 אם אמרה \u0003\"גירשני בעלי\"\u0004 ואין בידה גט — הרי זו \u0003מתפרנסת והולכת\u0004 מהנכסים \u0003עד כדי\u0004 הסכום הקצוב ב\u0003כתובתה,\u0004 שכן אם נשואה היא — מגיעים לה מזונות, ואף אם גרושה היא — הריהי מקבלת כתובתה בדרך זו. והרי שיש לה מזונות, וקשה לדברי שמואל!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כששמעו בו שמת.\u0004 ושואלים: אם כן, \u0003ומאי שנא\u0004 \u0005[ומה שונה],\u0006 מדוע דווקא נותנים לה \u0003עד כדי כתובתה\u0004 ולא יותר? שאם שמעו בו שמת — יכולה היא להתפרנס מנכסיו עד שתינשא לאחר! ומשיבים: \u0003דאיהי\u0004 \u0005[שהיא]\u0006 \u0003היא דאפסידה אנפשה\u0004 \u0005[שהפסידה לעצמה],\u0006 שכיון שאמרה שגירשה — אין לה עוד מזונות.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כיצד אמרו\u0004 שה\u0003ממאנת אין לה מזונות? אי\u0004 \u0005[אין]\u0006 \u0003אתה יכול לומר\u0004 שמדובר \u0003ב\u0004קטנה ה\u0003יושבת תחת בעלה — שהרי בעלה חייב במזונות. אלא כגון שהלך בעלה למדינת הים,\u0004 ו\u0003לותה ואכלה\u0004 במשך הזמן ואחר כך \u0003עמדה ומיאנה\u0004 בו. ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003מיאנה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא מיאנה יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה,\u0004 ומשמע שמפרנסים את האשה כשהלך בעלה למדינת הים!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך שמואל: הכא למאי ניחוש\u0004 \u0005[כאן למה יש לחשוש]\u0006 \u0003לה? אי\u0004 \u0005[אם]\u0006 \u0003משום צררי\u0004 \u0005[כספים] —\u0006 \u0003צררי\u0004 \u0005[כספים]\u0006 \u0003לקטנה לא מתפיס\u0004 \u0005[איננו נותן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום מעשה ידיה — קטנה לא ספקה\u0004 \u0005[מספיק לה]\u0006 מעשה ידיה כדי לפרנסה. למחלוקת זו של רב ושמואל לא נמצא איפוא פתרון מוחלט גם לאחר הראיות המרובות שהובאו.","ושואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו, כיצד יש לפותרה למעשה? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: מעשה בא לפני רבי בבית שערים ופסק לה מזונות.\u0004 ובא מעשה דומה \u0003לפני ר' ישמעאל בצפורי ולא פסק לה מזונות. תהי\u0004 \u0005[תהה]\u0006 \u0003בה\u0004 בהלכה זו \u0003ר' יוחנן: וכי מה ראה ר' ישמעאל שלא פסק לה מזונות? הא\u0004 \u0005[הרי]\u0006 \u0003לא נחלקו בני כהנים גדולים וחנן\u0004 במשנתנו \u0003אלא לענין שבועה,\u0004 האם צריכה להישבע, \u0003אבל מזוני יהבינן\u0004 \u0005[מזונות נותנים אנו]\u0006 \u0003לה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמן בר אבא: כבר תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003רבינו שמואל בבבל:\u0004 המדובר הוא \u0003כששמעו בו שמת. אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בהתפעלות: כבר \u0003פתריתו\u0004 \u0005[פתרתם,\u0006 תירצתם\u0005]\u0006 \u0003בה כולי האי\u0004 \u0005[כל זה]?\u0006 לא ידעתי שנכנסתם כל כך לעומק הסוגיה, לפתור ולתרץ בעיה זו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, מסר את השמועה, באופן אחר וכך \u0003אמר: מעשה בא לפני רבי בבית שערים ולא פסק לה מזונות.\u0004 ומעשה בא \u0003לפני ר' ישמעאל בציפורי ופסק לה מזונות. אמר ר' יוחנן: מה ראה רבי שלא פסק לה? דהא\u0004 \u0005[שהרי]\u0006 \u0003לא נחלקו חנן ובני כהנים גדולים אלא לענין שבועה, אבל מזונות יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמן בר אבא: כבר תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003שמואל בבבל — כששמעו בו שמת. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פתריתו\u0004 \u0005[פתרתם,\u0006 תירצתם\u0005]\u0006 \u0003בה כולי האי\u0004 \u0005[כל זה]?\u0006","ומסכמים: \u0003והלכתא כותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב ופוסקין מזונות לאשת איש\u0004 שהלך בעלה למדינת הים. ואגב פסק זה מביאים עוד כמה פסקי הלכה: \u0003והלכתא כותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: יכולה אשה שתאמר לבעלה \"איני ניזונת ואיני עושה\",\u0004 שאין תקנת חכמים במזונות אלא לטובת האשה, והיא יכולה לוותר על כך.","\u0003והלכתא כותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב זביד בקוניא\u0004 (בזיגוג), ש\u0003אמר רב זביד: הני מאני\u0004 \u0005[אותם כלי]\u0006 \u0003קוניא,\u0004 שהם כלי חרס המכוסים בזיגוג באופנים שונים, שיש מהם הבולעים מהמאכל המבושל בהם, ונאסרים כאשר בולעים דבר איסור, כיין נסך, חמץ בפסח, או מאכלות אסורות — \u0003חיורי ואוכמי שרו\u0004 \u0005[לבנים ושחורים מותרים],\u0006 שהזיגוג גורם שלא ייבלע בהם דבר איסור שהיה בתוכם, ולאחר שטיפה מותרים, ואינם ככלי חרס שאסורים לעולם.","\u0003ירוקין אסירי\u0004 \u0005[ירוקים אסורים],\u0006 לפי שהם בולעים. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה שהלבנים והשחורים מותרים \u0003אלא דלית בהו קרטופני\u0004 \u0005[שאין בהן סדקים],\u0006 \u0003אבל\u0004 אם \u0003אית בהו קרטופני\u0004 \u0005[יש בהם סדקים] —\u0006 \u0003אסירי\u0004 \u0005[אסורים]\u0006 גם אלה, שהאיסור נבלע בחרס עצמו דרך סדקים אלה.","\u0003מי שהלך למדינת הים, ועמד אחד ופירנס את אשתו\u0004 במשך אותו הזמן, וכשחזר הבעל הוא תובע ממנו את הכסף שהוציא על אשתו. \u0003חנן אומר: איבד את מעותיו\u0004 כלומר, הבעל אינו חייב לשלם, שהרי עשה זאת אותו אדם מדעתו, ולא על פי בקשת הבעל.","\u0003נחלקו עליו בני כהנים גדולים ואמרו: ישבע\u0004 אותו האיש \u0003כמה הוציא\u0004 עבור האשה \u0003ויטול. אמר ר' דוסא בן הרכינס כדבריהם. אמר ר' יוחנן בן זכאי: יפה אמר חנן\u0004 במקרה זה, \u0003הניח מעותיו על קרן הצבי,\u0004 שהריהו כמניח את מעותיו על קרן של צבי הבורח לו למקום אחר.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003המודר הנאה מחבירו,\u0004 שנדר שלא יהנה חבירו ממנו —"],["\u0003שוקל לו את שקלו,\u0004 שמותר לו לתת עבור חבר זה את מחצית השקל למקדש מכספו, \u0003ופורע\u0004 לו \u0003את חובו,\u0004 שאם המודר חייב ממון יכול חבירו לפרוע לו, \u0003ומחזיר לו אבידתו. ובמקום שנוטלין שכר\u0004 על השבת אבידה — \u0003תפול הנאה\u0004 שמשלמים עבור ההשבה \u0003להקדש.\u0004","ודנים בדבר, \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה ש\u0003שוקל לו את שקלו — מצוה קעביד\u0004 \u0005[\u0006הוא \u0005עושה\u0006 בכך\u0005],\u0006 אבל אין זו הנאה ישירה לזה שנתן עבורו, שגם אם לא היה נותן כלל, אינו מפסיד, שכל אדם מישראל גם אם אינו נותן שקל יש לו חלק בקרבנות הציבור. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003תורמין\u0004 כאשר מוציאים הגזברים את השקלים שבלשכה לצורך קרבנות הציבור, לא רק עבור אלה ששקליהם מצויים שם, אלא גם \u0003על האבוד\u0004 (ששקלו נאבד) \u0003ועל הגבוי\u0004 כבר אלא שעדיין לא הגיע שקלו למקדש, \u0003ועל העתיד לגבות\u0004 גם אם לא ייגבה בפועל. וכיון שכך, בעצם לא גרם לו כל הנאה.","\u0003ומחזיר לו אבידתו — נמי\u0004 \u0005[גם כן]\u0006 \u0003מצוה קעביד\u0004 \u0005[הוא\u0006 \u0005עושה]\u0006 בהשבת האבידה. \u0003אלא\u0004 יש לתמוה על \u0003פורע לו את חובו, הא קמשתרשי ליה\u0004 \u0005[הרי\u0006 הוא \u0005מרויח לו],\u0006 שלולא פרע את חובו היה החבר צריך לשלם משלו, והרי זה כאילו נתן לחבר כסף!","\u0003אמר רב אושעיא: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003חנן היא\u0004 ש\u0003אמר\u0004 במשנתנו: \u0003איבד את מעותיו.\u0004 שכאן מדובר בחוב כגון זה, שאדם פורע חוב עבור חבירו כאשר החייב יכול שלא לפרעו כלל. ונמצא שההנאה היא למלווה ולא לחייב.","\u0003ורבא אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 כדעת \u0005חכמים],\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן, במה אנו עוסקים],\u0006 כגון \u0003שלוה\u0004 אותו חבר \u0003על מנת שלא\u0004 יצטרך \u0003לפרוע,\u0004 אלא כשירצה — יפרע. ובמקרה כזה אם מודר הנאה פרע — הרי עשה טובה למלווה, אבל הלווה לא נהנה מכך.","ומפרשים את ההסברים הללו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רבא לא אמר כרב אושעיא\u0004 בפירוש המשנה בנדרים — יש לו טעם לדבר: \u0003דמוקים לה כרבנן\u0004 \u0005[ש\u0006הוא \u0005מעמיד\u0006 לפי זה \u0005אותה,\u0006 את המשנה, \u0005כ\u0006דעת \u0005חכמים]\u0006 ולא רק כרב חנן. \u0003אלא רב אושעיא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבא\u0004 שמדובר בהלוואה שלא על מנת לפרוע? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב אושעיא:\u0004 בהלוואה שכזו \u0003נהי\u0004 \u0005[\u0006אם \u0005אמנם]\u0006 ש\u0003הנאה לית ליה\u0004 \u0005[אין לו]\u0006 ללווה, שהרי אינו חייב לפרוע חובו בזמן מסויים, מכל מקום"],["\u0003כיסופא מי לית ליה\u0004 \u0005[בושה האם אין לו]\u0006 ללווה שאינו פורע? \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 לענין מודר הנאה \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003הנאה בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה דמיכסיף מיניה\u0004 \u0005[ש\u0006הוא \u0005מתבייש ממנו].\u0006","\u0003אדמון אומר שבעה\u0004 דברים שחלקו חכמים עליהם: \u0003מי שמת והניח בנים ובנות, בזמן שהנכסים מרובין — הבנים יורשים\u0004 את נכסיו \u0003והבנות נזונות\u0004 מהם. \u0003ובנכסים מועטים\u0004 שאינם מספיקים לבנים ולבנות — \u0003הבנות יזונו, והבנים\u0004 שאין להם לא ירושה ולא מזונות, אם אין להם פרנסה — \u0003יחזרו על הפתחים. אדמון אומר: בשביל שאני זכר הפסדתי?! אמר רבן גמליאל: רואה\u0004 (מקבל, מסכים) \u0003אני את דברי אדמון.\u0004","על דברי אדמון \"בשביל שאני זכר הפסדתי\" שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה משמעו של טיעון זה \"שאני זכר\"? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003בשביל שאני זכר וראוי לעסוק בתורה\u0004 שלא כבנות — \u0003הפסדתי?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 וכי \u0003מאן דעסיק\u0004 \u0005[מי שעוסק]\u0006 \u0003בתורה הוא דירית\u0004 \u0005[שיורש],\u0006 ואילו \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003לא עסיק\u0004 \u0005[עוסק]\u0006 \u0003בתורה לא ירית\u0004 \u0005[יורש]?!\u0006 ומה ענין תלמוד תורה לכאן! \u0003אלא אמר רבא: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003בשביל שאני זכר\u0004 ויש לי מן התורה זכות מרובה בנכסים \u0003וראוי לירש בנכסים מרובין — הפסדתי\u0004 לגמרי \u0003בנכסים מועטין?!\u0004","ועוד מדברי אדמון: \u0003הטוען את חבירו\u0004 שהוא חייב לו \u0003כדי שמן, והודה\u0004 החבר \u0003בקנקנים\u0004 בלבד. \u0003אדמון אומר: הואיל והודה במקצת הטענה — ישבע. וחכמים אומרים: אין הודאת\u0004 ה\u0003מקצת\u0004 שהודה \u0003ממין הטענה,\u0004 שהרי זה טען שמן, וזה הודה בקנקנים. \u0003אמר רבן גמליאל: רואה אני את דברי אדמון.\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003טענו חטין ושעורין והודה\u0004 החבר \u0003בשעורין\u0004 בלבד — \u0003פטור.\u0004 וכן כאן תבע אותו כדי שמן, והודה לו רק בכדים.","אם כן \u0003לימא תהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על דברי \u0003רב נחמן אמר שמואל, שאמר רב נחמן אמר שמואל: טענו חטין ושעורים והודה לו באחד מהן — חייב\u0004 שבועה, לפי שהודה במקצת הטענה!","\u0003אמר רב יהודה אמר רב:\u0004 במשנה מדובר לא כשטען החבר שחייב לו שמן וקנקנים, אלא \u0003בטוענו מדה,\u0004 שאמר לו, כמות של כך וכך כדי שמן אתה חייב לי ונמצא שאין זו הודאה ממין הטענה כלל. ושואלים: \u0003אי הכי, מאי טעמא\u0004 \u0005[אם כך, מה הטעם]\u0006 של \u0003אדמון\u0004 המצריך שבועת הודאה במקצת? שהרי ודאי אין ההודאה ממין הטענה!","\u0003אלא אמר רבא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"מלא עשרה כדי שמן יש לי בבורך\",\u0004 במקרה זה ודאי \u0003שמן קטעין ליה\u0004 \u0005[טוען לו,\u0006 עליו\u0005],\u0006 \u0003קנקנים לא קטעין ליה\u0004 \u0005[טוען לו,\u0006 עליו\u0005]\u0006 כלל ולדעת הכל אין ההודאה בקנקנים הודאה במקצת להתחייב עליה שבועה. אם אמר לו \u0003\"עשרה כדי שמן מלאים יש לי אצלך\"\u0004 במקרה זה — \u0003שמן וקנקנים קטעין ליה\u0004 \u0005[טוען לו,\u0006 עליו\u0005],\u0006 וכאשר מודה בקנקנים נמצא שהודה במקצת הטענה, ואף בכך הכל מודים שנשבע.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 במשנה, הוא \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"עשרה כדי שמן יש לי אצלך\". אדמון אומר: יש בלשון הזה\u0004 גם \u0003לשון קנקנים, ורבנן סברי\u0004 \u0005[סבורים]:\u0006 \u0003אין בלשון הזה לשון קנקנים.\u0004","ומדייקים: \u0003אלא טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 ש\u0003אין בלשון הזה לשון קנקנים, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש בלשון הזה לשון קנקנים\u0004 — היה \u0003חייב\u0004 שבועה. אם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ר' חייא בר אבא,\u0004 ש\u0003אמר ר' חייא בר אבא: טענו חטין ושעורים והודה לו באחד מהם — פטור,\u0004 ולפי מה שפירשנו במשנה הכל מודים שחייב!","\u0003אמר רב שימי בר אשי:\u0004 המקרה במשנה אינו דומה לחיטים ושעורים שאין ביניהם כל קשר וממילא אינו כמודה במקצת הטענה, כי במשנתנו \u0003נעשה כמי שטענו רימון בקליפתו,\u0004 שאם הוא טוען לכדי שמן, הרי אין השמן מצוי בלא הכדים, כמו הרימון וקליפתו, ונחשב כדבר אחד. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא:\u0004 אין כאן דמיון, כי \u0003רימון בלא קליפתו לא מינטר\u0004 \u0005[אינו נשמר]\u0006 וממילא מובן כי כאשר טוענו רימון — רימון בקליפתו הוא טוען. אבל \u0003שמן מינטר\u0004 \u0005[נשמר]\u0006 \u0003בלא קנקנים\u0004 בכלי קיבול אחרים!","\u0003אלא\u0004 יש להסביר את משנתנו לשיטת ר' חייא בדרך אחרת: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"עשרה כדי שמן יש לי אצלך\", ואמר ליה אידך\u0004 \u0005[לו האחר]\u0006 \u0003\"שמן — לא היו דברים מעולם,\u0004 לא לויתי אצלך כלל, \u0003קנקנים נמי\u0004 \u0005[גם כן] —\u0006 \u0003חמשה אית\u0004 \u0005[יש]\u0006 \u0003לך\u0004 אצלי שבהם אני מודה שלקחתי, \u0003וחמשה לית\u0004 \u0005[אין]\u0006 \u0003לך.\u0004","\u0003אדמון אומר: יש בלשון הזה\u0004 של תביעתו \u0003לשון קנקנים, ומגו דקמשתבע\u0004 \u0005[ומתוך שנשבע]\u0006 על ה\u0003קנקנים\u0004 שהודה במקצתם, \u0003משתבע נמי\u0004 \u0005[נשבע גם כן]\u0006 על ה\u0003שמן על ידי גלגול\u0004 השבועה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סוברים]:\u0006 \u0003אין בלשון הזה\u0004 כלל \u0003לשון קנקנים.\u0004 ואם כן נמצא ש\u0003מה שטענו — לא הודה לו,\u0004 שעל השמן כפר לו, \u0003ומה שהודה לו\u0004 במקצת הקנקנים — \u0003לא טענו,\u0004 ואינו חייב אם כן שבועה כל עיקר.","ועוד מדברי אדמון: \u0003הפוסק מעות לחתנו\u0004 בנדוניה, \u0003ופשט לו את הרגל,\u0004 כלומר, אמר לו שאינו יכול לעמוד בהתחייבותו משום שאין לו ממון —"],["\u0003תשב\u0004 הארוסה \u0003עד שתלבין ראשה.\u0004 שאם החתן איננו רוצה לשאת אותה בלא נדוניה — הרשות בידו שלא לשאתה, שהרי האב לא קיים את התנאי. \u0003אדמון אומר: יכולה היא שתאמר: \"אילו אני פסקתי לעצמי\u0004 ולא עמדתי בתנאי — \u0003אשב עד שתלבין ראשי, עכשיו שאבא פסק — מה אני יכולה לעשות? או כנוס\u0004 (שא אותי לאשה), \u0003או פטור\u0004 אותי בגט \u0003\". אמר רבן גמליאל: רואה אני את דברי אדמון.\u0004","\u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו אינה כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי בר' יהודה: לא נחלקו אדמון וחכמים על הפוסק מעות לחתנו ופשט לו את הרגל, שיכולה היא שתאמר: \"אבא פסק עלי, מה אני יכולה לעשות\".\u0004","\u0003על מה נחלקו — על שפסקה היא על עצמה. שחכמים אומרים: תשב עד שתלבין ראשה,\u0004 שהרי לא קיימה את תנאה, \u0003אדמון אומר: יכולה היא שתאמר: כסבורה אני שאבא נותן עלי, ועכשיו שאין אבא נותן עלי — מה אני יכולה לעשות? או כנוס או פטור.\u0004 ועל כך \u0003אמר רבן גמליאל: רואה אני את דברי אדמון.\u0004 שמכיון שלארוסה אין ממון משל עצמה, מן הסתם על אביה סמכה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003במה דברים אמורים — בגדולה, אבל בקטנה כופין.\u0004 ושואלים: \u0003כופין למאן\u0004 \u0005[כופים את מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכופים \u0003לאב\u0004 שישלם — \u0003איפכא מיבעי ליה\u0004 \u0005[ההיפך צריך להיות]\u0006 שבגדולה שתנאה יש בו ממש צריך לכפותו, בקטנה שאין בה דעת לעשות תנאי — לא! \u0003אלא אמר רבא: כופין לבעל ליתן גט\u0004 או לכנוס.","\u0003אמר ר' יצחק בן אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה: כל מקום שאמר רבן גמליאל \"רואה אני את דברי אדמון\" — הלכה כמותו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 האם זה פסק ההלכה \u0003אפילו\u0004 כשנחלקו \u0003בברייתא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי קאמרינן\u0004 \u0005[האם אמרנו]\u0006 כל מקום שאמר \u0003במשנה?\u0004 — \u0003בכל מקום שאמר רבן גמליאל קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ואפילו בברייתא.","\u0003אמר ר' זירא אמר רבה בר ירמיה: שני דברים שאמר חנן — הלכה כיוצא בו, שבעה דברים שאמר אדמון — אין הלכה כיוצא בו.\u0004 ודנים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה משמעות פסק זה?","\u0003אילימא הכי קאמר\u0004 \u0005[אם תאמר\u0006 ש\u0005כך אמר]:\u0006 \u0003שני דברים שאמר חנן הלכה כמותו וכיוצא בו\u0004 גם בדברים הדומים לכך \u0003ושבעה דברים שאמר אדמון אין הלכה כמותו ולא כיוצא בו.\u0004 אולם \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק בן אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה: כל מקום שאמר רבן גמליאל \"רואה אני את דברי אדמון\" הלכה כמותו!\u0004","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003שני דברים שאמר חנן — הלכה כמותו וכיוצא בו, שבעה דברים שאמר אדמון — אין הלכה כיוצא בו\u0004 (בדברים דומים לכך) \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כמותו — הלכה\u0004 כשיטתו \u0003בכולהו\u0004 \u0005[בכולם].\u0006","אולם גם פירוש זה קשה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק בן אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה: כל מקום שאמר רבן גמליאל \"רואה אני את דברי אדמון\" — הלכה כמותו,\u0004 ומכאן שאם \u0003אמר\u0004 רבן גמליאל שהלכה כמותו — \u0003אין\u0004 \u0005[כן\u0006 היא\u0005],\u0006 \u0003לא אמר — לא,\u0004 ואין הלכה כמותו!","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003שני דברים שאמר חנן — הלכה כמותו וכיוצא בו, שבעה דברים שאמר אדמון — יש מהן שהלכה כמותו וכיוצא בו, ויש מהן שאין הלכה כמותו אלא כיוצא בו.\u0004","ומתי, \u0003בכל מקום שאמר רבן גמליאל רואה אני את דברי אדמון — הלכה כמותו, אינך\u0004 \u0005[האחרים] —\u0006 \u0003לא.\u0004","\u0003העורר על השדה,\u0004 שטוען ששדה שאדם מסויים קנה ומחזיק בו הריהו שלו, \u0003והוא,\u0004 העורר עצמו, \u0003חתום עליה\u0004 על מכירת שדה זה לאותו אדם שמחזיק בו \u0003בעד\u0004 — \u0003אדמון אומר:\u0004 אין זו הוכחה שבעדותו בשטר המכר הודה גם על בעלות השדה, אלא יש לומר כי העורר הזה אומר בלבו: \u0003השני נוח לי,\u0004 שאני יכול להתדיין איתו, \u0003והראשון\u0004 שמכרה לשני \u0003קשה הימנו,\u0004 כגון שהוא אדם אלים, ולכן לא ערערתי קודם כשהשדה היה בידו, ואף חתמתי על שטר המכירה.","\u0003וחכמים אומרים: איבד את זכותו,\u0004 שכיון שחתם על שטר המכר של אותו שדה ונאמר בשטר שהוא של המחזיק בו — מוכח שויתר על זכותו. אם \u0003עשאה סימן לאחר,\u0004 שאותו עורר כתב שטר על שדה אחר, ובאותו שטר הזכיר כסימן שדה זה כשייך לפלוני — לכל הדעות \u0003איבד את זכותו\u0004 שמוכח מכאן שמודה שהשדה שייך לאותו אדם.","\u0003אמר אביי: לא שנו\u0004 מחלוקת זו \u0003אלא\u0004 לגבי \u0003עד\u0004 שחתם על שטר המכר, \u0003אבל דיין\u0004 שהיה עורר על בעלות שדה, שישב במושב בית דין ואישר את שטר המכר של השדה שהוא עורר עליו — \u0003לא איבד את זכותו. דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: אין העדים חותמין על השטר אלא אם כן קראוהו,\u0004 ולכן כאשר חותם העד על השטר אינו יכול לומר שבא לאשר רק חלק מסויים בו, אלא מניחים שקרא והודה על כל מה שכתוב בשטר."],["\u0003אבל הדיינין חותמים\u0004 על שטר \u0003אף על פי שלא קראוהו,\u0004 שאין הם באים אלא לאשר את חתימת העדים, ואינם מתייחסים למה שכתוב בגוף השטר, ויתכן איפוא שחתמו על השטר בלא לדעת מה תוכנו.","שנינו במשנה שאם \u0003עשאה\u0004 לשדה זו שמערער עליה כ\u0003סימן לאחר\u0004 — איבד זכותו. \u0003אמר אביי: לא שנו אלא לאחר,\u0004 בשטר שאינו נוגע לזה שהוא מערער על זכותו, \u0003אבל\u0004 אם עשה זאת סימן \u0003לעצמו,\u0004 שקנה שדה אחר מאותו אדם — \u0003לא איבד את זכותו.\u0004","\u0003דאמר\u0004 \u0005[\u0006שיכול הוא \u0005לומר]:\u0006 \u0003אי דלא עבדי ליה הכי\u0004 \u0005[אם לא הייתי עושה לו כך]\u0006 וכותב שהשדה שלו \u0003לא הוה מזבין לה ניהלי\u0004 \u0005[היה מוכר לי את\u0006 השדה האחר\u0005],\u0006 \u0003מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]?\u0006 כי \u0003איבעי לי למימסר מודעא\u0004 \u0005[הייתי צריך למסור מודעה]\u0006 ולהודיע בפני עדים שמה שאני כותב — באונס אני עושה — חששתי לעשות כן, כי \u0003חברך חברא אית ליה, וחברא דחברך חברא אית ליה\u0004 \u0005[חברך חבר יש לו, וחבר של חברך חבר יש לו]\u0006 ולבסוף דבר כזה מתפרסם ברבים ויגיע גם אל בעל השדה ולא ירצה למכור לי.","\u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003עשאה\u0004 לשדה מסויים \u0003סימן לאחר, ערער\u0004 אחר כך וטען לבעלות על אותו השדה שעשאו סימן, \u0003ושכיב\u0004 \u0005[ומת],\u0006 \u0003ואוקים אפוטרופא\u0004 \u0005[והעמיד\u0006 קודם מותו \u0005אפוטרופוס]\u0006 שיטפל בנכסי יתומיו. \u0003אתא\u0004 \u0005[בא]\u0006 ה\u0003אפוטרופוס לקמיה\u0004 \u0005[לפני]\u0006 \u0003אביי. אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003עשאה סימן לאחר — איבד את זכותו,\u0004 ואין מקום לערעור.","\u0003אמר\u0004 האפוטרופוס: \u0003אי הוה אבוהון דיתמי\u0004 \u0005[אם היה אביהם של היתומים]\u0006 \u0003קיים, הוה טעין ואמר\u0004 \u0005[היה טוען ואומר]\u0006 כך: \u0003\"תלם אחד עשיתי לך\",\u0004 שסימן זה שעשיתי ששדה פלוני גובל בשדה שלו — לא התכוונתי לכל השדה כולו, אלא לתלם שבקצהו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003שפיר קאמרת\u0004 \u0005[יפה אתה אומר],\u0006 ומתקבלת טענתך. ש\u0003אמר ר' יוחנן, אם טען ואמר \"תלם אחד עשיתי לך\" — נאמן.\u0004 מכל מקום \u0003זיל הב ליה מיהת\u0004 \u0005[לך תן לו בכל אופן]\u0006 \u0003תלם אחד\u0004 שבו אתה מודה שהוא שייך למחזיק בשדה.","\u0003הוה עלה ריכבא דדיקלי\u0004 \u0005[היתה עליו,\u0006 על אותו תלם, \u0005שורת דקלים]\u0006 ולא רצה האפוטרופוס לוותר עליה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 האפוטרופוס לאביי: \u0003אי הוה אבוהון דיתמי\u0004 \u0005[אם היה אביהם של היתומים]\u0006 \u0003קיים, הוה טעין ואמר\u0004 \u0005[היה טוען ואומר]\u0006 \"באמת מכרתי לו, אבל \u0003חזרתי ולקחתי\u0004 (קניתי) \u0003ממנו\u0004 את השדה לאחר זמן\". \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שפיר קאמרת\u0004 \u0005[יפה אתה אומר].\u0006 ש\u0003אמר ר' יוחנן: אם טען ואמר \"חזרתי ולקחתיו ממנו\" — נאמן.\u0004 לאחר שזכה האפוטרופוס בכל התביעה \u0003אמר אביי: האי מאן דמוקים אפוטרופא\u0004 \u0005[מי שמעמיד אפוטרופוס] —\u0006 \u0003נוקים כי האי, דידע לאפוכי בזכותא דיתמי\u0004 \u0005[שיעמיד כמו זה, שיודע להפוך בזכות היתומים]\u0006 ולטעון עבורם כראוי.","\u0003מי שהלך למדינת הים ו\u0004בתוך הזמן ששהה שם \u0003אבדה דרך שדהו,\u0004 שאותו שביל שהיה רגיל ללכת בו נחרש בינתיים על ידי בעל השדה שהיה בו השביל, ולא ידוע היכן הוא. \u0003אדמון אומר: ילך לו\u0004 אל שדהו \u0003בקצרה\u0004 שבדרכים. \u0003וחכמים אומרים: יקנה לו דרך\u0004 מבעל אחד השדות הסמוכים בכל סכום שהוא, אפילו \u0003במאה מנה, או יפרח באויר.\u0004","שואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 שאין מקצים לו דרך, הלא \u0003שפיר קאמר\u0004 \u0005[יפה אומר]\u0006 \u0003אדמון\u0004 שהרי ברור שהיתה לו שם דרך! \u0003אמר רב יהודה אמר רב:\u0004 כאן מדובר \u0003כגון שהקיפוה ארבעה בני אדם מארבע רוחותיה,\u0004 שכל אחד מהשדות הגובלים שייך לאדם אחר. וכל אחד מהם אומר: לא אצלי היתה הדרך, אלא אצל האחר. וכיון שאינו יכול להוכיח את טענתו — ממילא חייב הוא לקנות לו דרך, שהמוציא מחבירו עליו מוטלת חובת הראיה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היה מעשה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003אדמון?\u0004","\u0003אמר רבא: בארבעה\u0004 בעלי שדות \u0003דאתו\u0004 \u0005[שבאים]\u0006 \u0003מכח ארבעה\u0004 שקדמו להם, שהשדות היו שייכים תחילה לארבעה אנשים שונים, או \u0003ארבעה דאתו\u0004 \u0005[שבאו]\u0006 \u0003מכח חד\u0004 \u0005[אחד],\u0006 שקודם היו כל השדות שייכים לאחד, וקנו אותם ארבעה אנשים שונים — \u0003כולי עלמא לא פליגי דמצי מדחי ליה\u0004 \u0005[הכל אינם חלוקים שיכולים לדחות אותו],\u0006 שכל אחד יאמר: לא אצלי היתה הדרך. \u0003כי פליגי בחד דאתי\u0004 \u0005[כאשר נחלקו\u0006 הוא כאשר היה מחזיק השדות \u0005אחד שבא]\u0006 \u0003מכח ארבעה\u0004 אנשים שונים.","\u0003אדמון סבר\u0004 \u0005[סבור]\u0006 שיכול לומר לו: \u0003מכל מקום\u0004 (בכל אופן) \u0003דרכא אית\u0004 \u0005[דרך יש]\u0006 \u0003לי גבך\u0004 \u0005[אצלך],\u0006 ואף שאין בידו להוכיח היכן היתה, מכל מקום ודאי שהיא בתחומו של האיש ששדותיו גובלים בשדהו ולכן הוא לוקח את הקצרה שבהן. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 שיכול בעל השדות לומר: \u0003אי שתקת\u0004 \u0005[אם תשתוק] —\u0006 \u0003שתקת\u0004 \u0005[תשתוק]\u0006 ונתפשר, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תשתוק — \u0003מהדרנא שטרא למרייהו\u0004 \u0005[אחזיר את השטרות לבעליהם]\u0006 \u0003ולא מצית לאשתעויי דינא בהדייהו\u0004 \u0005[תוכל לדון איתם]\u0006 שהרי הם ארבעה והם יסלקו אותך בטענותיהם.","מסופר: \u0003ההוא\u0004 \u0005[\u0006שכיב מרע \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לסובבים אותו, בצוואתו: \u0003דיקלא לברת\u0004 \u0005[דקל\u0006 אני מוריש \u0005לבתי].\u0006 \u0003אזול יתמי פלוג לנכסי\u0004 \u0005[הלכו היתומים, וחילקו את הנכסים]\u0006 ו\u0003לא יהבו\u0004 \u0005[נתנו]\u0006 \u0003לה דיקלא\u0004 \u0005[דקל\u0006 כלל\u0005].\u0006 \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו מתניתין\u0004 \u0005[זוהי משנתנו],\u0006 שכל אחד מן היורשים יכול לומר לה: הדקל השייך לך — לא אצלי הוא, אלא אצל יורש אחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003כל חד וחד מצי מדחי ליה\u0004 \u0005[אחד ואחד יכול לדחות אותו]\u0006 ולומר אין לי כל קשר עם הדרך שלך ולא היתה דרך זו מעולם על הקרקע שלי, ואולם \u0003הכא דיקלא גבייהו\u0004 \u0005[כאן הדקל\u0006 ודאי \u0005אצלם]\u0006 \u0003הוא,\u0004 שהיתה על כולם חובה לתת לה דקל זה, וכל אחד מחזיק איפוא בחלק זה שלא כדין. \u0003מאי תקנתייהו\u0004 \u0005[מה תקנתם]?\u0006 \u0003ליתבו\u0004 \u0005[שיתנו]\u0006 \u0003לה דיקלא\u0004 \u0005[דקל]\u0006 \u0003וליהדרו וליפלגו מרישא\u0004 \u0005[ויחזרו ויחלקו מתחילה],\u0006 שהרי כיון שנוטלת את הדקל מחלקו של אחד מהם צריכים הם להתחלק מחדש.","\u0003ההוא\u0004 ש\u0003אמר להו\u0004 \u0005[להם],\u0006 לסובבים אותו בצוואתו: \u0003דיקלא לברת\u0004 \u0005[דקל\u0006 אני מוריש \u0005לבתי].\u0006 \u0003שכיב ושביק תרי פלגי דדיקלא\u0004 \u0005[מת והניח שני חצאי דקל],\u0006 שהיתה לו שותפות בשני דקלים, ושני החלקים יחד הם כדקל אחד, ורצו היורשים לתת לבת שני חצאים אלה שיש טירחה יתירה בטיפול בהם.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אשי וקא קשיא ליה\u0004 \u0005[והיה קשה לו]\u0006 \u0003מי קרו אינשי לתרי פלגי דיקלי דיקלא\u0004 \u0005[האם קוראים לשני חצאי דקל, דקל],\u0006 \u0003או לא?\u0004 והאם אפשר לפרש כך את דברי המת, וידה על התחתונה שהרי היא כמוציאה מן היורשים, או שמא אין זה קרוי דקל, והם צריכים לתת לה דקל אחד שלם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 רב \u0003אבימי מהגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: קרו אינשי לתרי פלגי דיקלי דיקלא\u0004 \u0005[קוראים אנשים לשני חצאי דקל דקל]\u0006 ואם כן, רשאים לתת לה את שני החצאים."]]};
